{"assumptions":[],"created_at":"2026-10-26T19:26:17.756598+00:00","domain":"probability theory","id":"claim_9552b02a1e3d83ece6dc06b284272e64896f2ceaf67999e05c63fc9c6473b439","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2511.04938, 'Uniform dimension theorems for parabolic SPDEs'] Let $\{Z(s)\}_{s\in I}$ be an $\R^p$-valued random field, where 
	$I \subset \R^N$ is a non-random, compact, upright rectangle. 
	Let $\mathsf{d}$, $\mathcal{N}_n^\delta(\nu\,,r)$, and $F_n^\delta$ be as defined
	in Lemma \ref{lem:unif:dim2}, and suppose that the following two conditions hold:
	\begin{compactenum}[(i)]
		\item The following is finite for some $c>0$ and $\gamma>0$:
		\begin{align}
			\mathcal{E}_1 := \E\left[ \exp\left( c \sup_{\substack{s,s'\in I\\ s\ne s'}}
			\left[\frac{\|Z(s)-Z(s')\|}{\mathsf{d}(s\,,s')\left| 
			\log_+ (1/\mathsf{d}(s\,,s'))\right|^{1/2}}
			\right]^\gamma \right) \right];
		\end{align}
		\item For every $\delta\in(0\,,1)$, there exist $a,b>0$ and $\kappa>0$ such that
		\begin{align}
			\P\left\{ \mathcal{N}_n^\delta(\nu\,,2^{-n}) \ge 2^{an} \right\}
			\le b 2^{-\kappa n^2}
			\quad\text{$\forall n\in\N$, $s\in I$, $\nu \in \R^p$}.
		\end{align}
	\end{compactenum}
	Then, for every $\delta\in(0\,,1)$ and $R>0$, there exists 
	$L>0$ such that
	\[
		\P\left\{ \sup_{\nu \in B(0,R)} \mathcal{N}_n^\delta(\nu\,,2^{-n})
		\ge 2^{an} \right\} \le L^n \e^{- n^2/L}
		\quad\text{uniformly for all $n\in\N$}.
	\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:42:39.097015+00:00","domain":"probability theory","id":"claim_9555173e7b7bd6e837bcf804eeff3e2b3254fccaa33dabb3572045c76ffc545c","kind":"concept","schema_version":1,"statement":"[Lemm lemm4.1 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Let us assume that the conditions of Proposition (ClassYM of the paper) are in force except that the terminal value $\xi$ is of the form $\xi = \varphi(X_{s_0},\cdots,X_{s_{r-1}},X_{s_{r}})$ with $0\leq s_0\leq s_1\leq \cdots\leq s_{r-1}\leq s_r = T$, satisfies (equation 2.6 of the paper)--(equation 2.7 of the paper) and $X^{(i)} = X^{(j)}$ for all $i,j \in \{1,\cdots,r\}$.  Then there exists a unique solution $(\nabla^{j}Y,\nabla^{j}Z)$ to the BSDE 
				\begin{align}
					\nabla^{j}Y_t =& \sum_{i\geq j}^{r} \nabla_{{x^{(i)}}} \varphi(X_{s_0},\cdots,X_{s_{r-1}},X_{s_{r}})\nabla_x X_{s_i} - \int_{t}^{T} \nabla^{j} Z_s \mathrm{d}B_s\notag\\
					&\quad + \int_{t}^{T} \langle \nabla g(s,\bold{X}_s),\nabla_{x} \bold{X}_s \rangle \mathrm{d}s.
				\end{align}
				In addition, the following representations hold 
				\begin{align*}
					D_uY_t &= \sum_{i=0}^r y_i(t)\left(\nabla_{x}X_u\right)^{-1} \bold{1}_{\{u\geq s_i\}}, \quad 0\leq u \leq t,\\
					Z_t &= D_tY_t = \sum_{i=0}^r y_i(t)\left(\nabla_{x}X_t\right)^{-1} \bold{1}_{\{t\geq s_i\}},
				\end{align*}
				where the operator $D$ denotes the Malliavin derivative.
				Moreover, given a fixed time $t$ such that $t \in [s_j,s_{j+1}),0\leq j \leq N$ with the convention $[s_r,s_{r+1})=\{T\}$, we have
				\begin{equation}
					D_uY_t = \left(\nabla^{j}Y_t\right)^{\bold{T}}\left( \nabla_xX_u\right)^{-1},\quad Z_t = \left(\nabla^{j}Y_t\right)^{\bold{T}}\left( \nabla_xX_t\right)^{-1},
				\end{equation}
				and for all $1\leq i \leq r$,  $(y_0,z_0)$ and $(y_i,z_i)\in \mathbb{R}^m\times \mathbb{R}^{d\times m}$ are the adapted solutions to the following linear BSDEs 
