					&\quad + \int_t^T  \nabla_x g(s,\bold{X}_s)\nabla{X}_s\mathrm{d}s, \\
					y_i(t) &= \xi_i - \int_t^T z_i(s)\mathrm{d}W_s + \int_t^T \left(  \nabla_y g(s,\bold{X}_s)y_i(s) + \nabla_z g(s,\bold{X}_s)z_i(s) \right)\mathrm{d}s, 
				\end{align}
				respectively, and $\xi_i = \left( (\nabla_{x}\varphi)(X_{s_0},\cdots,X_{s_{r-1}},X_{s_{r}}) \right)^{\bold{T}} \nabla_{x}X_{s_i} \in \mathbb{R}^m$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

