{"assumptions":[],"created_at":"2026-10-27T14:25:44.589381+00:00","domain":"probability theory","id":"claim_962338d7b747565605da704a9203ff5d061517e2a73708f8093d331eb992d5b3","kind":"definition","schema_version":1,"statement":"[Defi def:elec_energy of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [Electric energy]
Let $I\subset \IR$ be an interval.
\begin{enumerate}
    \item We call electric fields on $I$ the set of all vector fields $E$ in $L^p_{loc}(I\times \IR,\IR\times \IR)$, for some $1<p<2/(s+1)$ fixed
\item Let $\xi$ be a finite point configuration in $I$ and $E$ an electric field on $I$. We say that $E$ is compatible with $\xi$ in $I$ provided 
\begin{align}
    -\textup{div}\,\left(\left\lverty\right\rvert^sE\right)=c_s\left(\xi-\delta_{\IR}\right) \text{ in }I\times \IR,
\end{align}
in the sense of distributions. Here  $\delta_{\IR}$ is the Radon measure on $\IR\times \IR$ defined by \begin{align*}
    \int_{\IR^2} f(x,y) d\delta_{\IR}(x,y)=\int_{\IR} f(x,0)dx,\quad f\in C_c(\IR^2,\IR).
\end{align*}
Similarly, in (equation eq:hypersurf of the paper) the point configuration $\xi$ is interpreted as a measure on $\IR^2$ via  
\begin{align*}
    \int_{\IR^2} f(x,y) d\xi(x,y)=\int_{\IR} f(x,0)d\xi(x)\quad f\in C_c(\IR^2,\IR).
\end{align*}
\item If $E$ is compatible with $\xi$ in $I$, for $\eta\in (0,1)$  we define the $\eta$-truncation of the electric field $E$ as
\begin{align*}
    E_{\eta}(x,y):=E(x,y)-\sum_{p\in \xi\cap I}\nabla f_{\eta}((x,y)-(p,0)),
\end{align*}
    where $f_{\eta}$ is the function
    \begin{align*}
        f_{\eta}(x,y):=\left(g(x,y)-g(\eta)\right)_+
    \end{align*}
     and $g(\eta)$ is defined by $g(\eta)=g(\eta,0)$.
\item Let $\xi$ be a point configuration on $\IR$. We define the global electric energy of $\xi$ as
\begin{align*}
     \tilde{\mathcal W}^{elec}(\xi):=\inf_E \left(
    \lim_{\eta\to 0}\left( 
    \limsup_{n\to \infty}\frac{1}{\left\lvert\Lambda_n\right\rvert}\frac{1}{c_s}\int_{\Lambda_n\times \IR}\left\lverty\right\rvert^{s}\norm{E_{\eta}}^2-g(\eta)
    \right)
    \right),
\end{align*}
where the $\inf$ is taken over electric fields $E$ that are compatible with $\xi$ in $\IR$.
\item For $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ we set \begin{align*}
    \mathcal W^{elec}(\mathsf{P}):=\int \tilde{\mathcal W}^{elec}(\xi)\mathsf{P}(d\xi).
\end{align*}


\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.095552+00:00","domain":"probability theory","id":"claim_9623b9d758435dc2f5c5071075f7e9b61a24e99a917957ec3042ee3b43a2adfa","kind":"concept","schema_version":1,"statement":"[Lem lem13 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $\delta_1$ be as in Lemma (lem11 of the paper). Then there exist $B=B(a,h)>0$, $\Gamma_2=\Gamma_2(a,h)>0$ and $\Gamma_3=\Gamma_3(a,h)>0$
  such that if ((init of the paper)) holds, and if $T\in (0,T_{max}]$ is such that
  \begin{equation} \label{uut}
	|u| + |u_t| \le \delta_1
	\qquad \mbox{in } \Omega\times (0,T),
  \end{equation}
  then for
  \begin{equation} \label{F1}
	{\mathcal{F}}_1(t):=\frac{1+Ba}{2} \int_\Omega |\nabla u|^2
	+ \int_\Omega H^{(1)}(u,u_t) + B \int_\Omega H^{(2)}(u,u_t),
	\qquad t\in (0,T_{max}),
  \end{equation}
  we have
  \begin{equation} \label{13.1}
	\Gamma_2 \int_\Omega v^2 \le {\mathcal{F}}_1(t) \le \Gamma_3 \int_\Omega |\nabla u|^2 + \Gamma_3 \int_\Omega |\nabla u_t|^2
	\qquad \mbox{for all } t\in [0,T)
  \end{equation}
  and 
  \begin{eqnarray}\label{13.2}
	{\mathcal{F}}_1'(t) + \Gamma_2 {\mathcal{F}}_1(t)
	\le \Gamma_3 \int_\Omega |u|\cdot |f(u,u_t,\nabla u,\nabla u_t)|
	+ \Gamma_3 \int_\Omega |u_t|\cdot |f(u,u_t,\nabla u,\nabla u_t)|
	+ \Gamma_3 \int_\Omega |u_t|^3

  \end{eqnarray}
  for all $t\in (0,T)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:37:20.357644+00:00","domain":"probability theory","id":"claim_962b20b0d1fa90c976d11ca57e6ca75660f8c536547d485f0acdcfa6360d6d2a","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $(g_n)_{n \ge 1}$ be a sequence of finite simple graphs where $V(g_n)=[n]$. Assume that $g_n \to w$ in the graphon sense. Let $a_1^{(n)},\ldots,a_n^{(n)} \in \mathcal{A}$ be $g_n$-independent identically distributed centered (self-adjoint) random variables with variance one, for every $n \ge 1$. Then 
    \begin{align*}
        S_n=\frac{1}{\sqrt{n}}\sum_{k \in [n]}a_k^{(n)}
    \end{align*}
    converges in distribution to a law $\mu_w$ that depends only on $w$. Moreover, its odd moments vanish, whereas, for any $p\in \mathbb{N}$, we have
    \begin{align*}
        \int x^{2p}\, \text{d}\mu_w=\sum_{\pi \in P_2(2p)}\rho(f_\pi,w).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:31:57.871622+00:00","domain":"probability theory","id":"claim_962fd12ac472b295c2da6957bd4c95b8b1cfdd54b2db85440eaf69f9df767992","kind":"definition","schema_version":1,"statement":"[Definition d:dir-space of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] We call $(X,d,\mu, \mathcal{E}_p, \mathcal{F}_p, \Gamma_p)$ a local $p$-Dirichlet space if the following hold:
		\begin{enumerate}  
			\item \textbf{Locally compact space}: $(X,d,\mu)$ is a locally compact metric space equipped with a Radon measure $\mu$.
			\item \textbf{Completeness:} 	The space $\mathcal{F}_p$  is a subspace of $L^p(X,\mu)$ and
			$\mathcal{E}_p: \mathcal{F}_p \to [0,\infty)$ is a non-negative function such that $\mathcal{F}_p$ is a Banach space when equipped with the norm $\norm{f}_{\mathcal{F}_p}=(\norm{f}_{L^p}^p+\mathcal{E}_p(f))^{1/p}$.
			\item \textbf{Homogeneity:} For all $f\in \mathcal{F}_p$ there exists a finite non-negative Borel measure $\Gamma_p \langle f \rangle$ on $X$ such that $\Gamma_p \langle f \rangle(X)= \mathcal{E}_p(f)$   and for all $\lambda \in \mathbb{R}$
			\[
			\Gamma_p\langle \lambda f\rangle = |\lambda|^p \Gamma_p\langle f\rangle.
			\]
			\item \textbf{Sublinearity:} For every $f,g\in \mathcal{F}_p$ and every Borel set $A\subset X$, 
			\begin{equation} 
				\Gamma_p\langle f+g\rangle(A)^{\frac{1}{p}}\le \Gamma_p\langle f\rangle(A)^{\frac{1}{p}}+\Gamma_p\langle g\rangle(A)^{\frac{1}{p}}
			\end{equation}
			\item \textbf{Chain rule:} For all $f\in \mathcal{F}_p$, $g\in \Lip(\mathbb{R})$ with $g(0)=0$,  we have $g \circ f \in \mathcal{F}_p$ and
			\begin{equation} 
				d\Gamma_p\langle g\circ f\rangle \le \LIP[g]^p d\Gamma_p\langle f\rangle.
			\end{equation}
			\item \textbf{Locality:} For every $f\in \mathcal{F}_p$ and open set $A\subset X$, if $f|_A=c$ $\mu$-a.e., then $\Gamma_p\langle f\rangle(A)=0$. 
			\item \textbf{Weak lower semicontinuity:} For every $f\in L^p(X)$, and for any sequence of functions $(f_i)_{i \in \mathbb{N}}$ in $\mathcal{F}_p$ such that $f_i\to f \in L^p(X)$ with $\sup_{i\in \mathbb{N}} \mathcal{E}_p(f_i)<\infty$, then $f\in \mathcal{F}_p$ and
			\begin{equation} 
				\Gamma_p\langle f \rangle(A)\le \liminf_{i\to \infty} \Gamma_p\langle f_i \rangle(A)
			\end{equation}
			for every Borel set $A\subset X$. 
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:49:15.475977+00:00","domain":"probability theory","id":"claim_96303c75f60f1db881e4f177a3a21ce9980631e7e95b1917a61cb367f5ed3f00","kind":"concept","schema_version":1,"statement":"[Cor box-product-bifun of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] For any compact Lie group $G$, the functor
