{"assumptions":[],"created_at":"2026-10-28T00:45:32.100994+00:00","domain":"probability theory","id":"claim_9709dda63d24eac8f6e724c1db33d2708b2587a2afc01dee1974e77bbf5e6b79","kind":"definition","schema_version":1,"statement":"[Defn def bi-inf RW of arXiv:2411.14350, 'Randomized Geodesic Flow on Hyperbolic Groups'] $ $
\begin{itemize}
\item Given two sequences $\bar z:= (\bar z_n)_{n\in \mathbb{N}}$ and $z:=(z_n)_{n\in \mathbb{N}}$ with $\bar z_0=z_0$, we denote by $(\bar z\oplus z)$ the bi-infinite sequence $(x_n)_{n\in\mathbb{N}}$ given by
\[ \bar z_n \oplus z_n:= x_{n} := \begin{cases} \bar z_{-n} &\text{if } n \leq 0,\\ z_{n} &\text{if } n > 0.
\end{cases}
\]
\item Given two independent random walks $\big(Z_n\big)_{n\in\mathbb{N}}$ and $\big(\bar Z_n\big)_{n\in\mathbb{N}}$ starting at $g\in G$ and with step distribution $\mu$, define the \textbf{bi-infinite random walk with fixed origin $g$ and step distribution $\mu$} as 
\[\big(X_z\big)_{z\in\mathbb{Z}}:= \bigg(\big(\bar Z_n\big)_{n\in\mathbb{N}} \oplus \big( Z_n\big)_{n\in\mathbb{N}}\bigg)\] 
\item We will denote by {\bf $\bar\mathbb{P}_{g}$ the distribution of $(X_z)_{z\in\mathbb{Z}}$, equivalently, the joint distribution of $\big(Z_n\big)_{n\in\mathbb{N}}$ and $\big(\bar Z_n\big)_{n\in\mathbb{N}}$}. We will also write 
\begin{equation}
G^{\mathbb{Z}}:= \bigg\{ \text{all bi-infinite random walk paths } (X_{z})_{z\in\mathbb{Z}} \text{ in } G\bigg\} 
\end{equation}
and for $g \in G$
\begin{equation}
G_{g}^{\mathbb{Z}}:= \bigg \{ \text{all bi-infinite random walk paths } (X_{z})_{z\in\mathbb{Z}} \text{ in } G \text{ with } X_{0}=g \bigg \}.
\end{equation}
We then have that $G^{\mathbb{Z}} = \bigcup_{g\in G}G^{\mathbb{Z}}_g$ is a disjoint union.
\end{itemize}","status":"unverified"}

