 \end{split}\end{align}
and $n> n_0$. 
Let $V_n^*$ be a non-negative random variable which satisfies for all $ \lambda \in [0,\infty) $ that
\bas{
  - \ln \mathbb{E}\bigl[ e^{-\lambda V_n^*} \bigr]
  \ge \sum_{k=n_0+1}^n \left( c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda \right) \wedge q + c \frac{1-\beta^{n_0}}{1-\beta^n} \beta^{n-n_0} \lambda.
}
Then \bas{
{\mathbb E}[(V_n^*)^{-p}]&\le \frac1{c^p} D_{\rho,p},
}
where
\bas{

  D_{\rho,p}:=\sum_{r=0}^\infty (r+1)^p e^{-\rho r}<\infty.
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.516735+00:00","domain":"probability theory","id":"claim_983e816cc944908494ea93478af69bc683291c2ac248697f9c0933f1ee749aed","kind":"concept","schema_version":1,"statement":"[Theorem thm:1.2 of arXiv:2607.24164, 'The KLS constant is $O(\log^{1/4} n)$'] Suppose that $X \sim \mu$ is an isotropic log-concave random vector in $\mathbb{R}^n$. Then for any symmetric matrix $M$ one has that
