clock increment.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.247652+00:00","domain":"probability theory","id":"claim_99237473086e2c9f2a07da102f2a19005f6f7729b8aa72e996fa9415fb05e376","kind":"lemma","schema_version":1,"statement":"[Lemma lem:CRP case of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] Suppose $\alpha\in(0,1)$. \begin{enumerate}[(i)]
\item 
Suppose $p_\ell = d_0\Gamma_\ell^{-1/\alpha}, \ell\in{\mathbb N}$ as in (equation eq:p_n CRP of the paper). 
For every $K>0$,
\begin{equation}
\max_{|k|\le K\sqrt{j_n\log\log n}}\abs{np_{\ell_n+k}-j_n   +\frac{j_n(\Gamma_{\ell_n}-\ell_n+k)}{\alpha\ell_n}}= O\pp{j_n^{1/4}(\log n)^{1/2}\pp{\log\log n}^{1/4}},
