    \item $\exists c>0: \mathds{P}(d_U^{\textnormal{out}} \geq 2\delta^{\textnormal{tail}}),\mathds{P}(d_U^{\textnormal{in}} \geq 2\delta^{\textnormal{head}}) \geq c$ 
