\item[(2)] each intersection point is double and transverse, and
\item[(3)] each intersection point is endowed with classical (with a choice for overpass and underpass specified) or virtual crossing  (which is depicted as encircled double point) structure. 
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.737776+00:00","domain":"probability theory","id":"claim_9bc57d07784e5011b4e4214b111394e9f25160f5ddcbd65443197fea7001bea5","kind":"concept","schema_version":1,"statement":"[Proposition 11 of arXiv:2506.10476, 'Construction of ergodic \textsc{idla} forests in $\mathbb{Z}^d$'] Under the \textit{Absurd hypothesis} (\ref{Absurd-Hypo}), the following holds:
\begin{equation}

	\forall \varepsilon > 0 , \; \mathbb{P} \Big( \text{$\hat{\Sigma}_{\varepsilon}$ percolates} \Big) > 0 ~.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.844931+00:00","domain":"probability theory","id":"claim_9bc5b9e2ba77ec85dcf1e8d07497c6afe758fb9dbbb781e55d5d4f7a19726a77","kind":"concept","schema_version":1,"statement":"[Conj 8 (\cite{HallEak2025}) of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] Let $b_0$ be an invertible operator in a $W^\ast$-probability space $(\A,\tau)$.  Define
\[ \tilde{p}_0(z) = \tau[|b_0-z|^{-2}] \qquad \& \qquad \tilde{p}_2(z) = \tau[b_0^\ast b_0|b_0-z|^{-2}] \]
where, as usual, for any operator $a\in\A$, $|a|^2:=a^\ast a$.  Define $T(b_0,\cdot)\colon\C\to\R_+$ by
\begin{equation}  T(b_0,z) = \frac{\log(\tilde{p}_2(z))-\log(|z|^2\tilde{p}_0(z))}{\tilde{p}_2(z)-|z|^2\tilde{p}_0(z)}.
\end{equation}
For each $t>0$, define the open precompact set $\Sigma(b_0,t)$ by
\begin{equation}  \Sigma(b_0,t) = \{z\in\C\colon T(b_0,z)<t\}. \end{equation}
Let $b(t,\zeta)$ be a free multiplicative Brownian motion (see Notation \ref{notat.ovweparam}) freely independent from $b_0$.  Then the support of the Brown measure of $b_0b(t,\zeta)$ is equal to the image $\overline{\Sigma(b_0,t,\zeta)}$ of $\overline{\Sigma(b_0,t)}$ under the map $\Psi^{b_0}_{t,\zeta}$ of \eqref{eq.Psi}. (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.575339+00:00","domain":"probability theory","id":"claim_9bca31fe509a9fbe9df85d9718c49bf8fadf47a2338a20b1ae883b7a4fdd8b7a","kind":"theorem","schema_version":1,"statement":"[Theorem T:01law of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] \index{zero-one law}
  Assume condition (equation E:main of the paper). Further assume $\ell < \alpha (\gamma+1/2)$ if $\beta = 2$ and $\gamma \in (0, 2]$ in part {\rm (i)}
  below. Fix $a \ge 0$.
  \begin{enumerate}[\rm (i)]

    \item If $\rho \in (0, 1)$, then for any compact interval $I$ in $(0, \infty)$
          and any $x_0 \in \mathbb{R}^d$, there exist constants $K_1, K_2, K_3, K_4 \in [0,
              \infty]$ such that for each $t_0 \in I$,
          \begin{align}
            \lim_{\varepsilon \to 0^+} \sup_{t,s\in I: 0<|t-s|\le \varepsilon} \frac{|u(t,x_0)-u(s,x_0)|}{|t-s|^\rho\sqrt{\log(1+|t-s|^{-1})}} = K_1 \quad \text{a.s.},
          \end{align}
          \begin{align}
            \lim_{\varepsilon \to 0^+} \sup_{t: 0<|t-t_0|\le \varepsilon} \frac{|u(t,x_0)-u(t_0,x_0)|}{|t-t_0|^\rho\sqrt{\log\log(|t-t_0|^{-1})}} = K_2 \quad \text{a.s.},
          \end{align}
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \sup_{t : |t-t_0| \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho (\log\log(1/\varepsilon))^{-a}} = K_3 \quad \text{a.s.},
          \end{align}
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \inf_{t_0 \in I} \sup_{t : |t-t_0| \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho(\log(1/\varepsilon))^{-a}} = K_4 \quad \text{a.s.}
