{"assumptions":[],"created_at":"2026-10-26T20:56:03.898282+00:00","domain":"probability theory","id":"claim_9d1635f5b32077f01d18f155f54d7e26dac1d03d0b6be468eca565f7e2c7bc6b","kind":"theorem","schema_version":1,"statement":"[Theo 9 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Assume that conditions $({\bf A1})$-$({\bf A3})$ are satisfied. We have 
\begin{enumerate}
\item For each $s, t \in  [0, T],\; t \leq s$, $(X^{t,x,\varepsilon},Y^{t,x,\varepsilon},Z^{t,x,\varepsilon})$ the solution of \eqref{Eq1} converges in $\mathcal{S}^2(\R)\times\mathcal{S}^2(\R)\times\mathcal{H}^2(\R^n)$ when $\varepsilon\rightarrow 0$, to $(\mathcal{X}^{t,x},\mathcal{Y}^{t,x},0)$ solution of \eqref{u}.
\item Let denote $Y^{t,x}(t)$ the limit of $Y^{\varepsilon,t,x}(t)$ when $\varepsilon \rightarrow 0$ and set $u(t,{\bf 1}(x))=Y^{t,x}(t)$. Then the function $u$ is a viscosity solution of PDE the following path-dependent PDE 
\begin{eqnarray}
\left\{
\begin{array}{l}
\displaystyle \frac{\partial u (t,{\bf 1}(x))}{\partial t}+b(t,{\bf 1}(x),{\bf 1}(u(t,{\bf 1}(x))),{\bf 1}(0))\frac{\partial u(t,{\bf 1}(x))}{\partial x}\\\\\displaystyle+f\left(t,{\bf 1}(x),{\bf 1}(u(t,{\bf 1}(x))),{\bf 1}(0)\right)=0\\\\
u(T,{\bf 1}(x))=g({\bf 1}(x)),
 \end{array}
 \right.
 \end{eqnarray}
\item The function $u$ is bounded, continuous Lipschitz in $\varphi$ and uniformly continuous in time.
\item Furthermore, if $u\in C^{1,1}_{b}([0, T]\times  L_{-T}^{\infty}(\mathbb{R}))$, since \eqref{u} has a unique continuous solution, the function $u$ is a classical solution of \eqref{u1}.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.537178+00:00","domain":"probability theory","id":"claim_9d17832c99d204e7176c03f93417279536aeaddd407662e50942b26c80879eb3","kind":"definition","schema_version":1,"statement":"[Definition def.WIP of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] List $E_d({\scaleobj{1}{\square}}_m \setminus \Gamma_m)$ in an deterministic order $\{e_1,\dots, e_K\}$ and run the following algorithm under the canonical coupling space defined in Definition~(def.Coupling of the paper): 
			\begin{enumerate}
				\item Let $\widetilde{\mathbf{a}}^{\delta,(0)}_{m} := \mathbf{a}^\delta_m, \mathcal{E}_m^{(0)} := \emptyset$.
				\item For $1\leqslant i \leqslant K$, 
				\begin{itemize}
					\item if $e_i = \{x, y\}$ such that $ x,y\overset{\widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}}{\longleftrightarrow} \partial {\scaleobj{1}{\square}}_m$, then $\widetilde{\mathbf{a}}^{\delta,(i)}_{m} := \widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}$ and $\mathcal{E}_m^{(i)} := \mathcal{E}_m^{(i-1)}$; 
					\item otherwise, let $\mathcal{E}_m^{(i)} = \mathcal{E}_m^{(i-1)} \cup \{e_i\}$, and 
					\begin{equation}
						\widetilde{\mathbf{a}}^{\delta,(i)}_{m}(e) := \widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}(e) + (1-\widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}(e))\Ind{e=e_i, U(e_i)\leqslant \frac{\delta}{1-\mathfrak{p}}}.
					\end{equation}
				\end{itemize}
				\item The output is $\widetilde{\mathbf{a}}^\delta_{m} := \widetilde{\mathbf{a}}^{\delta,(K)}_{m}, \mathcal{E}_m := \mathcal{E}_m^{(K)}$.
			\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:37:20.369824+00:00","domain":"probability theory","id":"claim_9d1b38861727b3d6d8c2bf67402e97e244adfd61e241817ae3a0d5954b125d31","kind":"lemma","schema_version":1,"statement":"[Lemma lem:ubound of arXiv:2411.13430, 'Optimal subelliptic super-Poincar\'e and isoperimetric inequalities on stratified Lie grou'] Under the assumptions of Theorem (thm1 of the paper), the measure $\mu$ satisfies the $U$-bound 
