{"assumptions":[],"created_at":"2026-10-27T06:56:11.133525+00:00","domain":"probability theory","id":"claim_a229e25ef55c5db4892bbc1cd2125032ffed22958e46c5fbc5b9681abf9d0f19","kind":"lemma","schema_version":1,"statement":"[Lemma 6 (\cite{Chen2013}*{Lemma~5}) of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Fix an integer $m\ge1$. Let $\psi$ be continuous on $[0,1]$ and differentiable on $(0,1)$. For a binary word $\mathbf s=(s_1,\ldots,s_n)\in\{0,1\}^n$, let $\psi_{\mathbf s}$ be continuous on $[0,1]$ and differentiable on $(0,1)$. Suppose that all the expressions below are integrable at zero, that $\psi(0)=0$, and that
\begin{equation}
  \psi'(t)=\frac12\psi_{(0)}(t)+\frac1{2\sqrt t}\psi_{(1)}(t),
  \qquad
  \psi_{\mathbf s}'(t)=\frac12\psi_{(\mathbf s,0)}(t)
  +\frac1{2\sqrt t}\psi_{(\mathbf s,1)}(t)
\end{equation}
for $t\in(0,1)$ and $1\le |\mathbf s|\le m$. If
\[
  \psi_{\mathbf s}(0)=0,\qquad 1\le |\mathbf s|<m,
\]
then, writing
\[
  \Delta_n(t):=\{(t_1,\ldots,t_n):0<t_n<\cdots<t_1<t\},
\]
we have
\begin{align}
\psi(t)
={}&\frac1{2^m}\sum_{\mathbf s\in\{0,1\}^m}
\int_{\Delta_m(t)}
\left(\prod_{j=1}^m t_j^{-s_j/2}\right)\psi_{\mathbf s}(0)\,d\mathbf t \\
&+\frac1{2^{m+1}}\sum_{\mathbf s\in\{0,1\}^{m+1}}
\int_{\Delta_{m+1}(t)}
\left(\prod_{j=1}^{m+1}t_j^{-s_j/2}\right)
\psi_{\mathbf s}(t_{m+1})\,d\mathbf t.\notag
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:38.358724+00:00","domain":"probability theory","id":"claim_a22ed7bf4b3c854b8853bb75f0f085d1d743561c7a3f6ab73dbc1e92652fccf6","kind":"definition","schema_version":1,"statement":"[Definition 7 (First-order corrector) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Given a slope $p \in \Rd$, a bounded Lipschitz domain $U \subseteq \Rd$, and $\eps \in (0, 1)$, we define
		\begin{equation}

			\nu(U^\eps, p)
			\coloneqq -\inf_{\substack{w \colon \eps\Zd \to \R \\ w = 0 \text{ on } \eps\Zd \setminus U^\eps}}
			\frac{\eps^{2d}}{2\kappa_\eps}
			\sum_{\substack{x, z \in \eps\Zd, z \ne 0 \\ x \in U^\eps \text{ or } x+z \in U^\eps}}
			\a\left(\frac{x}{\eps}, \frac{x+z}{\eps}\right) J(z)
			\Bigl[\bigl(p \cdot z + w(x{+}z) - w(x)\bigr)^2 - |p \cdot z|^2\Bigr].
		\end{equation}
		The factor $1/2$ ensures that each unordered edge touching $U^\eps$ is counted exactly once.
		We define the first-order corrector $\phi_p^\eps$ to be the unique minimizer of this functional; it is equivalently the unique solution to
		\begin{equation} 
			\begin{cases}
				\mathcal{L}^\eps(\ell_p + \phi_p^\eps) = 0 & \text{in } U^\eps\,,\\
				\phi_p^\eps = 0 & \text{on } \eps\Zd \setminus U^\eps\,.
			\end{cases}
		\end{equation}","status":"unverified"}

