{"assumptions":[],"created_at":"2026-10-26T21:02:38.606777+00:00","domain":"probability theory","id":"claim_a37cb72a8d5e1b9b7b1f00101c50dee1c9344be39b7fd45a9b7343cd3bf66301","kind":"theorem","schema_version":1,"statement":"[Proposition 19 of arXiv:2607.08129, '2607.08129'] Let $T_1,\ldots,T_N$ be independent real-valued random variables, and let
$0\le c_i\le\beta$.  Fix an interval $J=(a,b]$ and define
\begin{equation}
 R_J:=\sup_{a\le u\le b}
 \left|\sum_{i=1}^Nc_i
 \left(
 \1_{\{a<T_i\le u\}}-\Prob(a<T_i\le u)
 \right)\right|
\end{equation}
and
\begin{equation}
 V_J:=\sum_{i=1}^Nc_i^2\Prob(T_i\in J).
\end{equation}
Then
\begin{equation}
 \E R_J\le4\sqrt{V_J}.
\end{equation}
There is a universal constant $C_T<\infty$ such that, for every $x>0$,
\begin{equation}
 \Prob(R_J\ge\E R_J+x)
 \le C_T\exp\left\{
 -\frac{x}{C_T\beta}
 \log\left(1+
 \frac{x\beta}{V_J+\beta\E R_J}
 \right)
 \right\}.
\end{equation}
If $\beta=0$, both assertions hold trivially.  In particular, after changing the universal constant if necessary,
\begin{equation}
 \Prob(R_J\ge\E R_J+x)
 \le C_T\exp\bigg\{
 -\frac{x^2}{C_T\{V_J+\beta\E R_J+x\beta\}}
 \bigg\}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.185199+00:00","domain":"probability theory","id":"claim_a3828aa0e9be0d21582d5714f4c75ca9e3998c7c2f66b84629918de07b0c845f","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2606.30349, 'Attenuated Poisson Dirichlet approximations for divisibility configurations'] Let $\eta$ be a Poisson point process on $(0,1)$ with intensity $x^{-1}\,dx$, and let
\begin{align*}
T(\eta):=\int_{(0,1)}x\,\eta(dx).
\end{align*}
Then
\begin{align*}
\mathcal L\big(\mathfrak q(\eta)\mid T(\eta)\le 1\big)
=
\mathfrak A[\theta_{\mathcal S}],
\end{align*}
where $\theta_{\mathcal S}$ denotes the law on $\mathcal S$ obtained by arranging a $PD(1)$ mass partition in decreasing order. Equivalently,
\begin{align*}
\mathfrak q(\eta)\mid \{T(\eta)\le1\}
\overset{Law}{=}
U(P_1,P_2,\dots),
\end{align*}
where $(P_1,P_2,\dots)$ has distribution $PD(1)$, $U$ is uniformly distributed on $(0,1)$, and $U$ is independent of $(P_1,P_2,\dots)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.569869+00:00","domain":"probability theory","id":"claim_a385e4dd837fa10e0b7fc4c7a21b0f6c5c31774d579fc73fdae249f09d7b4dc0","kind":"definition","schema_version":1,"statement":"[Definition 4 (Stochastic domination) of arXiv:2608.27307, '2608.27307'] Let
        \begin{align}
                \xi=(\xi^{(N)}(u):N\in\N,\ u\in U^{(N)}),
                \qquad
                \zeta=(\zeta^{(N)}(u):N\in\N,\ u\in U^{(N)}) \nonumber
        \end{align}
        be two families of nonnegative random variables, where $U^{(N)}$ is a possibly $N$-dependent parameter set.
        We say that $\xi$ is stochastically dominated by $\zeta$, uniformly in $u$, if for all (small) $\eps>0$ and (large) $D>0$, we have
        \begin{align}
                \sup_{u\in U^{(N)}} \bb P(\abs{\xi^{(N)}(u)}>N^\eps\zeta^{(N)}(u)) \leq N^{-D} \nonumber
        \end{align}
        for large $N > N_0(\eps,D)$. We write $\xi=O_\prec(\zeta)$ or $\xi\prec\zeta$ when $\xi$ is stochastically dominated by $\zeta$ uniformly in $u$. Note that in the special case when $\xi$ and $\zeta$ are deterministic, $\xi\prec\zeta$  means for any given $\eps>0$,  $|\xi_N(u)|\leq N^\eps\zeta_N(u)$ uniformly in $u$, for allsufficiently large $N\geq N_0(\eps)$.  Let $R$ be a family of complex square matrices and $\zeta$ a family of nonnegative random variables. We write $R=O_\prec(\zeta)$ to mean $\abs{\scalar{\bbv}{R\bbw}}\prec\zeta|\bbv||\bbw|$ uniformly for all deterministic vectors $\bbv$ and $\bbw$.

        In addition, we say that an event $\Xi $ holds \emph{with high probability} if
        \begin{align}
                \bb P(\Xi)\geq 1-N^{-D} \nonumber
        \end{align}
        for any large constant $D>0$ when $N$ is sufficiently large.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.939730+00:00","domain":"probability theory","id":"claim_a38773a7edc19ad00170d50fd182e0fa2dd034d4ef1021d1c7ac175d42ff187b","kind":"concept","schema_version":1,"statement":"[Proposition 29 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] [Log--sum inequality]
     For non--negative numbers $(a_{i})_{i\ge 1}$ and $(b_{i})_{i \ge 1},$
    \begin{displaymath}
        \sum_{i \ge 1 } a_{i} \log \Bigg( \frac{\sum_{i \ge 1 } a_{i}}{\sum_{i \ge 1 } b_{i}} \Bigg) \le \sum_{i \ge 1 } a_{i} \log \Big( \frac{a_{i}}{b_{i}} \Big) 
    \end{displaymath}
    provided that the sums of $a_{i}$ and $b_{i}$ are finite. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

