{"assumptions":[],"created_at":"2026-10-27T06:02:34.833871+00:00","domain":"probability theory","id":"claim_a6abdf1bf68d6a9d6b3c99eb21508633a44ede1c980e39f60a31d056af01fc1b","kind":"theorem","schema_version":1,"statement":"[Theorem 14 (Gaussian cofactor induction) of arXiv:2607.20329, '2607.20329'] Let $\mathbb K\in\{\R,\C,\Hh\}$ and $\beta=\dim_{\R}\mathbb K$.
		For each $m\ge1$, let $g_m^{\mathbb K}$ be a standard
		$\mathbb K$-Gaussian column in $\mathbb K^m$, independent of the gamma
		variables.  Then, for every $n\ge1$,
		\begin{equation}
			\Pi_{n-1,\beta}g_n^{\mathbb K}(g_n^{\mathbb K})^*
			\preceq_{\mathrm{Lt}}
			C_n^{\mathbb K}(C_n^{\mathbb K})^*.
		\end{equation}
		Moreover,
		\begin{equation}
			\Pi_{n,\beta}
			\le_{\mathrm{Lt}}\|C_n^{\mathbb K}\|_2^2.
		\end{equation}
		Finally, for every $z\in\mathbb K^{n+1}$,
		\begin{equation}
			0\le \E e^{\ii(z,C_{n+1}^{\mathbb K})_{\R}}
			\le \E e^{\ii(z,\sqrt{\Pi_{n,\beta}}\,
				g_{n+1}^{\mathbb K})_{\R}}.
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.864111+00:00","domain":"probability theory","id":"claim_a6ac313c3ab2e3437b465d1ad600821b95c7c1156c40c98896b10e1929636a88","kind":"theorem","schema_version":1,"statement":"[Proposition 54 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mf A$ be an HOTM and $\mu$ and $\nu$ be $\mf A$-valued premeasures such that $\q{\mu}=\q{\nu}$. 
  \begin{enumerate}
  \item[(i)]  $\mu\dotleq\nu$ if and only if $\as[\mf A]{\mu}\dotleq\as[\mf A]{\nu}$.
  \item[(ii)] Suppose $\mu$ and $\nu$ are measures. If $\mu\dotleq\nu$ and $\nu\dotleq\mu$, then $\mu=\nu$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:25:44.969042+00:00","domain":"probability theory","id":"claim_a6ac5e03bd4612fd380cd53f2afa6008a83791f7e20003e7443cd59880ca453c","kind":"lemma","schema_version":1,"statement":"[Lemma 8 (Fourth moments for the cross-polytope) of arXiv:2605.11451, '2605.11451'] Let $X\sim \nu_{1,n}$ be uniform on $B_1^n$ and let $i\neq j$. Then
\begin{align}
 \E X_i^4
 &=\frac{24}{(n+1)(n+2)(n+3)(n+4)},\notag\\
 \E X_i^2X_j^2
 &=\frac{4}{(n+1)(n+2)(n+3)(n+4)}.
\end{align}
Consequently, for every $\theta\in\sphere$,
\begin{equation}
 \E\langle\theta,X\rangle^4
 =
 3\,\E X_1^2X_2^2+\bigl(\E X_1^4-3\,\E X_1^2X_2^2\bigr)\sum_{i=1}^n\theta_i^4,
\end{equation}
and the coefficient $\E X_1^4-3\,\E X_1^2X_2^2$ is strictly positive.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.423224+00:00","domain":"probability theory","id":"claim_a6b03ec99daf7e5561994511de023e57f85c4dd8c35af2a60a3811b28af53285","kind":"concept","schema_version":1,"statement":"[Proposition p: alpha mixing condition of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d, 2]$. Suppose that there are $\gamma> d+\max(p,0), c>0$ such that
    \begin{align}
        \BE_{0}^{\Phi}[\|Z(0)\|^{\gamma}] &< \infty,\\
        \BE_{0,y}^{\Phi}[\|Z(0)\|^{\gamma}] &\leq c,\quad y\in\R^d\\
        \int \frac{\kappa(y)^{\frac{\gamma-2q}{\gamma}}}{1 + \|y\|^{2q-p}}\, \alpha_\Phi(dy) &< \infty,\quad q\in\N, q<\tfrac{d+p}{2}, 
    \end{align}
    where
    \begin{equation}
        \kappa(y) := \sup_{B_1,B_2\in\cB^d} \big|\BP_{0,y}^\Phi(Z(y)\in B_1, Z(0)\in B_2) - \BP_0^\Phi(Z(y)\in B_1)\BP_0^\Phi(Z(0)\in B_2)\big|,\quad y\in\R^d.
    \end{equation}
    Then $\Psi$ is $p$-uniform if $\Phi$ is. If $p<2$, then beyond $p$-uniformity also transfers. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.615112+00:00","domain":"probability theory","id":"claim_a6b9c4c19b126c03935d1afc6e103b19145debe60a9d4bca422120300dad6a3e","kind":"theorem","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.22644, '2604.22644'] Let the scale function defined for $k \ge 1$ be
\begin{align}
    S(k;p) = \sum_{i=0}^{k-1} \prod_{j=1}^{i} \frac{1 - r^j p}{r^j p}
\end{align}
where the empty product for $i=0$ is defined as $1$. Then, the probability that the first excursion $e_1$ does not reach $N$ is given by:
\begin{align}
    P(e_1 \text{ does not reach } N) = 1 - \int_0^1 \frac{p}{S(N;p)} dp.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:27:25.791885+00:00","domain":"probability theory","id":"claim_a6bf3b94a840156be1b34b03b77f108cdbceaca6d8d6a364783801138aab7696","kind":"concept","schema_version":1,"statement":"[Prop continuity of arXiv:2605.11785, 'Regularization of a mean-field SDE by an additive common noise: the conditional expectatio'] For any $\epsilon\in (0,\frac 12)$, there exists a constant $C_\epsilon>0$, depending on $\epsilon$, $\sigma^0$, $b$ and $T$ only, such that, for any $M>0$ and any $\mu_0, \widehat \mu_0\in \mathcal P_1(\mathbb{R}^d)$, 
\begin{equation}
d_{\rm B_ML}(P^{\mu_0},P^{\widehat\mu_0})\leq C_\epsilon \left(W_1(\mu_0,\widehat \mu_0)^{1/2}+ W_1(\mu_0,\widehat \mu_0)^{1/2-\epsilon}\right) (W_1(\mu_0,\widehat \mu_0)^{1/2} +M).
\end{equation}  
More generally, if we  denote (with a slight abuse of notation) by $P^{\mu_0}(d\bm{x}|\bm{x}^0)$ the conditional distribution of the $X$ component given that $X^0=\bm{x} ^0$ under $P^{\mu_0}$, then, for all $M>0$ and for all $\mu_0, \widehat \mu_0\in \mathcal P_1(\mathbb{R}^d)$,
\begin{align}
& d_{{\rm B}_M{\rm L}}\left(Q^{\mu_0}(d\bm{x}^0)\prod_{i=1}^kP^{\mu_0}(d\bm{x}^i|\bm{x}^0),Q^{\widehat\mu_0}(d\bm{x}^0)\prod_{i=1}^kP^{\widehat\mu_0}(d\bm{x}^i|\bm{x}^0)\right) \notag\\
& \qquad\qquad\qquad\qquad  \leq C_\epsilon \left(W_1(\mu_0,\widehat \mu_0)^{1/2}+ W_1(\mu_0,\widehat \mu_0)^{1/2-\epsilon}\right)  \left(k W_1(\mu_0,\widehat \mu_0)^{1/2}+ M\right).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.763485+00:00","domain":"probability theory","id":"claim_a6c5add227785d19a4f1c5c178907e0e398bbfee89594055cbd50ec595393501","kind":"theorem","schema_version":1,"statement":"[Theorem 5 (Finite 2D $\rho$-variation) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Let $H > 1/4$ and $\rho = 1/(2H)$. Then
