{"assumptions":[],"created_at":"2026-10-27T19:59:45.007679+00:00","domain":"probability theory","id":"claim_a88e854704dcbca2fd84a05227a318bba59b6a1783c66ce6b392994e8976bc4f","kind":"theorem","schema_version":1,"statement":"[Proposition LUE left soft fac of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Let $\xi_{a,N}$, $\eta_{a,N}$ be the kernel functions defined in (equation explicit xi and zeta of the paper) and $(\tilde{\mu}_{n,N},\tilde{\sigma}_{n,N})$ be a pair with respect to the left-soft-edged scaling $\tau$ satisfying the restriction (equation restriction of recaling of the paper). Define:
    \begin{equation}
    \begin{array}{cc}
          K^{LS}_{\tau}(x,y):=\tilde\sigma_{n,N}K_{L_{a,N}}\left(\tilde{\mu}_{n,N}-\tilde\sigma_{n,N}x,\tilde\mu-\tilde\sigma_{n,N}y\right),\\
          \\
        \xi_{\tau}(s):=\tilde\sigma_{n,N}\xi_{{a,N}}\left(\tilde{\mu}_{n,N}-\tilde\sigma_{n,N}s\right),\\
        \\
          \eta_{\tau}(s):=\tilde\sigma_{n,N}\eta_{{a,N}}\left(\tilde{\mu}_{n,N}-\tilde\sigma_{n,N}s\right).
    \end{array}
    \end{equation}
    Then the corresponding operators satisfy: $\mathbf{K}_{\tau}^{LS}=\mathbf{G}_\tau\mathbf{H}_\tau+\mathbf{H}_\tau\mathbf{G}_\tau$ with kernel functions $G_{\tau}(x,y)=\xi_\tau(x+y)$ and $H_\tau(x,y)=-\eta_\tau(x+y)$. Moreover, let $Ai(x+y)$ be the kernel of the integral operator $\mathbf{Ai}$, then the decomposition: $\mathbf{Ai}^2=\mathbf{K}_{Airy}$ holds for the Airy operator.

    In particular, for any $s_0\in\mathbb{R}$, $\mathbf{G}_{\tau}$, $\mathbf{H}_\tau$ and $\mathbf{Ai}$ can be regarded as Hilbert--Schmidt integral operators on $L^2(s_0,\infty)$ with kernels $\xi_\tau(x+y-s_0)$, $-\eta_\tau(x+y-s_0)$ and $Ai(x+y-s_0)$ respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.424882+00:00","domain":"probability theory","id":"claim_a8925faa46ffbfb472a85a49a1437d11b9683a4660decca319dd07d9f9ece1c8","kind":"concept","schema_version":1,"statement":"[Theorem 159 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit} and \ref{Assumptions_analyticity}. Let $L \in \amsmathbb{Z}_{> 0}$ and a $L$-tuple of integers $\boldsymbol{h} \in [H]^L$ both independent of $\N$, let a (possibly $\N$-dependent) $L$-tuple of functions $\boldsymbol{f}(z)$ such that $f_l(z)$ is twice continuously differentiable in $\amsmathbb{A}_{h_l}^{\mathfrak{m}}$ and is a holomorphic function of $z$ in a $\N$-independent complex neighborhood $\amsmathbb{K}_h$ of $\bigcup_{k = k^-(h_l)}^{k^+(h_l)} [\overline{\alpha}_k,\overline{\beta}_k]$. Assume there exists a constant $C > 0$ such that $\max_{l} \sup_{z \in \amsmathbb{K}_h} |f_l(z)| \leq C$.

Let $\textnormal{\textsf{\textbf{Gau\ss{}}}}[\boldsymbol{f}]$ be a $L$-dimensional random Gaussian vector independent of the $K$-dimensional discrete Gaussian vector $\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}$ appearing in Theorem~\ref{Theorem_CLT_for_filling_fractions_saturation}, having covariance
\begin{equation}

\textnormal{\textsf{Cov}}_{l_1,l_2}[\boldsymbol{f}] = \sum_{k_1=k^-(h_{l_1})}^{k^+(h_{l_1})} \, \sum_{k_2=k^-(h_{l_2})}^{k^+(h_{l_2})} \oint_{\gamma_{l_1}} \oint_{\gamma_{l_2}}
 f_{l_1}(z_1) f_{l_2}(z_2)
\,\mathcal{F}_{k_1,k_2}(z_1,z_2)\,\frac{\dd z_1 \dd z_2}{(2\ii\pi)^2}.
\end{equation}
and $l$-th component of the mean equal to the sum of $\mathbbm{Rest}[f_l]$ in \eqref{Elink1} and $\mathbbm{Rest}'[f_l]$ in \eqref{Elinkm2} below.
