    \item $X^r_{\tau^r_x}=0$ and $B_{\tau^r_x}=x$;
    \item $\mathcal L(t,x)>\mathcal L(\tau^r_x,x)$ for $x<L_t^r$ and $\mathcal L(t,x)\le \mathcal L(\tau^r_x,x)$ for $x\ge L_t^r$. In particular, $L^r_t=\sup\{x>r\,:\, \mathcal L(t,x)>\mathcal L(\tau^r_x,x)\}\lor r$ where $\sup\emptyset=-\infty$ by convention;
