{"assumptions":[],"created_at":"2026-10-27T11:26:52.654806+00:00","domain":"probability theory","id":"claim_aade92c771dcc6d6339c0ff9c116b16b4a66db371899f4d29a803f196ae184fc","kind":"theorem","schema_version":1,"statement":"[Prop 12 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $a>0$, $M=a|\mathbb{B}_R|$ and consider a sequence $(u_l)_{l\ge 1}$ in $\Sigma_a$. For $l\ge 1$, we set $\lambda_l:=\|u_l\|_\infty^{1/d}$, 
\begin{equation}
	P_l(x):=\frac{1}{\lambda_l^d}u_l\left(\frac{x}{\lambda_l}\right)\,,\quad x\in \bar{\mathbb{B}}_{\lambda_l R}\,,
\end{equation} 
and
\begin{equation}
	\varphi_l(x):=\frac{1}{\lambda_l^{d-2}}\phi'\left(u_l\right)\left(\frac{x}{\lambda_l}\right)\,,\quad x\in \bar{\mathbb{B}}_{\lambda_l R}\,.
\end{equation}
Then there are $P\in C(\mathbb{R}^d)$ and $\varphi\in C^2(\mathbb{R}^d)$ such that, up to a subsequence, 
\begin{equation*}
	P_l\rightarrow P \ \text{ in }\ C(\mathbb{R}^d)\,,\qquad \varphi_l\rightarrow \varphi \ \text{ in }\ C^2(\mathbb{R}^d)\,.
\end{equation*}
Assume in addition that $\|u_l\|_\infty\to\infty$ as $l\to\infty$. Then both $P$  and $\varphi$ are non-increasing with respect to $r=|x|$ with $P(0)=1$, and $P$ has compact support $\bar{\mathbb{B}}_{\rho_0}$ for some $\rho_0\in (0,\infty)$. Furthermore, $\varphi$ satisfies
\begin{equation}
	-\Delta \varphi=\left(\frac{m-1}{m}\right)^{1/(m-1)}\varphi_+^{1/(m-1)}\ \text{ in }\ \mathbb{R}^d
\end{equation}
with $\varphi_+=\max\{\varphi,0\}$, 
\begin{subequations}
\begin{equation}
	P^{m-1} = \dfrac{m-1}{m} \varphi_+ \;\;\text{ in }\;\; \mathbb{R}^d\,, 
\end{equation} 
and
\begin{equation}
 	\varphi(x)=\left\{\begin{array}{ll}
	\dfrac{m}{m-1} \rho_0^{2-d} \zeta\left(\dfrac{x}{\rho_0}\right)\,, & x\in \bar{\mathbb{B}}_{\rho_0}\,,\\[20pt]
	\dfrac{M_c}{\sigma_d}\dfrac{|x|^{2-d}-\rho_0^{2-d}}{d-2} \,, & x\in \R^d\setminus\bar{\mathbb{B}}_{\rho_0}\,.
\end{array}\right.
\end{equation}
\end{subequations}
Finally, it holds that $M\ge M_c$, the critical mass $M_c$ being defined in~\eqref{Mc}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.310504+00:00","domain":"probability theory","id":"claim_aae221bf316b21835a5550690ed6ea7f48b8279067b1c4584d8aaf5f122ae22f","kind":"theorem","schema_version":1,"statement":"[Proposition prop:convergenceOnepoint of arXiv:2411.14876, 'Limit theorems for stochastic exponentials of matrix-valued L\'evy processes \\'] Let $L$ be a L\'evy process in $\mathbb{R}^{d\times d}$ fulfilling (equation eq-nonsingular of the paper) and let $X$ be the corresponding stochastic exponential.
