{"assumptions":[],"created_at":"2026-10-26T19:40:21.311757+00:00","domain":"probability theory","id":"claim_ab523aa854b61eba7640bb3708cd108dc4ae94416d3842c7e2efc10119e8bd14","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$. For any $0 \le \theta \le d$ and $x, y \in \mathbb{R}^d$,
        \begin{equation}

            \mathbb{E} \delta(W_t -x) |W_t - y|^{-\theta} \le C |t|^{-(d-\theta)/2} |x - y|^{-\theta} |x|^{-\theta}.
        \end{equation}
        Similarly, for any $0 < k < d$ and $0 \le \theta \le k/2$,
        \begin{align}

        \mathbb{E} |W_t -x|^{-k} |W_t - y|^{-k} &\le C |t|^{-k/2} |x-y|^{-k}, \\

            \mathbb{E} |W_t -x|^{-k} |W_t - y|^{-\theta} &\le C |t|^{-(k-\theta)/2} |x|^{-\theta}|x-y|^{-\theta}.
        \end{align}
        Here, $C$ may depend on $d$ and $k$ but not on $t$, $x$, $y$, or $\theta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:55:18.932485+00:00","domain":"probability theory","id":"claim_ab561c85d763e744114a5dab16333f2e18ae3d448b8824a8a9dad81f114d8016","kind":"concept","schema_version":1,"statement":"[Conjecture conj:Clay of arXiv:2602.07920, 'On the position matrix of single-shelf shuffle and card guessing'] {[Clay]}

