{"assumptions":[],"created_at":"2026-10-27T20:33:21.477716+00:00","domain":"probability theory","id":"claim_ab87d2815d3334421edcefd8ffd319ce5ebce47b63d7188067c668b5fc5528a9","kind":"definition","schema_version":1,"statement":"[Definition def:moment-constraints of arXiv:2606.21391, 'Extreme points and faces in the moment problem'] Let $\mathbf{p}\colon X\to\mathbb{R}^d$ be measurable with respect to $\mathcal{F}$ and let
\begin{align*}
P\!_\mathrm{a.i.}  & \textstyle 
:=\{ \mu\in P\!_\mathrm{fin} : 
\text{$\mu$ is concentrated on a finite subset $\{x_1,\dots,x_k\}\subset X$}\\
& \textstyle \hspace{\widthof{$:=\{$}}
\text{such that $\mathbf{p}(x_1),\dots,\mathbf{p}(x_k)$ are affinely independent}\,\}.
\end{align*}
We refer to the measures in $P\!_\mathrm{a.i.}$ as finitely atomic measures having the 
affine independence property. Let $C\subset\mathbb{R}^d$ be a  convex subset and let
\begin{align*}
G_\mathrm{fin}(C) & \textstyle
:= \{\mu\in P\!_\mathrm{fin} : \int\mathbf{p}\mathrm{d}\mu\in C\},\\

G_\mathrm{a.i.}(C) & \textstyle
:= \{\mu\in P\!_\mathrm{a.i.} : \int\mathbf{p}\mathrm{d}\mu\in C\}.
\end{align*}
Let $Q\subset P$ be a convex set of probability measures. Denoting the components of 
$\mathbf{p}=(p_1,\ldots,p_d)$ by $p_i\colon X\to\mathbb{R}$, $i=1,\ldots,d$, we define
\begin{align*}
Q^\mathbf{p} & \textstyle 
:= \{\mu\in Q : \text{$p_i$ is $\mu$-integrable $\forall i=1,\dots,d$}\,\},\\

G(C) & \textstyle
:= \{\mu\in Q^\mathbf{p} : \int\mathbf{p}\mathrm{d}\mu\in C\}.
\end{align*}
We abbreviate $G_\mathrm{fin}(\mathbf{q}):=G_\mathrm{fin}(\{\mathbf{q}\})$, etc., for singletons 
$\{\mathbf{q}\}$ with elements $\mathbf{q}\in\mathbb{R}^d$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:33:11.958749+00:00","domain":"probability theory","id":"claim_ab898deeb30f3e10d31152295698cabbb0ad055130fbec7df44ce906cfff0d7d","kind":"concept","schema_version":1,"statement":"[Problem Universal lower-orthant thresholds of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[problem]{prob:threshold-vectors}
