{"assumptions":[],"created_at":"2026-10-27T10:25:49.873753+00:00","domain":"probability theory","id":"claim_acb8da3c1a8f06c12ef35a2e24e875d6b159dad57a9e182998a7569e788ab1c8","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] The following statements hold.

  \smallskip
  \noindent
  \textup{(i) (\textsf{Explicit Malliavin derivatives})}  For $\eps>0$,
  \begin{align}
    D_{j,y}B_i^\eps(t)
    &=\dl_{ij}\bigl(\Phi^\eps(t-y)-\Phi^\eps(-y)\bigr),

      \\
    D_{j,y}\xi_i^\eps(x)
    &=\dl_{ij}\phi^\eps(x-y).
  \end{align}
  Consequently,
  \begin{align}
    D_{j,y}H_{x}^{\al,\eps}(\ga)
    =
    \begin{cases}
      \Phi^\eps(x+\ga_{j+1}-y)
      -\Phi^\eps(x+\ga_j-y),&0\leq j\leq n-1,\\[3pt]
      \al\bigl(\Phi^\eps(x+\ga_n-y)-\Phi^\eps(-y)\bigr),&j=n.
    \end{cases}
  \end{align}

  \smallskip
  \noindent
  \textup{(ii) (\textsf{Variance bound})}  Put
  $v_\eps(x,\ga)=\Var(H_{x}^{\al,\eps}(\ga)) =  \| D H_{x}^{\al,\eps}(\ga) \|_\fH^2  $.  Then
  \begin{align}
    -\al^2|x|+(1+\al^2)\ga_n
    -\eps(n+\al^2)\int_\R |r|(\phi\ast\phi)(r)\,dr
    \leq v_\eps(x,\ga)
    \leq \al^2|x|+(1+\al^2)\ga_n.
  \end{align}
  In particular, for every compact $K\subset\R$,
  \[
    \sup_{x\in K,\,0\leq\eps<1}v_\eps(x,\ga)
    \leq C_K(1+\ga_n).
  \]

  \smallskip
  \noindent
  \textup{(iii) (\textsf{Uniform free-energy moments and removal of the path
  truncation})}  For every compact $K\subset\R$, $p<\infty$, and
  $\lambda\in[0,\be)$,
  \begin{align}
    \sup_{\substack{x\in K,\ 1\leq R\leq\infty\\0\leq\eps<1}}
    \bigl\|\log Z_{x,R}^{\al,\be,\eps}(\lambda)\bigr\|_{L^p(\Omega)}
    <\infty.
  \end{align}
  For fixed $x$ and $\eps\in[0,1)$,
  \begin{align}
    \log Z_{x,R}^{\al,\be,\eps}(\lambda)
    \xrightarrow[R\to\infty]{L^p(\Omega)}
    \log Z_{x,\infty}^{\al,\be,\eps}(\lambda).
  \end{align}

  \smallskip
  \noindent
  \textup{(iv) (\textsf{Removal of the mollification})}  For every fixed $x$ and
  every $p<\infty$,
  \begin{align}
    \log Z_{x}^{\al,\be,\eps}
    \xrightarrow[\eps\downarrow0]{L^p(\Omega)}
    \log Z_{x}^{\al,\be}.
  \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:53.160386+00:00","domain":"probability theory","id":"claim_acbbb6992c8b7ace647ece299956d957720f95cfe2473f8b8dc4589f3b88fbeb","kind":"definition","schema_version":1,"statement":"[Definition 10 of arXiv:2607.02434, 'A Topological Formula for \\ Potts Lattice Gauge Theory Correlations'] Let $\Lambda \subset \Z^d$ be a box, let $q\geq 2,$ and let $0\leq i\leq d-1.$ For $f\in C^{i}\paren{\Lambda;\Z\paren{q}}$ define
\begin{equation*}
    H\paren{f}=-\sum_{\sigma\in \Lambda^{\paren{i}}}I_{\delta f\paren{\sigma}=1}\,.
\end{equation*}
The $i$-dimensional $q$-state Potts (hyper)lattice gauge theory on $\Lambda$ with inverse temperature $\beta$ is the measure
\[\nu_\Lambda\paren{f}=\nu^{\mathbf{f}}_{\Lambda,\beta,q,i}\paren{f} \propto e^{-\beta H\paren{f}}\,.\]
Furthermore, let $f' \in C^{i}\paren{\Lambda;\Z\paren{q}}$ satisfy $f'\paren{\sigma} = 1$ for $\sigma\in \paren{\partial \Lambda}^{\paren{i}}$ and $f'\paren{\sigma} = f\paren{\sigma}$ for $\sigma \in \paren{\Lambda \setminus \partial \Lambda}^{\paren{1}}.$ Then the $q$-state Potts lattice gauge theory with constant boundary conditions and inverse temperature $\beta$ is the measure $\nu^1_\Lambda=\nu^1_{\Lambda,\beta,q,i}$ defined by
\[\nu^1_\Lambda\paren{f}\propto \nu_{\Lambda}\paren{f'} \propto e^{-\beta H\paren{f'}}\,.\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.549983+00:00","domain":"probability theory","id":"claim_acc37c98e41a98fde8039869a6fa74c9d5a1ef4edaa8687188ebdf53ed60ba23","kind":"concept","schema_version":1,"statement":"[Question eq:bounds_TVd of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] Fix $w, w' \in \{a,b\}^*$ two non-isomorphic words, and let $\mathbf{w}, \mathbf{w}'$ be the associated random functions. Which asymptotic bounds hold for their TV-distance? More precisely, determine which of the following two inequalities are strict:
