\begin{align}
x_I&=-\delta-E_I+F_I\frac{E_Se^{r_Iu}-E_IG_S}{e^{(r_I+r_S)u}-G_IG_S},\\
x_S&=\delta+E_S+F_S\frac{-E_Ie^{r_Su}+E_SG_I}{e^{(r_I+r_S)u}-G_IG_S},
\end{align}
where $u$ is the unique solution of  
\begin{equation}
    u-2\delta-E_I-E_S
=\frac{-E_IF_Se^{r_Su}-E_SF_Ie^{r_Iu}+2E_SF_SG_I}{e^{(r_I+r_S)u}-G_IG_S}.

\end{equation}

Moreover, the value function is given by
 \begin{equation}
V(x)=
\begin{cases}
x+\delta, & \text{if $x\leq x_I$},\\    
A_I e^{-r_I(x-x_S)}+A_S e^{r_S(x-x_I)},& \text{if $x_I\leq x\leq x_S$},\\
x-\delta, & \text{if $x\geq x_S$,}
\end{cases}
\end{equation}
with
\begin{equation}
A_I=\frac{-E_Ie^{r_Su}+E_SG_I}{e^{(r_I+r_S)u}-G_IG_S},
\quad
 A_S=\frac{E_Se^{r_Iu}-E_IG_S}{e^{(r_I+r_S)u}-G_IG_S}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:33.534888+00:00","domain":"probability theory","id":"claim_ad264326bff27a40c903d19c88b5a1200b8c12b0f92916057f480f706d25f701","kind":"concept","schema_version":1,"statement":"[Lemma 19 of arXiv:2603.28093, 'Random Stability of Random Variables'] Pick a distribution $Q$ on $[0, \infty)$, and assume $G(Q) \ne \{1\}$ is nontrivial. Then let $N$ be any nontrivial random variable with distribution from $G(Q)$, and let $Y$ be the standard $N$-stable random variable. Then:
\begin{itemize} 
\item $\mathbb E[N\ln N] < \infty$ if and only if $\mathbb E[Y] < \infty$;
\item $\mathbb E[N\ln^{a+1} N] < \infty$ for a fixed $a > 0$ if and only if $\mathbb E[Y\ln^{a}Y] < \infty$;
\item $\mathbb E[N^k] < \infty$ for a fixed $k = 2, 3, \ldots$ if and only if $\mathbb E[Y^k] < \infty$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

