				& f(\rho_0(\urm_0+\vbf,\rho_0\urm_0+\sqrt{\m r^2-\rho_0^2}\m u+\m r\wbf,\rho_0\urm_0+\sqrt{\m (\m r')^2-\rho_0^2}\m u+\m r'\wbf')
			\end{split}
		\end{equation*}
		where we used the short notation \(P_{\m Q^\perp}(\wbf) = (P_{\m Q^\perp}(\m w_1),...,P_{\m Q^\perp}(\m w_{d-k}))\) (and similarly for \(P_{\m Q^\perp}(\wbf'))\) and where we denote by \(d\m u_0\), \(d\vbf=d\m v_1... d\m v_k\), \(d\m u\), \(d\m u'\), \(d\wbf=d\m w_1... d\m w_{d-k}\) and \(d\wbf'=d\m w'_1... d\m w'_{d-k}\) the respective surface area measures on the corresponding spheres and where we associate to the Grassmannian \(\mathcal{L}^d_k\) its standard measure \(Q\), normalized such that
		\begin{equation*}
			\int\limits_{\mathcal{L}^d_k} d\m Q = \binom{d}{k (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.438593+00:00","domain":"probability theory","id":"claim_ae0f792d4e51f21876e31ef05daacf6323e1d3f2376283f1df11a85c723a3164","kind":"definition","schema_version":1,"statement":"[Defn 10 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p\in BS_\xi$. Write $p$ with its partial Fourier transform 
\begin{equation*}
    p(x,\xi)=\sum_{\nu\in \Z^d}p_\nu(x)e^{2i\pi\ps{\nu}{\xi}}
\end{equation*}
where for all $\nu\in \Z^d$, $p_\nu(x)=\int_{\T^d}p(x,\xi)e^{-2i\pi\ps{\nu}{\xi}}d\xi$. We define $\mathrm{Op}_h(p)$ as the operator acting upon $\mathrm{PS}$ by \eqref{Expression nouvelle procédure de quantif bis} and associate it with the infinite matrix $M_\infty(p)$ given by \eqref{Coef infinite matrix quantization}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:06:42.720052+00:00","domain":"probability theory","id":"claim_ae10c6cc42a7226d53ae5259e1c7225966ec94b70fb7c241f21805fe2dc9fa51","kind":"concept","schema_version":1,"statement":"[Cor main of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $\rho_0,\rho_1 \in {\mathcal P}(\mathbb{R}^n)$ with $W_2(\rho_0,\rho_1)<\infty$. Let  $\bar m^\varepsilon_0, \bar m^\varepsilon_1\in {\mathcal P}({\mathcal X_{\omega,\varepsilon}})$ with $W_2(\bar m^\varepsilon_0, \rho_0) \to 0$, $W_2(\bar m^\varepsilon_1, \rho_1) \to 0$.


     Let $(m^\varepsilon, J^\varepsilon)$ be  minimizers of the discrete action on $[0,1]$ with $m^\varepsilon_0 = \bar m^\varepsilon_0$, $m^\varepsilon_1 = \bar m^\varepsilon_1$. Then the curves have convergent subsequences $m^\varepsilon \stackrel{*}{\rightharpoonup} \rho$, $\iota J^\varepsilon \stackrel{*}{\rightharpoonup} j$, and
    \begin{equation*}
        C_\omega(\rho_0,\rho_1) = A_\omega(\rho,j) = \lim_{\varepsilon \to 0} \mathcal{A}_{\omega,\varepsilon}(m^\varepsilon, J^\varepsilon).
    \end{equation*}

    Here the homogenized Wasserstein distance $C_\omega$ can be characterized as either the minimal action
    \begin{equation*}
        C_\omega(\rho_0,\rho_1)= \min_{(\rho,j)}A_\omega(\rho,j)
    \end{equation*}
    or as the minimum Monge-Kantorovich cost
    \begin{equation*}
    C_\omega(\rho_0,\rho_1)= \min_{\gamma\in \mathrm{Cpl}(\rho_0,\rho_1)}\langle \gamma, f_\omega(y-x)\rangle,
    \end{equation*}
     where $\mathrm{Cpl}(\rho_0,\rho_1)$ is the set of all couplings of $\rho_0$ and $\rho_1$, i.e. all measures $\gamma\in {\mathcal P}(\mathbb{R}^n\times\mathbb{R}^n)$ with marginals $\rho_0$ and $\rho_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:30:36.791368+00:00","domain":"probability theory","id":"claim_ae1131d87dde2e8424bf108a8007185de0a22a64dcbc1ca0b31f489370bf8ee6","kind":"concept","schema_version":1,"statement":"[Theorem 15 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Suppose that $A :\rK \to H$ is a bounded linear operator. Then, $A$ is Hilbert--Schmidt if and only if there exists a (strongly) $\tilde{\kappa}$-measurable function
  $\Phi : \mO \to H$ with
\begin{equation}
\int_{\mO} \normm{\Phi(x)}_H^2\,\tilde{\kappa}(\d x)< \infty,
\end{equation}
such that
\begin{equation}
Af = \int_{\mO} f(x)\, \Phi(x)\, \tilde{\kappa}(\d x),
\;\; \forall\, f \in \rK,
\end{equation}
where the integral is a Bochner integral in $H$. In this case,
\begin{equation}
\normm{A}_{\HS(\rK, H)}^2
= \int_{\mO} \normm{\Phi(x)}_H^2\, \tilde{\kappa}(\d x),
\end{equation}
where $\normm{A}_{\HS(\rK,H)}^2$ is the Hilbert-Schmidt norm defined by  
  \begin{equation}
    \normm{A}_{\HS(\rK,H)}^2
    = \sum_{n=1}^\infty \normm{A \tilde{e}_n}_H^2
  \end{equation}
  for any complete orthonormal system $(\tilde{e}_n)_{n=1}^\infty$ in $\rK=L^2(\mO, \tilde{\kappa})$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.862318+00:00","domain":"probability theory","id":"claim_ae12c968ef33343d7a16ec7856cac822744ffa7fa6d57b3cb869a846a1553691","kind":"concept","schema_version":1,"statement":"[Theorem 16 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Suppose Assumptions \ref{Ass:Half_Step} and \ref{Aspt_new} hold. Let $K_\eps$ satisfy Assumption \ref{Ass:kernel}. Let $h,T>0$ such that $T/h\in{\mathbb N}$, $\eps,\delta \in (0,1)$ and $ \hX_{jh}^{h,\eps,\delta}$ be defined in Equation \eqref{eq_Xhepsdelta} for $j\in \{0,\dots,\frac Th\}$. Recall $\lambda$ from Equation \eqref{Eq_lambda}.
