         Here the hidden constant explodes as $p\rightarrow 1$ or $p \rightarrow \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.855309+00:00","domain":"probability theory","id":"claim_ae14ba87c29f0dbe40b65bdd61c5713fe844cebace7786c92f5212092f1f6091","kind":"concept","schema_version":1,"statement":"[Lemma th:BHI of arXiv:2410.23974, 'Polynomial rate of relaxation for the Glauber dynamics of infinite-volume critical Ising m'] Consider the Ising model (equation eq:free-ising of the paper) on a finite subgraph $G\subset\Z^{d}$ with any boundary condition $\omega$. Let $F:\Omega_{G}\mapsto\mathbb{R}_{+}$ be an arbitrary square-integrable non-negative function, we have
    \begin{equation}
        \sum_{x\in G}\cov^{\omega}_{G}(F,\sigma_{x})^{2}\leq\frac{64c_{M}}{\gamma_{G}^{2}}D^{\omega}_{G}(\sqrt{F}).
    \end{equation}
    In particular, $c_{M}$ denotes the $L^{\infty}$ upper bound for the flipping rates (see (equation eq:bound-rates of the paper)). $\cov^{\omega}_{G}(\cdot,\cdot)$ and $D^{\omega}_{G}(\cdot)$ denote the covariance and Glauber Dirichlet form with respect to the Ising measure on $G$. $\gamma_{G}$ refers to the log-Sobolev constant of the Ising model on $G$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:38:37.404144+00:00","domain":"probability theory","id":"claim_ae15d8de2ee0a5b1d136abea03429a11f2f368490b3762214452541491ad91b5","kind":"lemma","schema_version":1,"statement":"[Lem 14 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] (A priori estimates) Let Assumption \ref{assu:assum for F} and Assumption \ref{assu:assu for existence} hold for some $p\in[2,\infty)$.

For any $n\in\mathbb{N}$ and $\alpha,\varepsilon\in(0,1)$, let $u_{\alpha,n,\varepsilon}$ be a solution of \eqref{eq:appro penalized eq}, then we have
\begin{description}
  \item[(1)] almost surely for every $t\in[0,T]$,
\begin{equation}
\Vert u_{\alpha,n,\varepsilon}(t)\Vert_{L^{1}(\mathbb{T}^{d})}=\Vert u_{\mathrm{init}}\Vert_{L^{1}(\mathbb{T}^{d})}-\int^t_0\Vert\varepsilon^{-1}(u_{\alpha,n,\varepsilon}-\psi)^{+}\Vert_{L^{1}(\mathbb{T}^{d})}\mathrm{d}s,
\end{equation}
  \item[(2)] for any $\phi\in C_c^\infty([0,T))$,
\begin{align}
 & -\mathbb{E}\int_{0}^{T}\int_{x}\partial_t\phi(t)|u_{\alpha,n,\varepsilon}|^2\mathrm{d}t \\
 & =\mathbb{E}\int_{x}\phi(0)|u_{\mathrm{init}}|^{2}-2\mathbb{E}\int_{0}^{T}\int_{x}\phi(t)\big(\Phi^{\prime}(u_{\alpha,n,\varepsilon})|\nabla_{x}u_{\alpha,n,\varepsilon}|^2+\alpha|\nabla_{x}u_{\alpha,n,\varepsilon}|^2\big)\mathrm{d}t \nonumber\\
 & \quad-\frac{2}{\varepsilon}\mathbb{E}\int_{0}^{T}\int_{x}\phi(t)|(u_{\alpha,n,\varepsilon}-\psi)^{+}|^{2}\mathrm{d}t-\frac{1}{2}\mathbb{E}\int_{0}^{T}\int_{x}\phi(t)\sigma^2_{n}(u_{\alpha,n,\varepsilon})(\nabla_{x}\cdot F_{2}-2F_3)\mathrm{d}t\nonumber \\
 & \quad-\frac{2}{\varepsilon}\mathbb{E}\int_{0}^{T}\int_{x}\phi(t)(u_{\alpha,n,\varepsilon}-\psi)^{+}\psi\mathrm{d}t,\nonumber
\end{align}
  \item[(3)] there exists a constant $C$ independent of $n$, $\alpha$, and $\varepsilon$ such that
\begin{align}
 & \sup_{t\in[0,T]}\mathbb{E}\Vert u_{\alpha,n,\varepsilon}(t)\Vert_{L^{p}(\mathbb{T}^{d})}^{p}+\mathbb{E}\Vert|u_{\alpha,n,\varepsilon}+1|^{\frac{p-2}{2}}\nabla_{x}\llbracket\sqrt{\Phi^{\prime}}\rrbracket(u_{\alpha,n,\varepsilon})\Vert_{L^{2}(Q_{T})}^{2} \\
 & +\alpha\mathbb{E}\Vert|u_{\alpha,n,\varepsilon}+1|^{\frac{p-2}{2}}\nabla_{x}u_{\alpha,n,\varepsilon}\Vert_{L^{2}(Q_{T})}^{2} +\varepsilon^{-1}\mathbb{E}\Vert|u_{\alpha,n,\varepsilon}+1|^{\frac{p-2}{2}}(u_{\alpha,n,\varepsilon}-\psi)^{+}\Vert_{L^{2}(Q_{T})}^{2}\nonumber\\
 & +\mathbb{E}\Vert|u_{\alpha,n,\varepsilon}+1|^{p-2}\varepsilon^{-1}(u_{\alpha,n,\varepsilon}-\psi)^{+}\Vert_{L^{1}(Q_{T})}\nonumber \\
 & \leq C\Big(1+\mathbb{E}\Vert u_{\mathrm{init}}\Vert_{L^{p}(\mathbb{T}^{d})}^{p}+\mathbb{E}\Vert u_{\mathrm{init}}\Vert_{L^{1}(\mathbb{T}^{d})}^{m+p-1}\Big).\nonumber
\end{align}
\end{description}
The estimate (\ref{eq=00FF1Apriori p}) also holds when $p=2$, that is
\begin{align}
 & \sup_{t\in[0,T]}\mathbb{E}\Vert u_{\alpha,n,\varepsilon}(t)\Vert_{L^{2}(\mathbb{T}^{d})}^{2}+\mathbb{E}\Vert\nabla_{x}\llbracket\sqrt{\Phi^{\prime}}\rrbracket(u_{\alpha,n,\varepsilon})\Vert_{L^{2}(Q_{T})}^{2}+\alpha\mathbb{E}\Vert\nabla_x u_{\alpha,n,\varepsilon}\Vert_{L^{2}(Q_{T})}^{2} \\
 & +\varepsilon^{-1}\mathbb{E}\Vert(u_{\alpha,n,\varepsilon}-\psi)^{+}\Vert_{L^{2}(Q_{T})}^{2}+\mathbb{E}\Vert\varepsilon^{-1}(u_{\alpha,n,\varepsilon}-\psi)^{+}\Vert_{L^{1}(Q_{T})}\nonumber\\
 & \leq C\Big(1+\mathbb{E}\Vert u_{\mathrm{init}}\Vert_{L^{2}(\mathbb{T}^{d})}^{2}+\mathbb{E}\Vert u_{\mathrm{init}}\Vert_{L^{1}(\mathbb{T}^{d})}^{m+1}\Big).\nonumber
\end{align}","status":"unverified"}

