{"assumptions":[],"created_at":"2026-10-28T00:26:20.625936+00:00","domain":"probability theory","id":"claim_ae8b7e2259f680b50741b0d050aeead8c8de33620f04b7ca6f25282bacee6625","kind":"lemma","schema_version":1,"statement":"[Lemma lem:f^ER_Bass-bounds of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Consider the Bass/{\rm SI} model~{\rm ((eqs:Bass-SI-models-ME of the paper),(eqs:ER-network of the paper))} on infinite sparse {\rm ER}~networks. 
	\begin{enumerate}
		\item 
		When $\lambda=0$, the expected/infection adoption level is the same as on networks of isolated nodes,
		i.e., 
		\begin{equation}

			f^{\rm ER}(t;p,q,I^0,\lambda=0) = f^{\rm isolated}(t;p,I^0),
			\qquad 	f^{\rm isolated}:=I^0 + (1-I^0)(1-e^{-pt}).
		\end{equation}


		\item  



		$\lim_{\lambda \to \infty} f^{ \text{\rm ER}}(t;p,q,I^0,\lambda) = f^{\rm compart}(t;p,q, I^0)$,

		where $ f^{\rm compart}$ is the expected adoption/infection level
		in the  compartmental Bass/{\rm SI} model
		\begin{equation}

			\frac{df}{dt} = (1-f)(p+qf), \qquad f(0) = I^0.
		\end{equation}

	\item  For $0<\lambda<\infty$,
		\begin{equation}

			f^{\rm isolated}(t;p,I^0)  < f^{\rm ER}(t;p,q,I^0,\lambda)  < f^{\rm compart}(t;p,q,I^0), \qquad t>0.
		\end{equation}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:56:37.644859+00:00","domain":"probability theory","id":"claim_ae8e644c01db4b230073b2547966d1e086471e822a58314596f22c86330f2201","kind":"definition","schema_version":1,"statement":"[Def Random cluster representation of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] The generalised random cluster representation on a finite subset $\Lambda \subset \mathbb Z^d$ with parameters $\beta\geq  0$ and $\mathsf h\in (\mathbb R^+)^\Lambda$, and boundary conditions $(\xi,\mathsf{b})$ is the probability measure $\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}$ on $ \{0,1\}^{\overline E(\Lambda[\mathsf h])}\times (\mathbb R^+)^{\overline \Lambda} $ defined by
\begin{equation}
\mathrm{d}\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}[(\omega,\mathsf a)] = \phi^\xi_{\Lambda, \beta, \mathsf h, \mathsf a}[\omega] \mathrm{d}\mu^{(\xi,\mathsf{b})}_{\Lambda, \beta, \mathsf h}[\mathsf a].
\end{equation}
We write $\Phi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf{h}}$ for the distribution of the $\omega$-marginal of $\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.967778+00:00","domain":"probability theory","id":"claim_ae8f975248c15dbce188f57c3f4dc6eb518de36171e43b1237c0cfb4ecd89f65","kind":"lemma","schema_version":1,"statement":"[Lemma 16 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] For any \(f \in \CF_{N - 1}\), we have the estimate
  \begin{equation}
    \begin{split}
      &\ \|R^{\phi(\mathbf{Y}), f}\|_{(N - |f|)\gamma}\\
