while by  convention  $\underline{\Phi_3V_0}=\underline{\Phi_3V_1}=\underline{\Phi_3V_2}=0$,  $\underline{\Phi_3V_3}=\Phi_3$ and $\underline{\Phi_2 V_n}:=\Phi_2V_{n-2}$. 

\item[(iii)]  Similarly, we introduce 
\begin{equation}
    (\widehat{\Phi}_3)_{xy}:=|\widehat{H}_{xy}|^2\widehat{H}_{xy}, ~~(\widehat{\Phi}_2)_{xy}:=\delta_{xy}\sum_{z}B_{xz}^2\sigma_{xz}^2(|\widetilde{W}_{xz}|^2-1),
