{"assumptions":[],"created_at":"2026-10-27T10:34:20.727074+00:00","domain":"probability theory","id":"claim_b0c985f94ba39cc3a84c27f36a94bae44295e43e1d96dd811aaba99481441762","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2609.02197, '2609.02197'] Let $\left(q,m\right) \in \left[1,+\infty\right[\times \mathbb{N}^*.$
\begin{enumerate}
\item We denote by $L^2\left(\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m\right)$ the set of functions $g:\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m\longrightarrow\mathbb{R}$ such that $g$ is a $\left(\mathcal{B}\left(\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m\right),\mathcal{B}\left(\mathbb{R}\right)\right)$-measurable function and $$\int_{\left(\mathbb{R}_+\times \mathbb{T}^d\right)^m}\left|g\left(x\right)\right|^2\,\mathrm{d}x<+\infty.$$
\item We denote by $L^q\left(\mathbb{T}^d\right)$ the set of functions $g:\mathbb{T}^d\longrightarrow\mathbb{R}$ such that $g$ is a $\left(\mathcal{B}\left(\mathbb{T}^d\right),\mathcal{B}\left(\mathbb{R}\right)\right)$-measurable function and $$\int_{\mathbb{T}^d}\left|g\left(x\right)\right|^q\,\mathrm{d}x<+\infty.$$
We also define
\begin{align*} 
\left\Vert\cdot\right\Vert_{L^q\left(\mathbb{T}^d\right)}: L^q\left(\mathbb{T}^d\right) &\longrightarrow \mathbb{R}_+ \\ h & \longmapsto \left\Vert h\right\Vert_{L^q\left(\mathbb{T}^d\right)}=\left(\int_{\mathbb{T}^d}\left|h\left(x\right)\right|^q\,\mathrm{d}x\right)^{\frac{1}{q}}
\end{align*}
\item We denote by $L^\infty\left(\mathbb{T}^d\right)$ the set of functions $g:\mathbb{T}^d\longrightarrow\mathbb{R}$ such that $g$ is a $\left(\mathcal{B}\left(\mathbb{T}^d\right),\mathcal{B}\left(\mathbb{R}\right)\right)$-measurable function and there exists $\mu \in \mathbb{R}_+$ such that $\left|g\left(x\right)\right|\leq \mu$ $\mathrm{d}x$-almost everywhere on $\mathbb{T}^d.$
\\
We also define
\begin{align*} 
\left\Vert\cdot\right\Vert_{L^\infty\left(\mathbb{T}^d\right)}: L^\infty\left(\mathbb{T}^d\right) &\longrightarrow \mathbb{R}_+ \\ h & \longmapsto \left\Vert h\right\Vert_{L^\infty\left(\mathbb{T}^d\right)}=\mathrm{ess\,sup}_{x \in \mathbb{T}^d}|h\left(x\right)|
\end{align*}
\end{enumerate}","status":"unverified"}

