{"assumptions":[],"created_at":"2026-10-27T19:55:37.874775+00:00","domain":"probability theory","id":"claim_b179eb670766b3f93ce1c161458f77c28213f49f62a9969667b95ba7b7712673","kind":"theorem","schema_version":1,"statement":"[Coro normalizedsequence of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] Define the normalized sequence $\{\gamma_n\}_n$ by
    \begin{equation*}
        \gamma_n := \frac{n! \varepsilon_n}{(b-a)^n}
        =
        \mathbb{E}\mleft[\mleft(\frac{b-X}{b-a} \mright)^n \mright] \in [0,1], \qquad n \geq 0.
    \end{equation*}
    Then the following hold:
    \begin{coroitems}
        \item The sequence $\{\gamma_n\}_n$ is non-increasing and bounded in $[0,1]$, and satisfies $\gamma_n \searrow \mathbb{P}(X = a)$ as $n \to \infty$. 
        \item For all $\delta \in (a,b)$, 
        \[
            \gamma_n
            \leq \mathbb{P}(X \leq \delta) + \mleft(\frac{b- \delta}{b-a}\mright)^n, \qquad n \geq 0.
        \]
        \item If there exists $\delta > 0$ such that $\mathbb{P}(X \geq a + \delta) = 1$, then 
        \begin{equation}
            \varepsilon_n \leq \frac{(b-a-\delta)^n}{n!}, \qquad n \geq 0.
        \end{equation}
        \item If $\mathbb{P}(X = a) > 0$, then
        \begin{equation}
            \lim_{n \to \infty} \frac{(n+1)\varepsilon_{n+1}}{\varepsilon_n} = b-a.
        \end{equation}
    \end{coroitems}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:10.191281+00:00","domain":"probability theory","id":"claim_b1818502350e5ed8714a0d63a1111a654bb795d882c00f21070934cd73774bc4","kind":"concept","schema_version":1,"statement":"[Lemma 190 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] If a real-valued $f\in L_{2}(\Gamma_{i}(t_{0}))$, then
for any $s=1,2,...$ and $k_{1},...,k_{i}\in\{1,...,d_{1}\}$
