{"assumptions":[],"created_at":"2026-10-27T07:21:06.855556+00:00","domain":"probability theory","id":"claim_b28d76272c86be97a9144af4c93ad2d406a6b51eea31341df255172368ce3121","kind":"concept","schema_version":1,"statement":"[Lemma 14 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Suppose that $\sO\seq \R^d$ is an open and bounded set. Let $q\in[2,\infty)$. Let $v$, $\phi$, $\Phi_j$, $\psi_n \colon [0,T]\times\Omega \to L^q(\sO)$ be progressively measurable for $j\in\{1, \ldots, d\}$ and $n\geq 1$, and suppose that
 \begin{itemize}
  \item $v_0 \in L^0_{\F_0}(\Omega; L^q(\sO))$,
  \item $v\in L^2(0, T; H^{1,q}(\sO))\cap C([0,T];L^q(\sO))$ a.s.,
  \item $\phi \in L^1(0,T;L^q(\sO))$ a.s.,
  \item $\Phi \in L^2(0,T; L^q(\sO;\R^d))$ a.s.,
  \item $(\psi_n)_{n\geq 1}\in L^2(0,T;L^q(\sO; \ell^2))$ a.s.,
 \end{itemize}
and a.s.\ for all $t\in[0,T]$, the following identity holds true for all $\varphi\in H^1(\sO)$
\begin{equation}
(v(t), \varphi)_{L^2} = (v_0, \varphi)_{L^2}
+ \int_0^t (\phi(s), \varphi)_{L^2} \ds - \int_0^t (\Phi(s), \grad \varphi )_{L^2} \ds  + \sum_{n \geq 1} \int_0^t (\psi_n(s), \varphi)_{L^2} \dWsn.
\end{equation}
Then, a.s.\ for all $t \in [0,T]$,
\begin{align*}
\|v(t)\|_{L^q(\sO)}^q
&= \|v_0\|_{L^q(\sO)}^q
+ q \int_0^t \int_{\sO} |v(s)|^{q-2}
\left[v(s)\phi(s) - (q-1)\nabla v(s)\cdot \Phi(s)\right] \dx\ds \\
&\phantom{= } + q \sum_{n \geq 1} \int_0^t \int_{\sO}
|v(s)|^{q-2} v(s)\psi_n(s) \dx \dWsn + \frac{q(q-1)}{2} \int_0^t \int_{\sO}
|v(s)|^{q-2} \|\psi(s)\|_{\ell^2}^2 \dx\ds.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.752834+00:00","domain":"probability theory","id":"claim_b293f9cf92f4dc8709f7da68b62d43cbfd7c9ae1e5d6a3f0986f0a63ae5fa54b","kind":"lemma","schema_version":1,"statement":"[Lm 17 of arXiv:2609.03836, 'Koszul Orlik--Solomon Algebras from Non-supersolvable Arrangements'] Let $M$ be a matroid and let $F$ be a modular flat of $M$ of positive rank.
