\begin{equation}
 U(y)=\frac{y^2}{2}-\frac12-\frac12\log2
 -\int_{\sqrt2}^{\left\lverty\right\rvert}\sqrt{z^2-2}\,\,\mathrm d z,
 \qquad \left\lverty\right\rvert>\sqrt2.
\end{equation}","status":"unverified"}

