{"assumptions":[],"created_at":"2026-10-27T17:18:19.451515+00:00","domain":"probability theory","id":"claim_b47d64d3b23f49cc1628ac64ae5d1f1665f1cefea53f6e3f0a4062adf34a6f71","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Gaussian_moment of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $g\sim\mathcal{N}(0,1)$. For non-negative integers $a$ and $b$, define
\begin{equation}
I(a,b) := \mathbb{E}\!\left[(g^2 - 1)^a g^{2b}\right].
\end{equation}
Then we have
\begin{itemize}
\item[(i)] \textbf{(Recursion)} For $a\ge 2$,
\begin{equation}
I(a,0)=  2(a-1)\big(I(a-1,0)+I(a-2,0)\big),
\end{equation} 
and for $a\ge 1, b\ge 1$,
\begin{equation}
I(a,b)=2a\, I(a-1,b)+ (2b-1)\,I(a,b-1),
\end{equation}
with initial conditions
\begin{equation}
I(0,0) =1,\quad I(1,0) =0,\quad I(0,b) = (2b-1)!!.
\end{equation}

\item[(ii)] \textbf{(Inequality)} For $b=0,\,a\ge 2$ or $b\ge 1,\,a\ge 0$,
\begin{equation}
 \mathbb{E}[g^{2a+2b}] \leq 2^a\, \mathbb{E}[(g^2-1)^a g^{2b}].
\end{equation}
\end{itemize}","status":"unverified"}

