{"assumptions":[],"created_at":"2026-10-27T05:44:27.967348+00:00","domain":"probability theory","id":"claim_b50a17de7455ab84af3290c687656870243eb7445d72460de6881ed1228523fb","kind":"concept","schema_version":1,"statement":"[Proposition 11 (Range, radius, depth and diameter) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] For every $x\in V$,
\begin{equation}
  \Ee[\pi(R_x^{\mathrm{raw}})]
  =\sum_{z\in V}\pi(z)h_q(x,z),
\end{equation}
and therefore, we get:
\begin{equation}
  \Ee[\pi(L_x)]
  \leq\sum_{z\in V}\pi(z)h_q(x,z).
\end{equation}
For $x\in V$, if $\operatorname{rad}(L_x):=\max_{y\in L_x}d(x,y),$
then, we find:
\begin{equation}
  \Pp(\operatorname{rad}(L_x)>R)
  \leq h_q(x,B(x,R)^c)
\end{equation}
and hence, it comes:
\begin{equation}
  \Pp(\operatorname{rad}(L_x)>R)
  \leq
  1-\frac{1}{\pi(x)}
  \Ee^{B(x,R)}_{\{x\}}\left[\pi(S_{T_q}^{B(x,R)})\right].
\end{equation}
Let $\operatorname{depth}_q(x)$ be the number of edges from $x$ to $\rho_q(x)$ in the
forest.\\
For every integer $m\geq0$, we get
\begin{equation}
  \Pp(\operatorname{depth}_q(x)\geq m)
  \leq\left(\frac{1}{1+q}\right)^m,
\end{equation} 
and also
\begin{equation}
  \Ee[\operatorname{depth}_q(x)]\leq\frac1q.
\end{equation}
Furthermore, for every $R\geq0$, it comes
\begin{equation}
  \Pp(\operatorname{diam}(C_q(x))\geq R)
  \leq
  \sum_{\substack{y\in V\\d(x,y)\geq R/2}}
  \sum_{z\in V}h_q(x,z)h_q(y,z),
\end{equation}
and also
\begin{equation}
  \Pp\bigl(\exists C:\operatorname{diam}(C)\geq R\bigr)
