\sup_{\fa\not\equiv \rm{const}} \frac{\int f\fa d\mu}{\|(-L_0)^{1/2}\fa\|_{L^q(\mu)}}
\le \|(-L_0)^{-1/2}f\|_{L^p(\mu)} 
\le 2 \sup_{\fa\not\equiv \rm{const}} \frac{\int f\fa d\mu}{\|(-L_0)^{1/2}\fa\|_{L^q(\mu)}}.
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:06:07.090782+00:00","domain":"probability theory","id":"claim_b5195af761284d237979ca936f6eb5d4fa4570a9b2d92ebaeb75db7e7c0d3dc2","kind":"theorem","schema_version":1,"statement":"[Prop 29 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Let $\mathcal{X}$ be  a vector field on $E_{U}$.  The following properties are equivalent:
\begin{enumerate}
\item[{\rm (i)}] There exists a vector field $X$ on $U$ such that  $(\mathcal{X},X)$ is a linear  local vector field on $E$.
\item[{\rm (ii)}]  When we consider $\mathcal{X}$ as a map from $\mathcal{F}(E_{U})$ to $\mathcal{F}(E_{U})$ then $\mathcal{X}(\mathcal{F}_L(E_{U}))\subset \mathcal{F}_L(E_{U})$ and $\mathcal{X}(\mathcal{F}_\pi(E_{U}))\subset \mathcal{F}_\pi(E_{U})$.
\item[{\rm (iii)}] The local flow $\mathfrak{F}_{\mathcal{X}}^t$ of $\mathcal{X}$ is a local bundle isomorphism for $E$ over the flow $\Fl_X^t$ of  $X$.
\end{enumerate}","status":"unverified"}

