    \operatorname{Var}\mleft[\widehat{\mathsf{N}}_G(X)\mright] \lesssim n^{2\mathsf{v}-3+\xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.923168+00:00","domain":"probability theory","id":"claim_b597a0920fd86e7b8f6b795291cf3ce328fc6289dd7b852e95c43541dd6fcf2c","kind":"concept","schema_version":1,"statement":"[Proposition prop_relation_pointandboundary of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d),
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d)>0$ such that 
	\begin{equation}
	M^{-\varsigma_d(N)}	\lesssim 	\frac{ \mathbb{P}^D\big(A\xleftrightarrow{\ge 0} x\big)}{\mathbb{P}^D\big(A\xleftrightarrow{\ge 0}  B(M)\big)}\cdot M^{(\frac{d}{2}-1)\boxdot (d-4)}	 \lesssim   M^{3\varsigma_d(M)}
	\end{equation}
for all $N\ge 1$ and $x\in \partial B(M)$ if either of the following two conditions holds:
\begin{enumerate}
	\item[(a)] $A\subset \widetilde{B}(N)$, $M\ge \ensuremath{C_{\ref*{const_relation_pointandboundary1}}}N^{( 1 \boxdot \frac{d-4}{2})+\varsigma_d(N)}$ and $D\subset  \widetilde{B}(N)\cup [\widetilde{B}(2M)]^c$;


	\item[(b)] $A\subset [\widetilde{B}(N)]^c$, $M\le \ensuremath{c_{\ref*{const_relation_pointandboundary2}}}N^{(1 \boxdot \frac{2}{d-4})-\varsigma_d(N)}$ and $D\subset  [\widetilde{B}(N)]^c \cup \widetilde{B}(\frac{1}{2}M)$.

