        2\left( \frac{1-q}{e^{-2x}+1} + \frac{q}{e^{2x} +1} \right)\left(\cosh(x)\right)^n(1 + o(1)),  &\text{ if } a = 0,\\
        2\left( \frac{1-q}{a+1}\mathds 1_{x>0} + \frac{q}{a+1} \mathds 1_{x<0} \right)\left( \fgd \right)^n(1 + o(1)),  &\text{if $a\in(0,1]$.}
        \end{array} \right.   
