c\,l_j\equiv 1\pmod n\quad\text{for every $j$ with at most one exception.}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.889017+00:00","domain":"probability theory","id":"claim_b6b83e4d406bef04bdb707ac8e145dbd5079ccbcfda735d045b3830bccc8fdbe","kind":"definition","schema_version":1,"statement":"[Definizione 14 (Composition law) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let us consider two stochastic transformations $T_1=(\Phi_1, B_1, \eta_1, h_1) \in S_m(M,M')$ and $ T_2=(\Phi_2, B_2, \eta_2, h_2)\in S_m(M',M'')$. We define $ T_2\circ T_1$ as the unique transformation corresponding to the composition $F_{T_2}\circ F_{T_1}$ of the associated isomorphisms, i.e. \begin{equation*}
 T_2 \circ T_1 := \big( \Phi_2 \circ \Phi_1, \ (B_2 \circ \Phi_1)  B_1, \ (\eta_2 \circ f_1)  \eta_1,\ \sqrt{\eta_1}B_1^{-1}( h_2 \circ \Phi_1) + h_1 \big) \in S_m(M,M''),
 \end{equation*}
 where $\Phi_2 \circ \Phi_1=(\tilde{\Phi}_2\circ \tilde{\Phi}_1,f_2\circ f_1).$
 In the same way, we define $\ T_1^{-1}$ as the unique transformation corresponding to the inverse isomorphism $\ F_{T_1}^{-1}$, i.e.
 \begin{equation*}
        T_1^{-1}:=( \Phi_1^{-1}, \ (B_1 \circ \Phi_1^{-1})^{-1}, \ (\eta_1 \circ f_1^{-1})^{-1}, - \frac{1}{\sqrt{\eta_1}} B_1  h_1 \circ \Phi_1^{-1}) \in S_m(M',M).
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:42:57.238721+00:00","domain":"probability theory","id":"claim_b6b8cedbaf606189c72db8474256f675badf921046416452506c9cb85b969fc3","kind":"lemma","schema_version":1,"statement":"[Lemma lem:comparison_of_fields of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Fix $b \in (0,a/100)$ deterministic and depending only on $a$.  Suppose that we have the setup described above and let $\hat{\Psi}_1$ denote the GFF on $\BD$ with boundary conditions given by $b_j$ on the counterclockwise arc of $\partial \BD$ from $\hat{x}_j$ to $\hat{x}_{j+1}$ for all $j \in \{1,2,3,4\}$.  Let $\mathcal{Z}_{\varepsilon}$ denote the Radon--Nikodym derivative of the conditional law of $\tilde{\Psi}_1$ restricted to $\BD \setminus \bigcup_{j=1}^4 \overline{B_{\varepsilon^b}(y_j)}$ with respect to the conditional law of $\hat{\Psi}_1$ restricted to $\BD \setminus \bigcup_{j=1}^4 \overline{B_{\varepsilon^b}(y_j)}$,  in both cases given the boundary conditions of $\tilde\Psi_1$ (in particular,  the points $\hat x_j , y_j$ and the values $b_j$).  Then,  for all $p>0$,  we have that
\begin{align*}
\BE[\mathcal{Z}_{\varepsilon}^p ] \to 1 \quad \text{as} \quad \varepsilon \to 0.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.859571+00:00","domain":"probability theory","id":"claim_b6b9ddd06c743d63fde2bf276885f84eb328353ccee7bab44fed1224ff07da36","kind":"concept","schema_version":1,"statement":"[Lem no-atom of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] {leadership}}] 
     Suppose that $(S_{j})_{j \in \mathbb{N}}$ is a sequence of mutually independent random variables such that $\sum_{j=1}^{\infty} S_{j}$ converges almost surely. Then the distribution of $\sum_{j=1}^{\infty} S_{j}$ contains an atom on $\mathbb{R}$ if and only if, for some collection $(c_{j})_{j \in \mathbb{N}} \in \mathbb{R}^{\mathbb{N}}$
        \begin{equation} 
            \forall j \in \mathbb{N} \quad \Prob{S_{j} = c_{j}} > 0 \quad \text{ and } \quad \sum_{j=1}^{\infty} \Prob{S_{j} \neq c_{j}} < \infty. 
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.728101+00:00","domain":"probability theory","id":"claim_b6ba61d436b0a30599f2e5ff8712c9b180ebc109848c4860f11c2d356c3a91ad","kind":"definition","schema_version":1,"statement":"[Definition def:mixing-time of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] For a probability measure $\mu$ on $\mathbf{S}_N$, let $P^t_{\mu}(A) = \mathbb{P}( X_t \in A \mid  X_0 \sim \mu )$. The (worst-case) mixing time is defined by:
    \begin{align*}
        t_{\mathsf{mix}}(\varepsilon) =  \inf \{ t >0 :\max_{x \in \mathbf{S}_N } d_{\textsc{tv}} ( P^t_x, \pi_{\beta} ) \leq  \varepsilon  \} \, .
    \end{align*}
    where $d_{\textsc{tv}}$ is the total-variation distance. 
    Given $M$, let $\mathcal{M}_E$ denote the collection of probability measures invariant under the map $e_1 \to - e_1$, then we define the symmetric mixing time to be:
    \begin{align*}
        t_{\mathsf{mix}}^{\mathsf{sym}} (\varepsilon) = \inf \{ t > 0 : \max_{\mu \in \mathcal{M}_E} d_{\textsc{tv}}( P^t_{\mu} ,\pi_{\beta}) \leq \varepsilon \} \, .
    \end{align*}
    We denote $t_{\mathsf{mix}}$ and $t_{\mathsf{mix}}^{\mathsf{sym}}$ as the values $t_{\mathsf{mix}}(1/4)$ and $t_{\mathsf{mix}}^{\mathsf{sym}}(1/4)$ respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:59:45.561952+00:00","domain":"probability theory","id":"claim_b6bb37051e42cb0d12745c934c672a0e2aa101dbad4d83d3854e9a2cba575022","kind":"concept","schema_version":1,"statement":"[Theorem eq: Levy-Ito decomposition of arXiv:2411.17109, 'On the maximal correlation of some stochastic processes'] If $(X_t,Y_t)_{t\geq 0}$ is a two-dimensional L\'{e}vy process, then there exists $b=(b^{X},b^{Y})\in\mathbb{R}^2$, a two-dimensional Brownian motion $(B^{X}_t,B^{Y}_t)_{t\geq 0}$ with the covariance matrix $\Sigma$ and a Poisson random measure $N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y)$ with the intensity measure $\mathrm{d}t\nu(\mathrm{d}x,\mathrm{d}y)$ such that for $t\geq 0$,
\begin{equation}
\begin{aligned}
X_t=b^{X}t+B^{X}_t+\int_{0}^{t}\int_{|x|<1}x\widetilde{N}^{X}(\mathrm{d}s,\mathrm{d}x)+\int_{0}^{t}\int_{|x|\geq 1}xN^{X}(\mathrm{d}s,\mathrm{d}x),\\
Y_t=b^{Y}t+B^{Y}_t+\int_{0}^{t}\int_{|y|<1}y\widetilde{N}^{Y}(\mathrm{d}s,\mathrm{d}y)+\int_{0}^{t}\int_{|y|\geq 1}yN^{Y}(\mathrm{d}s,\mathrm{d}y),
\end{aligned}
\end{equation}
where
\[N^{X}(\mathrm{d}t,\mathrm{d}x)=1_{x\neq 0}\int_{\mathbb{R}}N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y), N^{Y}(\mathrm{d}t,\mathrm{d}y)=1_{y\neq 0}\int_{\mathbb{R}}N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y),\] \[\nu^{X}(\mathrm{d}x)=1_{x\neq 0}\int_{\mathbb{R}}\nu(\mathrm{d}x,\mathrm{d}y), \nu^{Y}(\mathrm{d}y)=1_{y\neq 0}\int_{\mathbb{R}}\nu(\mathrm{d}x,\mathrm{d}y)\]
and
\[\widetilde{N}^{X}(\mathrm{d}t,\mathrm{d}x)=N^{X}(\mathrm{d}t,\mathrm{d}x)-\mathrm{d}t\nu^{X}(\mathrm{d}x), \widetilde{N}^{Y}(\mathrm{d}t,\mathrm{d}y)=N^{Y}(\mathrm{d}t,\mathrm{d}y)-\mathrm{d}t\nu^{Y}(\mathrm{d}y).\]
Moreover, $(B_t)_{t\geq 0}$ is independent of $N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y)$ and
\begin{equation*}
N(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y)=\sum_{(s,\Delta X_s,\Delta Y_s):(\Delta X_s,\Delta Y_s)\neq (0,0)}\delta_{(s,\Delta X_s,\Delta Y_s)}(\mathrm{d}t,\mathrm{d}x,\mathrm{d}y),
\end{equation*}
where $\delta_{z_0}(\mathrm{d}z)$ is the Dirac measure at $z_0\in[0,\infty)\times(\mathbb{R}^2\setminus\{(0,0)\})$. In addition, $(B^{X}_{t})_{t\geq 0}$ is a measurable function of $(X_t)_{t\geq 0}$, and $(B^{Y}_t)_{t\geq 0}$ is a measurable function of $(Y_t)_{t\geq 0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:10.888592+00:00","domain":"probability theory","id":"claim_b6bc6adbc92326dd05ffb7c7c5d9b0b7d1e42ddf0be0706299faf4c86a991129","kind":"definition","schema_version":1,"statement":"[Definition 30 of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $(M,d)$ be a proper geodesic metric space.
    A random closed subset $\mathcal Z$ of $M$ is called \emph{normal} if 
    \begin{itemize}
        \item[{\rm(i)}] the path-connected component of every $x\in M$ in $\mathcal{Z}$ is a closed set.
        \item[{\rm(ii)}] every bounded subset of $M$ intersects finitely many path-connected components of $\mathcal{Z}$.
    \end{itemize}
    We refer to the path-connected components as \emph{clusters}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.441088+00:00","domain":"probability theory","id":"claim_b6c234f46cdbed88b402433da95d912cca627ea2eba04cdcf861e4284315aac4","kind":"concept","schema_version":1,"statement":"[Lemma diagramno of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] {feldheim2010universality}; [geng2024outliers]}] 
