    \end{equation}
    Consequently, if $\varphi:\mathfrak{X} \to [-\infty,\infty)$ is such that $b(x,t) := (W \star \varphi)(x,t) < \infty$ for all $(x,t) \in \mathbb{R}^2$, then $b$ is an eternal solution.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:43:53.645884+00:00","domain":"probability theory","id":"claim_b71ea37bc1d718414e6148052118cf0d0f751a66c1c1c779bb0ccb838b171269","kind":"lemma","schema_version":1,"statement":"[Lemma lem:useful-bound of arXiv:2512.17747, 'On exponentially height-penalized random trees'] For any real number $\alpha\in\mathbb R$ and any two strictly positive numbers $\beta,\gamma>0$, consider the function
    \begin{align*}
        F_t(x,y)=\frac{t^\alpha}{x^\beta}\exp\left(-\frac{t}{y^\gamma}\right)\,.
    \end{align*}
    Let $a_+=a_+(t)$ be strictly positive and bounded, and $\epsilon=\epsilon(t)$ converging to $0$ as $t$ diverges. 
    Then there exists $k=k(t)$ an integer depending on $t$ and a sequence of increasing values $(a_0\leq\ldots\leq a_k)$ (implicitly depending on $t$) such that $a_0=\epsilon$, $a_k=a_+$, and satisfying
    \begin{align*}
        \lim_{t\rightarrow\infty}\sum_{i=1}^kF_t(a_{i-1},a_i)=0\,.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.420991+00:00","domain":"probability theory","id":"claim_b71f1bcdad639713c63560c0ad87453998996d58f631d1781a7f5ffd66e7e58c","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] The \emph{traffic distribution} of a family $\mathbf{A}_{N}$ of random matrices is the map
        \begin{equation}
            \Phi_{\mathbf{A}_{N}}:g\in\mathbb{C}\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle\rightarrow\mathbb{E}\left[\frac{1}{N}\tr\left(g(\mathbf{A}_{N})\right)\right].
        \end{equation}
        We say that the family $\mathbf{A}_{N}$ \emph{converges in traffic distribution} if $\Phi_{\mathbf{A}_{N}}$ converges point-wise.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:52:32.331557+00:00","domain":"probability theory","id":"claim_b72292b91783bbc8f9290e3eb3a8f1c3b5cdaa7f7ffa1fa9db0988b9e7084514","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Given a signed graph $\Sigma = (V,E,\sigma)$, define the \textit{chromatic (unsigned) symmetric function of $\Sigma$} as
    \begin{equation}
        X_\Sigma^\parallel:=\sum_{\kappa \text{ proper}}x_{|\kappa(v_1)|} \cdots x_{|\kappa(v_d)|}
    \end{equation}
    where $V = \{v_1,\dots,v_d\}.$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:17:17.091158+00:00","domain":"probability theory","id":"claim_b723078e85e030b999a45fb7b10373931cc154b95467bd0b47bf1ba2094fba6b","kind":"theorem","schema_version":1,"statement":"[Theorem 9 of arXiv:2608.19976, 'Random valuations'] Let $\Phi$ be a non-negative ID valuation.  Then there exists a
  unique (necessarily $\sigma$-finite) L\'evy measure $\Lambda$ on
  $\R_+^{\Kd}$ whose outer measure is concentrated on the family of valuations and a
  deterministic valuation $\phi$ such that, for any $m\ge1$, finite
  family $\sI=\{K_1,\dots,K_m\}\subset\Kd$, and $u\in\R_+^m$,
  \begin{displaymath}
    \E\exp\Big\{-\big\langle u,\Phi_{\sI}\big\rangle\Big\}
    =\exp\bigg\{-\langle u,\phi_{\sI}\rangle
    -\int_{\R_+^{\Kd}\setminus\{O_{\Kd}\}} \Big(1-e^{-\langle u,\psi_{\sI}\rangle}
    \Big)\Lambda(d\psi)\bigg\}.
  \end{displaymath}
  Furthermore, $\Phi$ is monotone if and only if $\phi$ is monotone
  and the $\Lambda$-outer measure is supported by monotone valuations.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:59:24.049687+00:00","domain":"probability theory","id":"claim_b72c80179a98b3ad43baa59c2a37c987b66df3a574daf6d0f02aa8d33d6f91dc","kind":"theorem","schema_version":1,"statement":"[Proposition prop:critical-shift of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] As $s\to\infty$,
\begin{equation}
 \mathcal R_{N,\beta}(s)
 =2N-\frac{(N-2)^2}{4s}
 +\frac{(N-2)(\beta_N^*-\beta)}{s^2}+O(s^{-3}),
\end{equation}
where
\begin{equation}
 \beta_N^*=\frac{N^3+18N^2+20N-24}{192}.
\end{equation}
If $\beta<\beta_N^*$, then $h_{N,\beta}$ cannot be a global supersolution for
the potential $A_N|n|^{-2}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:01:25.653172+00:00","domain":"probability theory","id":"claim_b72fbee58ef2f20cd52c3cfb19811c421b44eca419893a934bc56a6db3d50e26","kind":"definition","schema_version":1,"statement":"[Definition def:loops-loop variables of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] We will represent loops $\ell$ in $\Lambda$ by the sequence of oriented edges $\ell = e_1 \cdots e_n$ that are traversed by $\ell$. We denote $|\ell| := n$. Let $Q : E_\Lambda^+ \ra G$ be a lattice gauge configuration. For  a loop $\ell=e_1e_2\dots e_n$, let $Q_{\ell}:=Q_{e_1}Q_{e_2}\dots Q_{e_n}$ denote the corresponding loop variable. We define
\begin{equs}
W_\ell(Q) := \tr(Q_\ell),
\end{equs}
where $\tr = \frac{1}{N} \Tr$ is the normalized trace.
We refer to $W_\ell$ as a Wilson loop observable.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:55:18.919940+00:00","domain":"probability theory","id":"claim_b7366d7fcb504cbc0051fd027fe42b12cfbb3bd63cec3a8af900eae0e7cbc5ba","kind":"definition","schema_version":1,"statement":"[Definition def:URD of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] [URDog, EnergymethodRPDEs]
    Let $\alpha\in(\frac 13,\frac 12]$. An $\alpha$-continuous unbounded rough driver with respect to the scale $(H^{m})_{m>0}$ is a pair $(A^{1},A^{2})$ 
    of two index maps such that for any $s,t\in [0,T]$:
    \begin{align*}
        \norm{A^{1}_{s,t}}_{\mathcal{L}(H^{-m};H^{-(m+1)})} &\lesssim |t-s|^{\alpha}, \qquad m\in [0,2], \\
        \norm{A^{2}_{s,t}}_{\mathcal{L}(H^{-m};H^{-(m+2)})} &\lesssim |t-s|^{2\alpha}, \qquad
        m\in [0,1],
    \end{align*}
    and satisfies the Chen's relations: 
        $\delta A^{1}_{s,r,t}=0$ and $ \delta A^{2}_{s,r,t}=A^{1}_{r,t}A^{1}_{s,r}$  for all $ 0\leq s \leq r \leq t \leq T$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:57:30.994932+00:00","domain":"probability theory","id":"claim_b737820bdf5e57381c66b9677302a4f6b11d37754c37475993dbd510861dac52","kind":"theorem","schema_version":1,"statement":"[Theorem 46 (Scale-invariant reduced capture) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Assume $\mathfrak H:=\mathfrak H_Q(A,r)>0$.  Choose $q_*$ with maximal
$\lambda_*=\lambda_{\max}(E_{q_*})$, let $L_*$ be its full top eigenspace, and promote
\begin{equation}
 V_*=N_{q_*}R_{q_*}L_*.

\end{equation}
Then
\begin{equation}
 \lambda_*\ge\frac{\mathfrak H}{dQ},\qquad
 \inf_{0\ne c\in L_*}
 \frac{\norm{N_{q_*}R_{q_*}c}}{\norm{c}}
 \ge\frac{\mathfrak H}{dQR},

\end{equation}
and
\begin{equation}
 \sum_{a,q}\norm{P_{V_*}r_{a,q}}^2
 \ge
 \kappa_{Q,d}\frac{\mathfrak H}{R^2},
 \qquad
 \boxed{\kappa_{Q,d}=\frac1{dQa_Q}}.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.440063+00:00","domain":"probability theory","id":"claim_b73a9e645bdff2b87cc2b87c0405645bc3fc0d8db6824aae19bbf1cf17e1b49f","kind":"concept","schema_version":1,"statement":"[Theorem prop.Wells of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let $\Lambda \subseteq \ensuremath{\mathbb{Z}^d}_n$ be a finite set, then for any collection of nonnegative conductances $(J_{xy})_{ \{ x, y \} \in E(\Lambda)}$ and any pair of vertices $x , y \in \Lambda$,
    \begin{equation} 
         \left\langle \cos ( \theta_x - \theta_y ) \right\rangle_{\Lambda, J/4}^{\mathrm{XY}} \leq \mathbb{E}_{\nu_{\Lambda , J}} \left[ \left\langle \cos ( \theta_x - \theta_y ) \right\rangle_{\Lambda, J, r}^{\mathrm{XY}} \right].
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:04:39.224137+00:00","domain":"probability theory","id":"claim_b73fb10036138b9968693a73cd981a1a33a41dd2f5c125b95c7ccac1048752e1","kind":"lemma","schema_version":1,"statement":"[Lemma 9 (General Case Limit) of arXiv:2608.14143, 'Mod-$\phi$ convergence for random variables with cyclotomic generating functions'] Let $(s_N)_{N\in\N}$ be a sequence of positive integers. For each $N\in\N$, let $(a_{N,j})_{j=1}^N$ and $(b_{N,j})_{j=1}^N$ be sequences of positive integers. Define $h(w, z) := \log(\frac{1-e^{zw}}{-zw})$ for $w>0$, with $h(0, z) := 0$.
Recall the sequence
\[
K_N(z) := \Big( \prod_{j=1}^N \frac{a_{N,j}}{b_{N,j}} \Big) \Big(\prod_{j=1}^N \frac{1-e^{z b_{N,j}/s_N}}{1-e^{z a_{N,j}/s_N}}\Big).
\]
Define the sums $S_N^a(z) := \sum_{j=1}^N h(a_{N,j}/s_N, z)$ and $S_N^b(z) := \sum_{j=1}^N h(b_{N,j}/s_N, z)$. Assume there exist functions $I_a, I_b, C_a, C_b$ such that the following asymptotic expansions hold locally uniformly for $z$ in some domain $\mathscr{D} \subset \mathbb{C}$:
\begin{align*}
	S_N^a(z) &= N I_a(z) + C_a(z) + o(1),\qquad\text{and}\qquad S_N^b(z) = N I_b(z) + C_b(z) + o(1),
\end{align*}
as $N\to\infty$. Let $\phi(z) := I_b(z) - I_a(z)$. Then,
\begin{equation}
	\lim_{N\to\infty} \exp\big(-N \phi(z) \big) K_N(z) = \exp\big( C_b(z) - C_a(z) \big)
\end{equation}
locally uniformly on $\mathscr{D}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.635429+00:00","domain":"probability theory","id":"claim_b74eac54d0a177f9119ea974a5d0601db7a7fa505f335987071f7fbb1a0a04c4","kind":"concept","schema_version":1,"statement":"[Lemma 19 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $S$ be a reduction set for $G$ such that $S \subset \Vis$. 
    Then, there exists a classical spin model $ \widetilde{\vp}$ on the reduced graph $ \widetilde{G} = ( \widetilde{V}, \widetilde{E}) := R(G, S)$ such that 
    \begin{enumerate}[(i)]
	    \item the reference measure of all spins in $ \widetilde{V}$ is the same
        \item the boundary correlation functions are unchanged:
		\begin{equation}
		    \langle \vp({A}) \rangle = \langle \widetilde{\vp}(A) \rangle_{ \widetilde{G}}
            \end{equation}
            for all $A \subset W$. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.239175+00:00","domain":"probability theory","id":"claim_b74f551c2862fd5b18602d3b385b72d8a865fabf194e5afcfa72baad4893bf27","kind":"lemma","schema_version":1,"statement":"[Lemma lem: second moment of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] For every $\alpha_0, \lambda_0 \in (0,1)$, uniformly in $\alpha \in [\alpha_0,1)$, $\lambda \in [\lambda_0,1]$ and $\boldsymbol{F} \subset \mathbb{T}_N$ satisfying $|\boldsymbol{F}|=\lfloor\lambda N^d\rfloor$, 
        \begin{equation}

            \sum_{\boldsymbol{x}\neq \boldsymbol{y} \in \boldsymbol{F}}{\mathsf{P}(\boldsymbol{x},\boldsymbol{y} \in \mathcal{L}^\alpha)} \leq \big(1+o(1)\big)\big(\lambda N^{d(1-\alpha)}\big)^2.
        \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.763456+00:00","domain":"probability theory","id":"claim_b7534226d7318546c2bef3232da453d7d67d2ac26fba3faf6ee73de8b884e56e","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $(X_n)_{n \in \mathbb{N}}$ be a sequence of processes in $D_H$ such that 
    \begin{equation*}\lim_{n\rightarrow \infty}\ducp(X_n,\Lambda(X_n))= 0. 
    \end{equation*}
Then, there exists a process $X \in D_H$ so that 
$$ \lim_{n\rightarrow \infty}\ducp(X_n,X)= 0$$ and $X=\Lambda(X)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:53:10.158806+00:00","domain":"probability theory","id":"claim_b75b09289b04914276e57c5687175a260f6f72f58e773b657d7b5dd9d980d70c","kind":"concept","schema_version":1,"statement":"[Lemma FC2-free of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let ${\mathcal{C}}^\otimes$ be any symmetric monoidal $\infty$-category. Then evaluation at the free $C_2$-set $C_2$ defines an equivalence ${\textup{Fun}}^\otimes({\mathcal{F}}_{C_2}^\amalg,{\mathcal{C}}^\otimes)\xrightarrow{\;\smash{\raisebox{-0.25ex}{\ensuremath{\scriptstyle\sim}}}\;}{\textup{Fun}}(BC_2,{\mathcal{C}})$.
    \begin{proof}
        Write $\mathbb P\colon\Cat_\infty\to\CMon(\Cat_\infty)$ for the left adjoint to the forgetful functor. Then $\smash{\mathbb P({\mathcal X})\simeq\coprod_{n\ge 0}({\mathcal X}^{\times n})_{h\Sigma_n}}$ is a $1$-groupoid whenever ${\mathcal X}$ is so; it will therefore suffice to prove the universal property of $\smash{{\mathcal{F}}_{C_2}^\amalg}$ with respect to symmetric monoidal 1-categories, which is an instance of [global-mackey]*{Lemma~2.21}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:40:21.317772+00:00","domain":"probability theory","id":"claim_b75c8a21fd8fe2ba2bb1c399c45273c3af3d583a88259998fee0d1583b104803","kind":"theorem","schema_version":1,"statement":"[Proposition 11 of arXiv:2604.09248, '\bfseries Limit laws for longest edges in empty region graphs'] For $d\in\mathbb{N}$ with $d\ge 2$, $u\in(0,\infty)$, and a continuous symmetric function $R:[-u,u]\to[0,\infty)$ let
$$
K := \Big\{ (x_1,\hdots,x_d)\in \RR^d: x_1\in[-u,u], \sum_{i=2}^{d} x_i^2\leq R(x_1)^2 \Big\}.
$$
Assume that there exist $x_K\in K$ and $r_K>0$ such that $B^d(x_K,r_K)\subset K$. Then one can find a constant $c_K\in(0,\infty)$ only depending on $K$ and $d$ such that
\begin{equation}
\vol(K\setminus (\varrho K + x)) \geq c_K \|x\|    
\end{equation}
for all rotations $\varrho$ and all $x\in\RR^d$ with $K\cap(\varrho K+x)\neq\varnothing$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.200419+00:00","domain":"probability theory","id":"claim_b763a12590d7ee25184fedd79e3d5f34a87d4f66834849e3459ba267cf8a3c89","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Assume \eqref{assump:alpha}, \eqref{assump:moments}, \eqref{assump:nondeg}, 
	 \eqref{assump:mixedmoments} and (as a sufficient condition for \eqref{assump:cramer}) that the law of $(\log |A_1|, \log |A_2|)$ has an absolutely continuous component with respect to the Lebesgue measure on $\R^2$.
	 Suppose $\P(|A_1|>1, |A_2|>1)>0$ and that $\supp(X)$ contains an open set.

		Assume that there is $\bb \xi^* \in D \cap (0,1)^2$ such that  $\nabla \phi(\bb \xi^*)$ is parallel to $(1,1)$. 
		Then there exists a non-zero Radon measure $\Lambda_2$ on $\R^2\setminus[\mathsf{axes}]$ such that for all $f\in \bfC (\R ^2\setminus[\mathsf{axes}])$, 
	\begin{equation}
	\lim_{t \to \infty}	(\log t)^{1/2}	t^{\xi^*_1+\xi^*_2}\E\big[ f(t^{-1/\alpha_1}X_1,t^{-1/\alpha_2}X_2) \big]= \int f(\bb x) \Lambda_2(d\bb x).
	\end{equation}
	In particular,
	\begin{equation}
		\lim_{t \to \infty}	(\log t)^{1/2}	t^{\xi^*_1+\xi^*_2}\P\big( |X_1|>t^{1/\alpha_1}, |X_2|>t^{1/\alpha_2} \big) \in (0,\infty).
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:25:40.342788+00:00","domain":"probability theory","id":"claim_b76cba5109aa39c5c9dab86bdc81d838905e07f8a90130648e46171087982623","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] Let $M$ be a connected, complete, $d$-dimensional Riemannian manifold satisfying the following conditions 
\begin{enumerate}[i)]

    \item $M$ has positive global injectivity radius \(r_\text{inj}(M)>0\),\footnote{See Section (sec:localcomparison of the paper) or [LeeRM] for a precise definition.}

    \item the sectional curvatures of M are uniformly bounded from above and from below,\footnote{see, e.g., [LeeRM] for a definition and an introduction to sectional curvatures.}

    \item $M$ is simply connected and one-ended,\footnote{We call $M$ \emph{one-ended} when $M\setminus B$ has exactly one unbounded connected component for any bounded $B\subset M$.}

    \item there exists a log-expanding, bi-infinite path in $M$, i.e., a Lipschitz continuous path $\gamma:(-\infty,\infty)\to M$ satisfying, for some constants $c,C\in(0,\infty)$, the inequality
        \begin{equation}
            \mathrm{d}_{M}(\gamma(t),\gamma(s))\geq c\log |t-s|-C ~~~ \text{ for all } t,s\in(-\infty,\infty).
        \end{equation} 
\end{enumerate} 

Then, both $p_c(M,\lambda)$ and $p_u(M,\lambda)$ converge to $p_c(\mathbb R^d)$ as $\lambda\rightarrow \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.458118+00:00","domain":"probability theory","id":"claim_b76dd66d3a1f981d8bf1a71a1a1b234d6bd1fba96c005ab7a299ff494b841a17","kind":"concept","schema_version":1,"statement":"[Cor 35 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma \geq 1$, $0 \leq s \leq t \leq T$, $\delta \in [0, \; 1]$ and $n \in \mathbb{N}_+$. For $1 \leq \ell_n \leq L_n$, it holds
	\begin{align*}
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{n \sqrt{n} } \sum_{z=1}^{L_n-1} za(z)  \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )    \big[   \Psi_{x, \ell_n}^{\alpha,\beta}(\eta_r^n) - \Psi_{x,L_n}^{\alpha,\beta}(\eta_r^n)  \big]  \Bigg\}^{2} \Bigg] \\
		\leq & \widetilde{C} \| \nabla H \|^{2}_{2,n} (t-s)^{1 + \delta} \Bigg( \frac{\big[ \Theta(n) K_n\big]^{\delta+1} }{n^{2}} +  \frac{\big[ \Theta(n) \big]^{1+\delta} (K_n)^2  }{n^{2}}  L_n^{(\gamma-1)(1-\delta)}  \ell_n^{ \delta} \Bigg)  \big\{ \mathbbm{1}_{ \{ \gamma > 1 \} } + \big[ \log(L_n) \big]^{2} \mathbbm{1}_{ \{ \gamma = 1 \} } \big\}.
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.580314+00:00","domain":"probability theory","id":"claim_b76f4618f3fd7ce2639500e58f9c9388a5dc938e3120693cfa10c2b92222fca1","kind":"concept","schema_version":1,"statement":"[Proposition th-main of arXiv:2411.15401, 'The reference interval in higher-order stochastic dominance'] Let $a,b\in\mathbb{R}$ with $a<b$ and $n\in\mathbb{N}$. For $X,Y\in\mathcal X_{[a,b]}$, we have
\begin{align*}
&\mbox{(i) $X\ge_n^{[a,b]}Y$} \hspace{-0.3cm} & \iff  & \mbox{(ii) $\mathbb{E}[u(X)]\ge \mathbb{E}[u(Y)]$ $\forall u\in\mathcal U_n^{[a,b]}$} \hspace{-0.3cm} & \iff & \mbox{(iii) $\mathbb{E}[u(X)]\ge \mathbb{E}[u(Y)]$ $\forall u\in\overline{\mathcal U}_n^{[a,b]}$}   ; \\  
&\mbox{(iv) $X\ge_nY$} \hspace{-0.3cm}  & \iff  & \mbox{(v) $\mathbb{E}[u(X)]\ge \mathbb{E}[u(Y)]$ $\forall u\in\mathcal U_n$} \hspace{-0.3cm} &\iff  &\mbox{(vi) $\mathbb{E}[u(X)]\ge \mathbb{E}[u(Y)]$ $\forall u\in\overline{\mathcal U}_n$} ;
\end{align*}

and  (i) $\Rightarrow$ (iv) always holds true.  But (iv) $\Rightarrow$ (i) holds for all $X,Y\in \mathcal{X}_{[a,b]}$ if and only if $n\le 3$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.361942+00:00","domain":"probability theory","id":"claim_b772dd04a6dbe45c606dc364af2758e16883ad334e9701ee2d11ddd88589c8bc","kind":"theorem","schema_version":1,"statement":"[Proposition 58 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1} and \eqref{eq:3rd}. Then for every $k\ge 1$,
  \begin{align}
      \big(\widetilde{\mathscr{T}}^n_k,\{\widetilde{V}^n_i\}_{1\le i\le k}\big)\overset{d}{\longrightarrow} \big(\mathcal{T}_k^{\ell,\sigma},\{L_i\}_{1\le i\le k}\big)\text{ under the distance \eqref{fidis}}.
  \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:31:14.337601+00:00","domain":"probability theory","id":"claim_b77efeb6d5c3a1475a8ccbffe3b8c9d477e97deb066cf00cfacfa1e20a1b095d","kind":"lemma","schema_version":1,"statement":"[Lemma L: exponential_K_moment of arXiv:2606.18654, 'Rigidity of infinite exchangeable sequences with Gaussian marginals'] For $n \geq 1$ suppose that $a_1,\ldots, a_n \in \mathbb{R}$ satisfies $M_\eta(a_j) < \infty$ almost surely for all $j=1,\ldots, n$. Then
        \begin{equation*}
            \mathbb{E}\lb{\exp\lp{\sum_{i=1}^n K_\eta(a_i)}} = \mathbb{E}\lb{\exp\lp{\sum_{i=1}^n a_i X_i}}.
        \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.438953+00:00","domain":"probability theory","id":"claim_b77f86a9d3fb119c35ec53c78b20476a5b7fa2bdf427f8bc98a881c7dcfc8dee","kind":"definition","schema_version":1,"statement":"[Defn 14 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] We say that a continuous function $m:\mc{T}_{\A{1},\A{2}}\to (0,+\infty)$ is an order function on $\mc{T}_{\A{1},\A{2}}$ if there exist $C_0>0$ and $N_0\geq 0$ such that for all $\rho$, $\mu\in \mc{T}_{\A{1},\A{2}}$
    \begin{equation*}
        m(\rho)\leq C_0\jap{\rho-\mu}_{\mc{T}_{\A{1},\A{2}}}^{N_0}m(\mu)
    \end{equation*}
    with $\jap{\rho}_{\mc{T}_{\A{1},\A{2}}}=\pr{1+\bb{\rho}_{\mc{T}_{\A{1},\A{2}}}}^{1/2}$, where for $\rho=(x,\xi)\in \mc{T}_{\A{1},\A{2}}$,
    \begin{equation}
        \bb{\rho}_{\mc{T}_{\A{1},\A{2}}}:=\inf\limits_{{\gamma_1,\gamma_2\in \Z^d}}\pr{\bb{x-\Ab{1}\gamma_1}^2+\bb{\xi-\Ab{2}\gamma_2}^2}^{\frac{1}{2}}.

    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.680775+00:00","domain":"probability theory","id":"claim_b780ab9535b819b00ad30e6607b7775cc77ae7a13e3ac0e6173fa5362528eb2f","kind":"lemma","schema_version":1,"statement":"[Lemma l:BL-limits-moments of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Let  $\tilde{\mathcal{P}}$  be a marked point process on $\mathbb{R}^d\times\mathbb{K}$ with non-null, finite intensity $\rho$.  Let $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat\mathcal{N}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ be an real-valued score function which is \textnormal{BL}-localizing on all finite windows  for Palm distributions of some order $q\in \mathbb{N}$ (that is~(equation Lp-stab of the paper) holds  with  $p$ replaced by  $q$,  with  uniformly bounded correlation function $\rho^{(q)}$).
\begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item  
If $\xi$ satisfies the $(p + \epsilon)$-moment condition on finite windows~(equation e:xinpmomcopied of the paper) for some $p\geq q$ and some $\epsilon > 0$, then the random variables $\Upsilon_{\bk{x}{1}{q}}[i],1  \leq i \leq q$ have uniformly bounded $p$-moments, namely 

\begin{equation}
\sup_{x_1,\ldots,
  x_{q} \in \mathbb{R}^d}\max_{i=1,\ldots,q} \mathbb {E} [\max(1,|\Upsilon_{ \bk x1q}[i]|^p)]\le M^\xi_p.
  \end{equation}

\item 
Furthermore, under the assumptions of part ~(i.BL-limit-p-moment of the paper) above, we also obtain the speed of convergence of (natural) moments $p\in\mathbb{N}$; namely for $x_1,\ldots,x_q \in W_n$ we have

\begin{equation}
\max_{i=1,\ldots,q} 
      \Big | \mathbb {E} _{\bk x1{q}}[ (\xi(\tilde{x}_i,\tilde{\mathcal{P}}_n))^p]-\mathbb {E} [(\Upsilon_{\bk x1q}[i])^p]\Bigr| \le  (2M_{p+\epsilon/2}^\xi+6p)\varphi_{q} (d(\bk x1q,\partial W_n))^{\epsilon/(2p+\epsilon)},
  \end{equation}

  where $d(\bk x1q,\partial W_n)$ is the distance  between $x_1,\ldots,x_q \in W_n$ and the boundary of $W_n$.
  \item 
  If $\xi$ is \textnormal{BL}-localizing on all finite windows    of Palm order $q=2$ as in~(equation Lp-stab of the paper) and  satisfies the $(2+\epsilon)$-moment condition on finite windows~(equation e:xinpmomcopied of the paper) for some $\epsilon > 0$, then the  vector $\Upsilon_{\bk{x}{1}{2}}$ has uniformly bounded correlations, i.e.,  
\begin{equation}
\sup_{x_1,x_2 \in \mathbb{R}^d} 
 \mathbb {E} [\max(1,|\Upsilon_{\bk x12}[1]\Upsilon_{\bk x12}[2]|)] 
  \le M^\xi_2.
  \end{equation}
\item 
Furthermore, under the assumptions of part ~(i.BL-correlation-bound of the paper), the correlations have the speed of convergence:
\begin{equation}
  \Big | \mathbb {E} _{\bk x1{2}}[\xi(\tilde{x}_1,\tilde{\mathcal{P}}_n)\xi(\tilde{x}_2,\tilde{\mathcal{P}}_n)]-\mathbb {E} \bigl[\Upsilon_{\bk x12}[1]\Upsilon_{\bk x12}[2]\bigr]\Bigr| \le  (4M^\xi_{2+\epsilon/2} + 12)\varphi_{2}(d(\bk x12,\partial W_n))^{\epsilon/(4+\epsilon)}\,,
  \end{equation}
  where $ d(\bk x12,\partial W_n)$ is the distance between $\{x_1, x_2\}\subset W_n$ and the boundary of $W_n$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:11:02.381437+00:00","domain":"probability theory","id":"claim_b7818fa33cd633f1a0e96f42b5b4669b991b265ab8c8038f5cff2084634abc73","kind":"lemma","schema_version":1,"statement":"[Lemma lem:global_step_concentration of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] For $\alpha \in (0,\frac{1}{2})$ there is some $c > 0$ such that
