\end{equation}
In particular, if $\varepsilon_{m''}\to 0$ then $\textup{($iii$)}\xrightarrow{p}0$, and if $\varepsilon_{m''}\asymp (m'')^{-1/2}$ then $|\textup{($iii$)}|=O_p((m'')^{-1/2})$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.356574+00:00","domain":"probability theory","id":"claim_b865bf310e86eed77d482e740764d6cfcdde7d8c3e8f55d4574697267ab630d7","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2506.18558, '2506.18558'] {\rm(\textbf {Strong averaging principle})}
Suppose that Assumptions {\rm\ref{A1}}, {\rm\ref{A2}}, {\rm\ref{A3}} and {\rm\ref{A4}} hold. Then, for any initial value $(x,y)\in\RR^{n}\times\RR^{m}$ and $T>0$,
\begin{align}
\lim_{\varepsilon\rightarrow 0}\sup_{t\in[0,T]}\mathbb{E}|X_{t}^{\varepsilon}-\bar{X}_{t}|^2=0,
\end{align}
where $(\bar{X}_t)_{t\ge0}$ is the unique strong solution to the following averaged SDE \begin{equation}
d\bar{X}_{t}=\bar{b}(\bar{X}_t)\,dt+\bar\sigma(\bar{X}_t)\,d W^1_t,\quad\bar{X}_{0}=x.
\end{equation}
Here, $\bar{b}(x)=\displaystyle\int_{\RR^{m}}\hat b(x,y)\,\mu^x(dy)$, and $\mu^x$ is the unique invariant measure of the  SDE \eqref{e:IN}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:09.037454+00:00","domain":"probability theory","id":"claim_b8663f2fae71f973cb85b6dd3fb78a875bd671ce7318816eb2dd410b408d4b45","kind":"concept","schema_version":1,"statement":"[Corollary cor:mixing of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Assume the setting of Theorem~(thm:dichotomy of the paper).
\begin{enumerate}
\item[\rm(i)] In case \emph{(Q)}, choose $\lambda\in[1,\kappa]$ for which (equation eq:quadrootrateintro of the paper) holds, and let $\pi_\lambda$ be the unique invariant law of $Q_{h,\gamma}^{U_\lambda}$. Then there are initial states $z,\widetilde z\in\mathbb R^4$ and a constant $c>0$ such that, for every $\varepsilon\in(0,c/4]$, there exists $z_\varepsilon\in\{z,\widetilde z\}$ satisfying
\begin{equation*}
 t_{\mathrm{mix}}(z_\varepsilon,\varepsilon;Q_{h,\gamma}^{U_\lambda},\pi_\lambda)
 \ \ge\ \frac{\kappa}{3C_\star}\,\log\frac{c}{4\varepsilon}-1.
\end{equation*}
\item[\rm(ii)] In case \emph{(C)}, for every $R\ge1$ and every $\varepsilon\in(0,3/8)$,
\begin{equation*}
 t_{\mathrm{mix}}\bigl(z_R,\varepsilon;Q_{h,\gamma}^{U_R},\pi_R\bigr)
 \ >\ \left\lfloor\tfrac1{16}e^{c_0R^2}\right\rfloor,
 \qquad
 W_2(\delta_{z_R},\pi_R)\le C_0(1+R).
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.486247+00:00","domain":"probability theory","id":"claim_b86799cb99cf6fc64edf78d328697fd9b6473a1bffd0f5d18522b97c699daa9b","kind":"concept","schema_version":1,"statement":"[Prop 77 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $n\geq 1$ and $m\geq 1$.
A.s., the Wick power $:\Phi^{n}:$ can be decomposed
\begin{multline*}
:\Phi^{n}:~= \psi^{\rm gen}_{n,0}
+
\sum_{l=1}^{m}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{l-1}}^{k}
\,
\psi^{\rm gen}_{n-2k,l}
\\
+
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m}}^{k}
\,
:\Phi_{D\setminus A^{\rm gen, +}_{m}}^{n-2k}:
\, .
\end{multline*}
Moreover, for $\eta>0$,
one has the following $L^2$ decomposition of Sobolev norms:
\begin{eqnarray*}
\E\Big[
\Vert
:\Phi^{n}:
\Vert^{2}_{H^{-\eta}(\C)}
\Big]
&=&
\E\Big[
\Vert
\psi^{\rm gen}_{n,0}
\Vert^{2}_{H^{-\eta}(\C)}
\Big]
\\&&+
\sum_{l=1}^{m}
\E\Big[
\Big\Vert
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{l-1}}^{k}
\,
\psi^{\rm gen}_{n-2k,l}
\Big\Vert^{2}_{H^{-\eta}(\C)}
\Big]
\\
&&+
\E\Big[
\Big\Vert
