{"assumptions":[],"created_at":"2026-10-26T19:25:40.048192+00:00","domain":"probability theory","id":"claim_b944482dfcc6973fc31c08aef07cc0dda5e32d5ee70cf678962d638cf1a55379","kind":"theorem","schema_version":1,"statement":"[Cor 6 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Let $Z$ be a one-dimensional symmetric $\alpha$-stable process with $\alpha \in (1,2)$. Consider two processes, $X$ and $\tilde{X}$, satisfying the SDEs
\begin{align*}
X_t = x_0 + \int_0^t b(X_s) \rd s + \int_0^t \sigma(X_{s-}) \rd Z_s \quad \text{and} \quad \tilde{X}_t = \tilde{x}_0 + \int_0^t \tilde{b}(\tilde{X}_s) \rd s +  \int_0^t \tilde{\sigma}(\tilde{X}_{s-}) \rd Z_s,
\end{align*}
for $t\in[0,T]$ with initial values $x_0, \tilde{x}_0\in\real$.

Suppose the coefficients satisfy the following conditions for some constants $K, k, K'>0$, and $\tilde{\eta} \in [1/\alpha,1]$:
\begin{itemize}
    \item[(i)'] The drift coefficient $b$ is continuous bounded and $\tilde{b}$ is Lipschitz continuous:
    \begin{align*}
       |b(x)|\le K, \quad |\tilde{b}(x)-\tilde{b}(y)|\le K |x-y|. 
    \end{align*}
    \item[(ii)'] The jump coefficients $\sigma$ and $\tilde{\sigma}$ are bounded and H\"older continuous, and $\sigma$ is strictly positive:
    \begin{align*}
       k \le \sigma(x)\le K, \quad |\sigma^\alpha(x)-\sigma^\alpha(y)|\le K|x-y|^\eta,\\
       |\tilde{\sigma}(x)|\le K', \quad |\tilde{\sigma}(x)-\tilde{\sigma}(y)|\le K|x-y|^{\tilde{\eta}}.
    \end{align*}
    \item[(iii)'] The distances between the coefficients are small in the weighted norms defined in \eqref{weighted_norm}:
    \begin{align*}
       B \coloneqq \|b-\tilde{b}\|_{L^1\left(\mu_{x_0,\sigma}^{\alpha,T}\right)} < 1, \quad S \coloneqq \|\sigma-\tilde{\sigma}\|_{L^\alpha\left(\mu_{x_0,\sigma}^{\alpha,T}\right)} < 1. 
    \end{align*}
\end{itemize}
Then, there exists a positive constant $C = C(T, \alpha, K, k)$ such that\\
\noindent (1) Convergence in Expectation:
\begin{align*}
\sup_{t \in [0,T]} \e\left[|X_t-\tilde{X}_t|^{\alpha-1}\right] \le 
 \begin{cases}
    C\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\}& \textrm{if~~}\tilde{\eta} \in(1/\alpha,1]\\
	C\left[\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \left\{\log\left(\frac{1}{\max\left\{B, S\right\}}\right)\right\}^{-1}\right] & \textrm{if~~}\tilde{\eta} =1/\alpha,
  \end{cases}
\end{align*}
\noindent (2) Convergence in Probability: For any $h>0$,
\begin{align*}
\p\left(\sup_{t \in [0,T]}|X_t-\tilde{X}_t|^{\alpha-1}>h\right) \le
 \begin{cases}
    \frac{C}{h}\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\}& \text{if~~}\tilde{\eta} \in(1/\alpha,1]\\
	\frac{C}{h}\left[\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \left\{\log\left(\frac{1}{\max\left\{B, S\right\}}\right)\right\}^{-1}\right] & \textrm{if~~}\tilde{\eta} =1/\alpha.
 \end{cases}
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.128087+00:00","domain":"probability theory","id":"claim_b94e72acdd919a2e3b3d9ed1fd9601d88a0d2e75d5bd2a29a496b1573b3f098d","kind":"concept","schema_version":1,"statement":"[Prop B-prop of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] For each $n,L\in\mathbb{N}$ with $L\geq n$, the B($n$,$L$) enjoys the following properties:
    \begin{enumerate}[label=(\roman*)]

    \item \textit{Partition of the unity}: for any integer $ 0<L<N/2 $ it holds that
    \begin{align}
    \mathcal{L}_N^{\text{SSEP}}
    =\sum_{n=0}^L\mathcal{L}_N^{n,L};
    \end{align}

    \item \textit{Symmetry}: for any $\eta\in \Omega_N$ it holds that $\mathbf{b}_{n,L}(\eta)=\mathbf{b}_{L-n,L}(\overline{\eta})$, with $\eta\mapsto\overline{\eta}$ the map that exchanges the particles by vacant sites and vice-versa;

    \item \textit{Interpolation}: for each $n\in\mathbb{N}_+$ it holds that \textnormal{B($n$,$n$)$=$PMM($n$)};

    \item \textit{Range}: For each $\eta\in\Omega_N$ it holds that $\mathbf{b}_{n,L}(\eta)\in [0,1]$. 

    \item \textit{Blocked configurations}: there is $\eta\in\Omega_N$ such that $\mathbf{b}_{n,\ell}(\tau^x\eta)=0$ for any $x\in\mathbb{T}$;

    \item \textit{Mobile Clusters}: any box of length $L+2$ with exactly $n+1$ particles constitutes a mobile cluster. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.365347+00:00","domain":"probability theory","id":"claim_b94fe594e3f41c59a9db48d9f15fdcc1a0d99f4ab2a432973502e4ddc89087fe","kind":"definition","schema_version":1,"statement":"[Defn $\partial$-ribbons of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] A \textbf{system of $\bm \partial$-ribbons} adapted to $Z$ is a finite collection of pairwise disjoint smoothly embedded strips $R_m = \sigma_m \times [-1, 1] \subset M_{\mathord{\scalebox{0.45}{$\square$}}}$ such that
    \begin{itemize}
        \item The arcs $\sigma_m \times \{\pm1\}$ are tangent to the foliation $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$, and each ribbon is transverse to $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ and tangent to $Z$,

        \item For the initial point $p_m$ of $\sigma_m$, the interval $p_j \times [-1,1]$ lies on $\partial_* M_{\mathord{\scalebox{0.45}{$\square$}}}$ away from $N_\partial^\mathrm{win}$, and for the end point $q_m$, the interval $q_m \times [-1,1]$ lies either in the interior of a vertical side of an annular fence, or in the interior of a window. Moreover, $R_m$ intersects $\partial M_{\mathord{\scalebox{0.45}{$\square$}}}$ along these intervals only, and transversally. 

        We further require that the ribbons are tangent to $\partial_y$ inside of $N_{\mathord{\scalebox{0.45}{$\square$}}}$.
    \end{itemize}

    This system is \textbf{$\bm \partial$-full} if for each point $p \in \partial_* M_{\mathord{\scalebox{0.45}{$\square$}}}$, the leaf of $\partial \mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ passing through $p$ intersects interiors of initial intervals of $\partial$-ribbons, or interiors of windows, on both sides of $p$.","status":"unverified"}

