{"assumptions":[],"created_at":"2026-10-26T21:02:38.603806+00:00","domain":"probability theory","id":"claim_bc748272dbf3976a4c58bac3d382342fc6a6ea817bf665cb815a4f723ddfbd30","kind":"concept","schema_version":1,"statement":"[Proposition 3 of arXiv:2607.07552, 'Weak convergence rate for the Cox--Ingersoll--Ross process'] Let $f\in\mathcal{C}^{(q)}((0,\infty),\mathbb{R})$ and $m\geq q$, $m\in\mathbb{N}$, be such that there exists $K>0$ with
	\begin{equation}
		|f^{(q)}(x)|\leq K(1+x^m)\quad\forall x\geq 0.
	\end{equation}
	Then the function $v:\mathbb{R}_{+}\times[0,T]\to\mathbb{R}$ defined by $v(x,t):=\mathbb{E}^x[f(X_{T-t})]$ satisfies the PDE
	\begin{equation}
		\partial_t v+b(x)\partial_x v+{\sigma(x)^2\over 2}\partial_{xx}v=0,\quad v(T,x)=f(x).
	\end{equation}
	Moreover, the derivatives of $v$ are uniformly bounded, and there exists $K>0$ such that
	\begin{equation}
		\left|\partial^{k}_x\partial^{r}_t v(x,t)\right|\leq K(1+x^{m+q+r})\quad\forall(x,t)\in\mathbb{R}_{+}\times[0,T],\quad k+2r\leq q.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:36:16.067500+00:00","domain":"probability theory","id":"claim_bc77565fc67f8e052d8022a56b0035a5e6204e6393ac99a68a64b9351dbf7c4d","kind":"concept","schema_version":1,"statement":"[Proposition prop:global_well_cutoff of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Let $4< p<+\infty$ and $-\frac{1}{2}<r<-\frac{2}{p}$. For all $\omega_0\in B^{-2/p}_{g,2,p},$ there exists a unique local p-solution $(\omega,\tau)$ of (equation main_ito_cutoff of the paper) satisfying $\tau=+\infty$ $\mathbb{P}-a.s.$ and
 \begin{align*}
     \omega&\in H^{\theta,p}_{loc}\left([0,+\infty);H_g^{-2\theta}\right)\cap  C\big([0,+\infty);B^{-\frac{2}{p}}_{g,2,p}\big)\quad \mathbb{P}-a.s.\quad  \text{for all } \theta\in [0,1/2).
 \end{align*}
 Moreover, for all $T>0$, there exists $C=C(T)$ such that
    \begin{align}
