\]
such that $v_{\varepsilon,f}$ is fiber-orthogonal and
\begin{equation}
N_{\varepsilon,\tau_*}(U_{\varepsilon,f}+v_{\varepsilon,f})
=
Z_{\varepsilon,f}\ell_{\varepsilon,f}
\end{equation}
in the weak sense. Moreover,
\begin{equation}
\|v_{\varepsilon,f}\|_{H^1_\varepsilon(\mathbb R^4)}
\le
C\|E^\perp_{\varepsilon,f}\|_{(H^1_\varepsilon(\mathbb R^4))^*}.
