{"assumptions":[],"created_at":"2026-10-27T10:02:28.582571+00:00","domain":"probability theory","id":"claim_bf6b899d5fd1760f0a7040ba6963a8abe0976f5e7c04eb50b49acc5941d23b90","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2609.01333, '2609.01333'] For each $\kappa>0$, there exists $\gamma_*=\gamma_*(\kappa)\in  \Big(0, \, \frac{1}{2\pi} \tfrac{1}{\frac{1}{\kappa} - \frac{1}{\sqrt{\kappa^2+1}}}\Big)$ such that for every $\alpha \in (0,1)$ and $\gamma\in (0,\gamma_*)$, there exists   $\lambda_{*}=\lambda_*(\kappa, \gamma)>0$ and a smooth curve
\begin{align*}
 I: (-\varepsilon_0,\varepsilon_0) &\longrightarrow  (0,\infty) \times C^{2,\alpha}(\R),\quad  s\longmapsto (\lambda_s,u_s)
 \end{align*}
satisfying   $I(0)= (\lambda_0,u_0) \equiv( \lambda_{*},0)$. Moreover,  the  following properties hold.
\begin{enumerate}[$(a)$]
\item For each $s \in (-\varepsilon_0, \varepsilon_0)$,  $u_s\in C^{2,\alpha}(\R)$ is even, $2\pi$-periodic, and takes the form
\begin{align*}
u_s(t) = s\big(\cos(t) + \omega_s(t)\big),
\end{align*}
where $\omega: (-\varepsilon_0, \varepsilon_0) \to C^{2,\alpha}(\mathbb{R})$, $s \mapsto \omega_s$ is a smooth curve satisfying $\omega_0 \equiv 0$, $\omega_s\in C^{2,\alpha}(\R)$ is even, $\omega_s$ is $2\pi$-periodic and satisfies
\begin{align*}
\int_{0}^{2\pi} \omega_s(t) \cos(t) \mathrm{d}t = 0.
\end{align*}
\item Each function $\varphi_s = \lambda_s + u_s$ satisfies  $\varphi_s\in C^{2,\alpha}(\R)$,  $\varphi_s\geq \frac{\lambda_*}{2}$, $\varphi_0=\lambda_*$ and
\begin{align}

H_{\partial\Omega_{\varphi_s}}(x) + \gamma \int_{\Omega_{\varphi_s}} G_\kappa(|x-y|)  \mathrm{d}y = C_{\lambda_s,\kappa} \qquad \text{for all } x \in \partial\Omega_{\varphi_s}
\end{align}
where the constant $C_{\lambda_s,\kappa}$ satisfies $C_{\lambda_s,\kappa}\leq C_{\lambda_*,\kappa}$ with

\begin{align*}
C_{\lambda_s,\kappa} &=H_{\partial\Omega_{\lambda_s}}\hspace{-0.7ex}
(0,\lambda_s e_1)+\gamma \int_{\Omega_{\lambda_s}}\hspace{-2ex} G_\kappa(|(0,\lambda_s e_1)-z|) \mathrm{d}z=\frac{1}{\lambda_s}
+ 2\gamma\lambda_s^2 \int_{B_1} \hspace{-2ex}K_0(\lambda_s \kappa|e_1-y|)\mathrm{d}y,
\end{align*}
\end{enumerate}
where $e_1=(1,0)\in \R^2$ and  $K_\nu$ is the modified Bessel function of the second kind of order $\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.636653+00:00","domain":"probability theory","id":"claim_bf75f3d28f0ef138b73b36224b15777c07abee7ba19c4a486c6ea1268c170dd8","kind":"concept","schema_version":1,"statement":"[Lemma 28 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $\eps > 0$. Then, there exists $C = C(\eps,P,\G)$ such that 
