{"assumptions":[],"created_at":"2026-10-27T15:07:17.278445+00:00","domain":"probability theory","id":"claim_bf943c26fcd11dea6bca7473d990d3a337588f9b901b99146539ed24dc329415","kind":"concept","schema_version":1,"statement":"[Theorem eq:resslim of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] First, we assume that
\begin{itemize}
\item[$\mathbf{(H0)}$] $\forall x>0, \quad g(x,0) < 0 < g(x,R_{\max})$,
\item [$\mathbf{(H1)}$] $\forall x >0, \displaystyle{\int_{0}^{x} \dfrac{d(t)}{g(t,0)} \mathrm{d}t} = - \infty$.
\end{itemize}
Then, we assume that there exists a weight function $\omega$ such that
\begin{itemize}
\item[$\mathbf{(H2)}$]
$\omega \in \mathcal{C}^{1}(\mathbb{R}^{*}_{+})$ is positive, non-decreasing, Lipschitz continuous on $(1,+\infty)$, and
\begin{itemize}
\item[$\mathbf{(a)}$] $\exists c_{g}>0, \forall x>0, \quad  \sup_{R \in [0,R_{\max}]} |g(x,R)| \leq c_{g}\omega(x)$,
\item[$\mathbf{(b)}$] $\exists c_{b}>0, \forall x>1, \quad b(x) \leq c_{b}\omega(x)$,
\item[$\mathbf{(c)}$] $\exists c_{d}>0, \forall x>0, \quad d(x) \omega(x) \leq c_{d}$.
\end{itemize} 
\end{itemize}
Finally, we assume that the sequence $\left(\left(\mu^{K}_{t},R^{K}_{t}\right)_{t \geq 0}\right)_{K \in \mathbb{N}^{*}}$ of renormalized processes (formally defined in Section (subsec:construcdeux of the paper)) is such that
\begin{itemize}
    \item[$\mathbf{(H3)}$] there exists a random variable $\mu_{0}^{*} \in \mathcal{M}_{\omega}(\mathbb{R}^{*}_{+})$ such that $(\mu_{0}^{K})_{K \in \mathbb{N}^{*}}$ converges in law towards $\mu_{0}^{*}$ in $(\mathcal{M}_{\omega}(\mathbb{R}^{*}_{+}),\mathrm{w})$,
    \item[$\mathbf{(H4)}$] there exists $p>1$ such that 
    \begin{align*}
    \underset{K \in \mathbb{N}^{*}}{\mathrm{sup}} \hspace{0.1 cm} \mathbb{E}\left(\left\langle \mu^{K}_{0}, 1 + \mathrm{Id} + \omega \right\rangle^{p}\right) < + \infty.
    \end{align*}
\end{itemize} 
Under $\mathbf{(H0)}$, $\mathbf{(H1)}$, $\mathbf{(H2)}$, $\mathbf{(H3)}$, $\mathbf{(H4)}$, for all $T \geq 0$, the sequence $\bigg(\left(\mu^{K}_{t},R^{K}_{t}\right)_{t \in [0,T]}\bigg)_{K \in \mathbb{N}^{*}}$ is tight in the Skorokhod space $\mathbb{D}([0,T], (\mathcal{M}_{\omega}(\mathbb{R}^{*}_{+}),\mathrm{w}) \times [0,R_{\max}])$. Any of its accumulation point $(\mu^{*}_{t},R^{*}_{t})_{t \in [0,T]}$ is a continuous process and verifies almost surely, for all $t \in [0,T]$,
\begin{align}
    R^{*}_{t} =  R^{*}_{0} + \displaystyle{\int_{0}^{t}\rho(R^{*}_{s},\mu^{*}_{s})\mathrm{d}s},

\end{align}
     and for every $\varphi :(t,x) \mapsto \varphi(t,x) =: \varphi_{t}(x)$ smooth enough and dominated by $\omega$,
     \begin{multline}
       \langle \mu^{*}_{t}, \varphi_{t} \rangle =  \langle \mu^{*}_{0}, \varphi_{0} \rangle + \displaystyle{\int_{0}^{t} \int_{\mathbb{R}^{*}_{+}} \bigg( \partial_{1}\varphi(s,x) + g(x,R^{*}_{s})\partial_{2}\varphi(s,x) }   \\
     + b(x)(\varphi_{s}(x_{0}) + \varphi_{s}(x-x_{0}) - \varphi_{s}(x)) - d(x)\varphi_{s}(x) \bigg) \mu^{*}_{s}(\mathrm{d}x) \mathrm{d}s,

     \end{multline}
     where $\partial_{1}$, respectively $\partial_{2}$, are the partial derivatives with respect to the first, respectively second, variable. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

