{"assumptions":[],"created_at":"2026-10-28T00:37:20.358465+00:00","domain":"probability theory","id":"claim_c1a762f19c448471bdbe951c91304233bc4fb335df2dc42961307189d44518b9","kind":"theorem","schema_version":1,"statement":"[Theorem non i.i.d of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $(\sigma_n)_{n\ge 1}$ be positive numbers. Let $(g_n)_{n\ge 1}$ be simple graphs where $V(g_n)=[n]$ and consider the weighted graph $(g_n,\sigma^2)$, where $\sigma^2(i)=\sigma_i^2$. Assume that $(g_n,\sigma^2)_n$ converges to a graphon $w$, and that
    \begin{align*}
        &\vert \sigma^2\vert =\sum_{k\in [n]}\sigma_i^2 \to \infty; \quad \frac{\sigma_{\max}^2}{\vert \sigma^2\vert}\to 0.
    \end{align*}
    Let $a_1^{(n)},\ldots,a_n^{(n)} \in \mathcal{A}$ be $g_n$-independent centered random variables with variance $\operatorname{var}(a_k^{(n)})=\sigma_k^2$, for every $n \ge 1$. 
    Assume that there exist constants $C_p\ge 1$ that depends only on $p\ge 1$ such that for any $n,k,p\ge 1$, we have 
    \begin{align*}
       \tau\left(|a_k^{(n)}|^p\right)\le C_p\sigma_k^p.
    \end{align*}
    Then
    \begin{align*}
        S_n=\frac{1}{\sqrt{\vert\sigma^2\vert}}\sum_{k \in [n]} a_k^{(n)}
    \end{align*}
    converges in distribution to $\mu_w$, the law defined in (equation eq: definition of mu_w of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:00.610406+00:00","domain":"probability theory","id":"claim_c1a7a53b3660eb8cf4403cd4f8d7113039277ab38bb3718c4d4a71a30f9e43b8","kind":"concept","schema_version":1,"statement":"[Proposition 2 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] Assume that $\mu,\nu \in\mathcal{P}_2(\Rd)$ share  the barycentre. Then,
	\begin{align*}
		\Pi_{\succeq_c \mu} (\nu)   = 	\Pi_{\succeq_c \nu} (\mu)  =   \argmin_{ \rho \succeq_c \mu, \  \rho \succeq_c \nu} m_2(\rho).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:23.370657+00:00","domain":"probability theory","id":"claim_c1ab0a9a6308537f8e04e3726f747444f3b84315bc4ee8a85d29a1609cbd0dec","kind":"concept","schema_version":1,"statement":"[Proposition 2 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Let $\Omega$ be a bounded, open set with $C^{1,1}$ boundary and $X=(X_t)_{t\ge 0}$ be a translation invariant isotropic process such that 
		\begin{align*}
			\E_0\left[\left(\overline{X}^{(1)}_T\right)^p\right]<\infty
		\end{align*}
		for some $T>0$ and $p>1$, and 
		\begin{align*}
			\lim_{t\downarrow 0}\frac{\E_0\left[\left(\overline{X}^{(1)}_t\right)^p\right]}{\E_0\left[\overline{X}^{(1)}_t\right]}=0.
		\end{align*}
		Then, 
		\begin{align*}
				\lim_{t\downarrow 0}\frac{\Vol(\Omega)-Q^X_\Omega(t)}{\E_0\left[\overline{X}^{(1)}_t\right]}=\Per(\Omega).
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:45:17.709417+00:00","domain":"probability theory","id":"claim_c1b165d9c11640c53e87f3689b8c85d05a9078f2ead2618887f5e7c2f7587e66","kind":"concept","schema_version":1,"statement":"[Proposition prop occup time invar of arXiv:2604.10509, 'Nonequilibrium fluctuations and moderate deviations for the occupation time of the SSEP wi'] Let $\{\mathcal{Y}_t, 0 \leq t \leq T\}$ be the process introduced in Proposition (prop density fluc of the paper). The following statements hold.
