{"assumptions":[],"created_at":"2026-10-27T06:25:55.319102+00:00","domain":"probability theory","id":"claim_c530b807b3c600547777389a6a6a98dc217fc91fb98cb563199462114aa7cbf7","kind":"lemma","schema_version":1,"statement":"[Lemma 28 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $r>0$ and an even number $n=2N$. 
For $\bs{\alpha}, \bs{\beta}\in\LX_n$, we write $\bs{x}=\ee^{\ii\bs{\alpha}}$ and $\bs{y}=\ee^{\ii\bs{\beta}-r}$.  
We denote by $\Pcro{1}$ the law of annulus $\SLE_4(\LZcro{1})$ in $(\A_r; x_1, y_1)$. 
Suppose $\gamma^1$ is the annulus Loewner chain whose law is the same as tilting $\Pcro{1}$ by the local martingale
\begin{align}
M_t(\LZcro{1}; \LZann{n})=\ee^{\frac{n-1}{4}t}
	\prod_{j=2}^{n}
	\left(\mathfrak{\covmap}_t'(\alpha_j)
	\mathfrak{\covmap}_t'(\beta_j+\ii r)\right)^{\frac14}
	\frac{\LZann{n}\left(r-t;\zeta_t,\mathfrak{\covmap}_t(\alpha_2),
		\ldots,\mathfrak{\covmap}_t(\alpha_n),
		\Re\mathfrak{\covmap}_t(\bs{\beta}+\ii r)\right)}
	{\LZcro{1}\left(r-t;\zeta_t,
		\Re\mathfrak{\covmap}_t(\beta_1+\ii r)\right)},
\end{align}
where $t<T$ and $T$ is the life-time of $\gamma^1$, i.e. the minimum between $r$ and swallowing time of points $\{x_2, x_n\}$.
\begin{itemize}
\item The driving function $\zeta:[0,r)\to \R$ for $\gamma^1$ satisfies the SDE system
\begin{equation}
	\begin{cases}
		\displaystyle \ud \zeta_t = 2 \ud B_t + 4 \partial_{\alpha_1} \log \LZann{n}(r-t; \zeta_t, U_t^2,\ldots, U_t^n,V_t^1,\ldots, V_t^n) \ud t, \qquad \zeta_0=\alpha_1, \\
		\displaystyle \ud U_t^j = H_1(r-t; U_t^j-\zeta_t)\ud t, \qquad U_0^j=\alpha_j,\quad 2\le j\le n,\\
		\displaystyle \ud V_t^j = H_3(r-t; V_t^j-\zeta_t)\ud t, \qquad V_0^j=\beta_j,\quad 1\le j\le n,
	\end{cases}
\end{equation}
where $\{B_t\}_{t\ge 0}$ is a standard Brownian motion.
\item The Dirichlet GFF $\Gamma$ in annulus $\A_r$ can be coupled with $\gamma^1$ so that $\gamma^1$ is a  level line of $\Gamma+\varphiann{n}$ starting from $x_1$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:22:08.409767+00:00","domain":"probability theory","id":"claim_c53997cede5e155ec8f7678a71936c56a33476339c738a312e0bc5edfcc27665","kind":"concept","schema_version":1,"statement":"[Thm replacement of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] Let $(A_n)_{n\ge1}$, $(B_n)_{n\ge1}$, $(X_n)_{n\ge1}$, and $(Y_n)_{n\ge1}$ be sequences of $n \times n$ real symmetric matrices, where $A_n$ is a deterministic sparsity profile, $B_n$ is deterministic, and $X_n$ and $Y_n$ are both inhomogeneous Wigner matrices.  
    Let $(K_n)_{n\ge1}$ be a sequence of positive real numbers. 
    Assume:
    \begin{enumerate}
        \item (Moment matching) For each $n \geq 1$, $X_n$ and $Y_n$ match moments per Definition (def:moments of the paper).
        \item (Sparsity profile) We have
        \begin{equation} 
            \limsup_{n \to \infty} \frac{1}{n K_n} \sum_{1 \leq i < j \leq n} (A_n)_{ij} \left( \mathbb{E} |(X_n)_{ij}|^2 + \mathbb{E}  |(Y_n)_{ij}|^2 \right) < \infty.
        \end{equation}
        \item (Lindeberg's condition) For every $\varepsilon > 0$
        \begin{equation} 
            \lim_{n \to \infty} \left[ \frac{1}{nK_n} \sum_{1 \leq i \leq j \leq n} (A_n)_{ij} \left( \mathbb{E} \left[ (X_n)_{ij}^2 \chi_{\{|(X_n)_{ij}| > \varepsilon \sqrt{K_n}\} } \right] + \mathbb{E} \left[ (Y_n)_{ij}^2 \chi_{\{|(Y_n)_{ij}| > \varepsilon \sqrt{K_n}\} } \right] \right) \right] = 0,
        \end{equation}
        where $\chi_E$ denotes the indicator function of the event $E$. 
    \end{enumerate}
    Then 
    \[ \mu_{\frac{1}{\sqrt{K_n}} A_n \odot X_n + B_n} - \mu_{\frac{1}{\sqrt{K_n}} A_n \odot Y_n + B_n} \;\xrightarrow[n\to\infty]{}\; 0 \qquad\mbox{ weakly in probability}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.925390+00:00","domain":"probability theory","id":"claim_c53a9f2c8993a082f4ab1fce3c01ffdd9e469594ad364e1c4cddd61ac5ec1b1a","kind":"theorem","schema_version":1,"statement":"[Corollary coro_subharmonic of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, $N\ge 1$, $x\in \mathbb{Z}^d\setminus B(3N)$ and $D\subset \widetilde{\mathbb{Z}}^d$, 
