{"assumptions":[],"created_at":"2026-10-27T12:36:49.852104+00:00","domain":"probability theory","id":"claim_c5d91551adcfc4cdf8e83a1e0b99615f154e316799f9e8d8771ef828e8eafb48","kind":"lemma","schema_version":1,"statement":"[Lemma lem:dgt4-path-survival of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Let $T>0$, $\kappa>0$, and $n_R\coloneqq\lfloor R^2T\rfloor$, and suppose that for every
	$\varepsilon\in(0,1)$, as $R\to\infty$,
	\begin{equation}
		\max_{\lceil\varepsilon n_R\rceil\leq m\leq n_R}\left\{\left|\frac{m\mathbb{P}(J(0)>\mathbb{E} u_{m-1}(0))}{G(0,0)\kappa}-1\right|+m\mathbb{P}\bigl(\{u_m(0)=0\}\mathbin{\triangle}\{J(0)>\mathbb{E} u_{m-1}(0)\}\bigr)\right\}\longrightarrow0\, .
	\end{equation}
	Then
	\begin{equation}
		R^{-2}\sum_{j=0}^{n_R-1}\mathbf E_0\left|\mathbb{P}(S_{n_R,j}(X)=1\mid X)-\left(1-\frac{j}{R^2T}\right)^\kappa\right|\longrightarrow0\, .
	\end{equation}
