{"assumptions":[],"created_at":"2026-10-26T19:20:33.747797+00:00","domain":"probability theory","id":"claim_c7b90158b09d02078fb87fe91943b6ddc0eff5580877514279cb4c3fa6507c2c","kind":"concept","schema_version":1,"statement":"[Lem 9 (Pivot regeneration blocks) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Fix $\ell\ge2$ and let $a>0$ satisfy
Condition~\textup{B.\ref{ass:B1}}.  Let
$
    0<\rho_1<\rho_2<\rho_3<\cdots
$
be the ordinary pivot nodes, and let $\gk_n$ be as in
\eqref{eq:kappa-def}.  We use the interval edge set $\cE[x,y]$ and
the interval environment $\Env[x,y]$ defined in
\eqref{eq:interval-env-notation}, and the block notation
\eqref{eq:block-variable-notation}.  Then the following holds.

\begin{enumeratei}
\item \textbf{Pivot renewal-block localization.}
If $\rho_i<\rho_j$ are two ordinary pivot nodes, then there exists a minimum-hop geodesic from $\rho_i$ to $\rho_j$ using only edges in
$\cE[\rho_i,\rho_j]$.  Consequently,
$
    T(\rho_i,\rho_j)
    \text{ and }
    H(\rho_i,\rho_j)
$
are measurable with respect to $\Env[\rho_i,\rho_j]$.

\item \textbf{Renewal-block i.i.d.~structure.}
The block sequence
\begin{align}
    \left\{
        \left(
            \sfP_i,\,
            \Env[\rho_i,\rho_{i+1}]
        \right)
    \right\}_{i\ge1}
\end{align}
is i.i.d.~In particular,
$
    \{(\sfP_i,\sfT_i,\sfH_i)\}_{i\ge1}
$
is i.i.d.

\item \textbf{Geometric domination of the gaps.}
Ordinary pivots occur infinitely often almost surely, and if
$
    \fs_\ell:=2\ell-1,
$
then
\begin{align}
    \sfP_i
    \preceq
    \fs_\ell\,\mathrm{Geom}(p_{a,\ell}),
    \quad i\ge1.
\end{align}
In particular, $\sfP_1$ has finite moments of all orders.  Consequently,
\begin{align}
    \frac{\gk_n}{n}
    \to
    \frac{1}{\E\sfP_1}
    \quad\text{a.s.}
\end{align}
\end{enumeratei} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:36:12.194178+00:00","domain":"probability theory","id":"claim_c7cd5469a4cbd35622c3bb42bc41240f71bc6eccd53415ac702c86ebbff353d2","kind":"concept","schema_version":1,"statement":"[Proposition 18 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ Wigner matrix satisfying Assumption~\ref{ass:momass}. For any fixed $p, n,S\in \N$ with $p\ge 3$ it holds that
