{"assumptions":[],"created_at":"2026-10-28T00:55:42.109894+00:00","domain":"probability theory","id":"claim_cad798b024f07e82efc1cbcc5dcfdfe519f191fdc614a3bdc2f03e0a8d2e7233","kind":"concept","schema_version":1,"statement":"[Theorem thm2 of arXiv:2411.15881, 'Stable Approximation for Call Function Via Stein's method'] Keep the same assumptions and notation as in Theorem (thm1 of the paper). Then we have
\begin{align*}
\left|\mathbb{E}\left(S_n-M\right)_{+}-\mathbb{E}\left(S_\alpha (1,\delta)-M\right)_{+}\right|\leq c_{2,M}R_{n},
\end{align*}
where $R_{n}$ is defined by (Rn of the paper) and
\begin{align*}
c_{2,M}=&
\frac{4d_{\alpha}\mathbb{E}\left[\left|\xi_{1}-\mathbb{E}[\xi_{1}]\right|^{2-\alpha}\right]}{(2-\alpha)(\alpha-1)\sigma^{2-\alpha}}\frac{\eta_{3,\alpha,\delta}}{M^{\frac{2(\alpha-1)}{3\alpha-1}}}
+\frac{3\mathbb{E}\left[|\xi_{1}|\right]\left|\mathbb{E}[\xi_{1}]\right|}{\sigma^{2}}\frac{\eta_{3,\alpha,\delta}}{M^{\frac{2(\alpha-1)}{3\alpha-1}}}\\
&+\eta_{3,\alpha,\delta}
\begin{cases}
\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{2}}\left[\frac{2}{2-\alpha}+\frac{2L}{\alpha+\gamma-2}(2A)^{-\frac{\alpha+\gamma}{\alpha}}\right]M^{-\frac{2(\alpha-1)}{3\alpha-1}},&\gamma\in(2-\alpha,\infty),\\
\frac{1}{\sigma^{2}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{\alpha-1}\right)
+q_{1}\right]\frac{2(\alpha-1)\log M}{3\alpha-1}M^{-\frac{2(\alpha-1)}{3\alpha-1}},& \gamma=2-\alpha,\\
\sigma^{\frac{\alpha-\gamma}{\gamma-1}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{2-\alpha-\gamma}\right)
+q_{1}\right]M^{-\frac{2(\alpha-1)^{2}}{(3\alpha-1)(1-\gamma)}}, &\gamma\in(0,2-\alpha),\\
\max\left\{\frac{2\alpha(2A)^{\frac{2}{\alpha}}}{(2-\alpha)\sigma^{2}},\frac{4}{\sigma^{2}},
\frac{8}{(2-\alpha)\sigma^{\alpha}}+\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{\alpha}}+q_{1}\right\}M^{-\frac{2(\alpha-1)^{2}}{(3\alpha-1)}},
&\gamma=0,
\end{cases}
\end{align*}
with
\begin{align}
q_{1}=\frac{8\alpha^{2}(A+L)-4\alpha L}{(\alpha-1)\eta_{3,\alpha,\delta}}.
\end{align}

In particular, when $\delta=0$, the order of $M$ can be improved and the $c_{2,M}$ can be reduced to $c_{3,M}$, which is defined as follows:
\begin{align*}
c_{3,M}=&
\frac{4d_{\alpha}\mathbb{E}\left[\left|\xi_{1}-\mathbb{E}[\xi_{1}]\right|^{2-\alpha}\right]}{(2-\alpha)(\alpha-1)\sigma^{2-\alpha}}\frac{\eta_{4,\alpha}}{M^{\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}}}
+\frac{3\mathbb{E}\left[|\xi_{1}|\right]\left|\mathbb{E}[\xi_{1}]\right|}{\sigma^{2}}\frac{\eta_{4,\alpha}}{M^{\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}}}\\
&+\eta_{4,\alpha}
\begin{cases}
\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{2}}\left[\frac{2}{2-\alpha}+\frac{2L}{\alpha+\gamma-2}(2A)^{-\frac{\alpha+\gamma}{\alpha}}\right]M^{-\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}},&\gamma\in(2-\alpha,\infty),\\
\frac{1}{\sigma^{2}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{\alpha-1}\right)
+q_{2}\right]\frac{(\alpha^{2}-1)\log M}{\alpha^{2}+2\alpha-1}M^{-\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}},& \gamma=2-\alpha,\\
\sigma^{\frac{\alpha-\gamma}{\gamma-1}}\left[\left(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{2-\alpha-\gamma}\right)
+q_{2}\right]M^{-\frac{(\alpha^{2}-1)(\alpha-1)}{(\alpha^{2}+2\alpha-1)(1-\gamma)}}, &\gamma\in(0,2-\alpha),\\
\max\left\{\frac{2\alpha(2A)^{\frac{2}{\alpha}}}{(2-\alpha)\sigma^{2}},\frac{4}{\sigma^{2}},
\frac{8}{(2-\alpha)\sigma^{\alpha}}+\frac{2(2A)^{\frac{2}{\alpha}}}{\sigma^{\alpha}}+q_{2}\right\}M^{-\frac{(\alpha^{2}-1)(\alpha-1)}{\alpha^{2}+2\alpha-1}},
&\gamma=0,
\end{cases}
\end{align*}
with $q_{2}=\frac{8\alpha^{2}(A+L)-4\alpha L}{(\alpha-1)\eta_{4,\alpha}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.492329+00:00","domain":"probability theory","id":"claim_cad8f016adb2609652599af4ff0b32048d2d5c7b378a60110e79902c91a4f3a8","kind":"definition","schema_version":1,"statement":"[Definition 240 of arXiv:2601.16377, '2601.16377'] If $\boldsymbol{v} \in \amsmathbb{R}^H$ is non-zero, we set $\widetilde{\boldsymbol{v}} = (\boldsymbol{v} \otimes \boldsymbol{v},0)\in (\amsmathbb{R}^{H} \otimes \amsmathbb{R}^{H}) \oplus \amsmathbb{R}$ and construct the complex surface
\[
\Sigma^{[2]}_{\widetilde{\boldsymbol{v}}} = \left( \bigsqcup_{\widetilde{\boldsymbol{w}} \in \mathfrak{G}^{[2]}.\widetilde{\boldsymbol{v}}} (\widehat{\amsmathbb{H}}^{+} \sqcup \widehat{\amsmathbb{H}}^-) \times (\widehat{\amsmathbb{H}}^+ \sqcup \widehat{\amsmathbb{H}}^-) \right)\Big/\sim.
\]
The equivalence relation identifies for each $h \in [H]$, $\epsilon_1,\epsilon_2,\epsilon_1',\epsilon_2' \in \{\pm 1\}$ and $\widetilde{\boldsymbol{w}} \in \mathfrak{G}^{[2]}.\boldsymbol{v}$:
\begin{itemize}
\item $\prod_{i = 1}^2 (\widehat{\amsmathbb{R}}^{\epsilon_i} \setminus \amsmathbb{B}^{\epsilon_i})$ with $\prod_{i = 1}^{2} (\widehat{\amsmathbb{R}}^{\epsilon_i'} \setminus \amsmathbb{B}^{\epsilon_i'})$ both in the $\widetilde{\boldsymbol{w}}$-th copy;
\item $\overline{\amsmathbb{B}}_{h}^{+} \times \widehat{\amsmathbb{H}}^{\epsilon}$ in the $\widetilde{\boldsymbol{w}}$-th copy with $\overline{\amsmathbb{B}}_{h}^- \times \widehat{\amsmathbb{H}}^{\epsilon}$ in the $T_1^{(h)}(\widetilde{\boldsymbol{w}})$-th copy;
\item $\widehat{\amsmathbb{H}}^{\epsilon} \times \overline{\amsmathbb{B}}_h^+$ in the $\widetilde{\boldsymbol{w}}$-th copy with $\widehat{\amsmathbb{H}}^{\epsilon} \times \overline{\amsmathbb{B}}_h^-$ in the $T_2^{(h)}(\widetilde{\boldsymbol{w}})$-th copy.
\end{itemize}

Let us denote for $\textnormal{supp}_i(\widetilde{\boldsymbol{w}}) = \big\{h \in [H] \quad \big|\quad T_i^{(h)}(\widetilde{\boldsymbol{w}}) \neq \widetilde{\boldsymbol{w}}\big\}$ for $i = 1,2$. The image in $\Sigma^{[2]}_{\widetilde{\boldsymbol{v}}}$ of the $\widetilde{\boldsymbol{w}}$-th copy of
\[
\bigcup_{ \epsilon,\epsilon' \in \{\pm 1\}} \bigg(\widehat{\amsmathbb{H}}^{\epsilon} \setminus \bigcup_{g \in \textnormal{supp}_1(\widetilde{\boldsymbol{w}})} \overline{\amsmathbb{B}}_g^{\epsilon}\bigg) \times \bigg(\widehat{\amsmathbb{H}}^{\epsilon'} \setminus \bigcup_{g \in \textnormal{supp}_2(\widetilde{\boldsymbol{w}})} \overline{\amsmathbb{B}}_g^{\epsilon'}\bigg)
\]
is denoted $\Sigma^{[2]}_{\widetilde{\boldsymbol{v}},\widetilde{\boldsymbol{w}}}$ and called the $\widetilde{\boldsymbol{w}}$-th sheet. The $\widetilde{\boldsymbol{v}}$-th sheet is called the principal sheet.","status":"unverified"}

