     where 
     \begin{align*}
         Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{ll}\mathbb{I} & -J \\ J & \mathbb{I}\end{array}\right).
     \end{align*}

     \item If $M=\left(\begin{array}{lll}A & x & B \\ y & q & yJ \\ C & Jx & D\end{array}\right)$ is an $N \times N$ centrosymmetric matrix with $N=2s+1$, and $A, B, C, D$  are  $s \times s$ matrices, $x$ is $s \times 1$ matrix, $y$ is $1 \times s$ matrix, and $q$ is a scalar, then $M$ is orthogonally similar to
     \begin{align*}
         Q^{T} M Q=\left(\begin{array}{ccc}
			A+J C & \sqrt{2} x & 0 \\
			\sqrt{2} y & q & 0 \\
			0 & 0 & A-J C
		\end{array}\right),
     \end{align*}
		where
  \begin{align*}
      Q  =  \sqrt{\frac{1}{2}}\left(\begin{array}{lll} \mathbb{I} & 0 & -J \\ 0 & \sqrt{2} & 0\\ J & 0 & \mathbb{I}\end{array}\right).
  \end{align*}
 \end{enumerate}
 Here $\mathbb{I}$ is the identity matrix and $J$ is the counter-identity matrix. In both cases $Q^TQ=\mathbb{I}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.557682+00:00","domain":"probability theory","id":"claim_cb191488340f760839ab356a269f2b3f330eba1c6d1410c85c9c03694bff978c","kind":"definition","schema_version":1,"statement":"[Definition {\cite{MR773445}} of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] A characteristic function $f$ is said to be \textit{geometrically infinitely divisible} if for every $p\in(0,1)$ there exists a characteristic function $g_p$ such that
    \begin{align}
        f(\xi)=\frac{p\,g_p(\xi)}{1-(1-p)g_p(\xi)}.
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:40:59.350874+00:00","domain":"probability theory","id":"claim_cb1d651774e1be5aabbb15a609f43d274beebc7baf688afd70ed0c01b66e740f","kind":"theorem","schema_version":1,"statement":"[Proposition 22 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] For every $j\ge j_0$ there exist continuous representations
\[
 \tau_j:G_{\{p\}}\longrightarrow\GG(\Z/p^j\Z)
\]
and
\[
 \varrho_{j+R}:G_{\{p\}}
 \longrightarrow\GG(\Z/p^{j+R}\Z)
\]
such that
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\varrho_{j+R}\pmod{p^j}=\tau_j$;
\item $\tau_{j+1}\pmod{p^j}=\tau_j$;
\item $\varrho_{j+R}\pmod{p^R}=\rho_R$;
\item $\tau_{j_0}=\rho_{2A}^*\pmod{p^{j_0}}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:14:46.359600+00:00","domain":"probability theory","id":"claim_cb2562526eb53286844945c7ec19ebaf705abeac4c44a6140e92ec284e0f34b7","kind":"theorem","schema_version":1,"statement":"[Theorem of arXiv:2608.10415, 'Continuous random variables'] When flipping a biased coin $n$ times in a row:
\begin{enumerate}
\item $E({\rm heads})=np$.

\item $E({\rm tails})=n(1-p)$.

\item $E(a\times{\rm heads}+b\times{\rm tails})=n(ap+b(1-p))$.
\end{enumerate}","status":"unverified"}

