\\
\leq 
\inf_{\omega\in\ell^\infty(X)}
\sup_{A}\euler^{-\omega}
\sup_{B}\euler^{\omega}
\left(
\fint_I
\tvert{P_\tau^\omega}_{A,A,2,q}^q
\drm \tau
\right)^\frac{1}{q}
\left(
\fint_I
\tvert{P_\tau^{-\omega}}_{B,B,2,q}^q
\drm \tau
\right)^\frac{1}{q}.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:06:42.726864+00:00","domain":"probability theory","id":"claim_cd4548153ec85813ad849dd96b7d2c484697031f4796b2c55f5148ea5e6f18f0","kind":"concept","schema_version":1,"statement":"[Theorem Main-Theorem-1 of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] For every $\varepsilon,\delta(\varepsilon)>0$, let $\theta_{\varepsilon,\delta(\varepsilon)}$ be a stochastic generalized Leray solution of (equation SPDE-SQG of the paper) in the sense of Definition (def-stochastic-leray of the paper) with initial data $ \theta_{\varepsilon, \delta(\varepsilon)}(0)$ satisfying Assumption (Gaussian-initial-data of the paper). Let $\mu_{\varepsilon}=\mu_{\varepsilon,\delta(\varepsilon)}$ be the laws of $\theta_{\varepsilon,\delta(\varepsilon)}$ on $\mathbb{X}_{\alpha,\beta}$. Let $ \mathcal{C}_0\subset\mathbb{X}_{\alpha,\beta}$ be a weak-strong uniqueness class of (equation PDE-SQG of the paper) and   $\mathcal{C}=\overline{\mathcal{C}_0}^{\mathcal{I}}$. Assume that the scaling regime (equation scaling-delta of the paper) holds for $(\varepsilon,\delta(\varepsilon))$. Then for any closed set $F\subset\mathbb{X}_{\alpha,\beta}$,
	\begin{equation*}
		\limsup_{\varepsilon\rightarrow0}\varepsilon\log\mu_{\varepsilon}(F)\leqslant-\inf_{\theta\in F}\mathcal{I}(\theta),  	
	\end{equation*}
	and for any open set $G\subset\mathbb{X}_{\alpha,\beta}$, 	\begin{equation*}
		\liminf_{\varepsilon\rightarrow0}\varepsilon\log\mu_{\varepsilon}(G)\geqslant-\inf_{\theta\in G\cap \mathcal{C}}\mathcal{I}(\theta). 	
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.566748+00:00","domain":"probability theory","id":"claim_cd4868c0d132b6d6fd968b03e356b856fd0fcfb1e142a7b01aaf46f732ba1b00","kind":"lemma","schema_version":1,"statement":"[Lemma L:lmm_tu of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $0<s<t$, and $a,b,c \in \mathbb{R}$ satisfy the property that $-1 <a <0$, $b > c
    \geq -2$ and $a + b + c > -4$. Furthermore, suppose that $t - s \ll s$. Denote
  by
  \begin{align*}
    I  \coloneqq & \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_2 \int_{s}^{\theta_2} \ensuremath{\mathrm{d} } \theta_1  \int_0^s \ensuremath{\mathrm{d} } r_2 \int_{0 \vee (r_2 - \theta_2 + \theta_1)}^{r_2} \ensuremath{\mathrm{d} } r_1 \: (r_2-r_1)^{a}  (\theta_1 - r_1)^{b}  (\theta_2 - r_2)^{c} \shortintertext{and}
    I' \coloneqq & \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_2 \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_1  \int_0^s \ensuremath{\mathrm{d} } r_2 \int_{0}^{(r_2 - \theta_2 + \theta_1) \wedge r_2} \ensuremath{\mathrm{d} } r_1 \: (r_2-r_1)^{a}  (\theta_1 - r_1)^{c} (\theta_2 - r_2)^{b}.
  \end{align*}
  Then, the following inequalities hold.
  \begin{align*}
    I \lesssim (t-s)^{(a + b + c + 4)\wedge 2} \quad  \text{and} \quad
    I' \lesssim \begin{dcases}
                  (t-s)^{(a + b + c + 4)\wedge 2}, & a + b + c \neq -2, \\
                  (t-s)^2 (1 + |\log (t-s)|),      & a + b + c = -2.
                \end{dcases}
  \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:02:34.840366+00:00","domain":"probability theory","id":"claim_cd48ca07e5c3a0675d84f162196b534b1d3f00399de6ace87a53fa1de0a48392","kind":"theorem","schema_version":1,"statement":"[Proposition 5 of arXiv:2607.20714, 'High Minima of Gaussian Processes: Overshoots and Minimizer Locations'] Suppose that $\sigma_*^2>0$, and let $T$ be any measurable selection from
