{"assumptions":[],"created_at":"2026-10-27T06:25:55.319335+00:00","domain":"probability theory","id":"claim_d2f910512b01e64f78f181cdd2901d8c0dfd4e71361744a655988b5f327219cc","kind":"lemma","schema_version":1,"statement":"[Lemma 31 ({\cite[Theorem~1.4) of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] {PeltolaWuGlobalMultipleSLEs}}]

Fix an even number $n=2N$ and a nice $n$-polygon $(\Omega;x_1,\ldots,x_n)$. Let $\Gamma$ be the GFF in $\Omega$ with alternating boundary data\footnote{with the convention that $x_{2N+j}=x_j$.}
\begin{align*}
	0 \text{ on } \bigcup_{j=1}^N (x_{2j-1}x_{2j}), \qquad \pi \text{ on }\bigcup_{j=1}^N (x_{2j}x_{2j+1}).
\end{align*} 
Let $\eta^j$ be the level line of the field starting from $x_{j}$ for $1\le j\le N$. Then the probability of the rainbow connectivity is
\begin{align*}
	\PP\left[ \eta^j \text{ terminates at } x_{n-j+1} \text{ for } 1\le j\le N \right]
	=\frac{\LZ_{\rainbow}^{(4)}(\Omega;x_1,\ldots,x_n)}{\LZ_n(\Omega;x_1,\ldots,x_n)},
\end{align*}
where $\LZ_{\rainbow}^{(4)}$ is defined in~\eqref{eqn::rainbow_pf4} and $\LZ_n$ is defined by conformal covariance from~\eqref{eqn::LZunitdisc_def}: if $\varphi:\Omega\to\U$ is conformal with $\varphi(x_j)=\ee^{\ii\theta_j}$ and $\bs{\theta}\in\LX_n$, then
\begin{align}
	\LZ_n(\Omega;x_1,\ldots,x_n)
	:=\prod_{j=1}^{n}|\varphi'(x_j)|^{\frac{1}{4}}\LZ_n(\bs{\theta})
	=\prod_{1\le i<j\le n}\Poisson(\Omega;x_i,x_j)^{-\frac14(-1)^{j-i}}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.360488+00:00","domain":"probability theory","id":"claim_d2f9c44c2690761b62c75b46cb6352356eb44304f81253233b4997d12cf56107","kind":"theorem","schema_version":1,"statement":"[Proposition prop:lumped-BE-kernel of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Let $\overline K$ and $\overline\pi$ be the transition kernel and stationary distribution of the lumped twisted Bose--Einstein Markov chain on $\mathrm{Comp}_{n,k}$. Then for all $\bm{i},\bm{j}\in\mathrm{Comp}_{n,k}$,
\begin{equation}
 \overline K(\bm{i},\bm{j})
 =
 \sum_{M=(m_{a,b})\in\mathcal{M}(\bm{i},\bm{j})}
 \prod_{a=1}^k\frac{i_a!}{(\theta)_{(i_a)}}
 \prod_{a,b=1}^k
 \frac{(\theta/k)_{(m_{a,b})}}{m_{a,b}!}
\end{equation}
and
\begin{equation}
 \overline\pi(\bm{i})
 =
 \frac{n!}{(k\theta)_{(n)}}
 \prod_{a=1}^k\frac{(\theta)_{(i_a)}}{i_a!}.
\end{equation}
In particular, $\overline\pi$ is the Dirichlet--multinomial distribution with parameters $n$ and $(\theta,\ldots,\theta)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.612065+00:00","domain":"probability theory","id":"claim_d2fe388bc7a0ea0e59e2c2debaee1c9ecf9fe83a83e061213c6759134521d435","kind":"lemma","schema_version":1,"statement":"[Lemma lem-resample-infty-2.5 of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] For $(\phi, \eta) \sim M_W$, let $\tau$ be the time $\eta$ separates $i$ from $\infty$, let $\sigma< \tau$ be the first time at which $\eta (\sigma) = \eta(\tau)$, and let $\mathcal{QCP}_{\phi, \eta((0, \sigma))\cap \mathbb{R}}$ denote the quantum cut point measure of $\eta ((0, \sigma)) \cap \mathbb{R}$. More precisely, this is the quantum cut point measure of the thin quantum disk defining $(\phi, \eta)$ (Definition~(def-thin-wedge of the paper)) restricted to the set of cut points $\eta ((0, \sigma)) \cap \mathbb{R}$.
	     Weight the law of $(\phi, \eta)$ by $|\mathcal{QCP}_{\phi, \eta((0, \sigma))\cap \mathbb{R}}|$ and sample a point $p \sim \mathcal{QCP}_{\phi, \eta((0, \sigma))\cap \mathbb{R}}^\#$. 



	    Define $(\mathcal{D}_1,\mathcal{D}_2, \tilde \mathcal{D})$ as in Lemma~(lem-resample-infty-1 of the paper). Let $\mathcal{D}_3$ (resp.\ $\mathcal{D}_4$) be the ordered subset of $\tilde \mathcal{D}$ corresponding to two-pointed quantum surfaces disconnected after (resp.\ before) $\eta$ hits $p$. Then the law of $(\mathcal{D}_1, \mathcal{D}_2, \mathcal{D}_3, \mathcal{D}_4)$ is
        \begin{align*}
           C\int 1_{r_1+r_2+r_3+r_4> \ell_2, r_4 < \ell_2}  \Big( &{\mathcal{M}}^\mathrm{disk}_{0,2}(W; r_1+r_2+r_3+r_4 - \ell_2, r_1) \times {\mathcal{M}}^\mathrm{disk}_{0,2, \bullet}(\gamma^2-W; \ell_2, \cdot, r_2) \\
           &\times {\mathcal{M}}^\mathrm{disk}_{0,2}(W; \cdot, r_3) \times {\mathcal{M}}^\mathrm{disk}_{0,2}(W; \cdot, r_4) \Big), 
        \end{align*}
	    where the integral is taken over $(\ell_2, r_1,r_2,r_3,r_4)$ with respect to Lebesgue measure on $(0,\infty)^5$, and $C = (1-\frac2{\gamma^2}W)^4$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.301973+00:00","domain":"probability theory","id":"claim_d306a584cf46eb298f812d27e7bf7d6c96d3e36379215aad5524d49787a5c3be","kind":"definition","schema_version":1,"statement":"[Definition def:results:CBP of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $(U, W)$ satisfy Assumption (as:results:lyapunov of the paper) and Assumption (as:results:invMeasure of the paper). We say $\nu \in {\mathcal{M}_{\kappa, d}}$ is a \emph{Cayley fixed point{}} if $\nu$ is of the form \begin{equation}
        \nu(\mathbf{x}) = \nu_0(x_0)\prod_{i = 1}^\kappa \bar{\nu}(x_i | x_0),

    \end{equation}
    where $\nu_0 \in \mathcal{P}(\ensuremath{\mathbb{R}}^d)$ is absolutely continuous and solves the following fixed point equation
    \begin{equation}

        \nu_0(x)^{\frac{1}{\kappa}} = \frac{1}{\mathcal{Z}_{\nu_0}} e^{-\tfrac{1}{\kappa}U(x)}\int_{\ensuremath{\mathbb{R}}^d} e^{-W(x-y) - \frac{1}{\kappa}U(y)}\nu_0(y)^{\frac{\kappa-1}{\kappa}} dy, \quad \nu_0\text{-a.e. }x \in \ensuremath{\mathbb{R}}^d,
    \end{equation}
   where the normalizing constant is given by 
    \begin{equation}

        \mathcal{Z}_{\nu_0} := \int_{\ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d} \exp\Big( - \tfrac{U(x) + U(y)}{\kappa} - W(x -y)\Big) \big[\nu_0(x)\nu_0(y)\big]^{\frac{\kappa-1}{\kappa}} dx dy,
    \end{equation}
    and $\bar{\nu}(x|y) := \bar{\nu}(x, y) / \nu_0(y)$ for $\nu_0$-a.e. $x, y \in \ensuremath{\mathbb{R}}^d$ where the edge marginal $\bar{\nu}(x, y)$ of $\nu$ is mutually absolutely continuous with respect to $\nu_0^{\otimes 2}$ and is of the form
    \begin{equation}

        \bar{\nu}(x,y) = \frac{1}{\mathcal{Z}_{\nu_0}}\exp\Big( - \tfrac{U(x) + U(y)}{\kappa} - W(x -y)\Big) \big[\nu_0(x)\nu_0(y)\big]^{\frac{\kappa-1}{\kappa}}, \quad \nu_0^{\otimes 2}\text{-a.e. }(x, y) \in \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:57:30.962610+00:00","domain":"probability theory","id":"claim_d3077dc0ec159f51b65238e351d3b0cbac37885c7165a2369bdd075d2578dd6f","kind":"concept","schema_version":1,"statement":"[Theorem 14 (Free-boundary integral equation) of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] The optimal boundary $b_T$ solves
\begin{equation}
    \begin{aligned}
        g(x)=\mathbb{E}\Bigg[g(X^x_{T-t})&+\int_0^{T-t}c(t+u)\ind{X^x_{u}\in(1-b_T(t+u),b_T(t+u))}\,du\\
        &-\int_0^{T-t}\mathcal{L}g(X^x_{u})\ind{X^x_{u}\not\in(1-b_T(t+u),b_T(t+u))}\,du\Bigg],
    \end{aligned}
\end{equation}
for $x=b_T(t)$ and $x=1-b_T(t)$ with $t<T$. For $T=\infty$, the integral is interpreted as the monotone limit as the integration domain expands and $g(X^x_{T-t})=0$ since $X^x_{\infty}\in\{0,1\}$, almost surely.

Moreover, this equation characterizes the optimal boundary uniquely in the following sense. 
If $\beta:[0,T)\to(1/2,1)$ is a continuous function satisfying
\[
    \gamma(t)<\beta(t)<1
\]
and solves \eqref{eq:main_boundary_integral} with $b_T(t)$ replaced by $\beta(t)$ for all $t<T$, then $\beta(t)=b_T(t)$ for all $t<T$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

