{"assumptions":[],"created_at":"2026-10-26T19:30:52.742878+00:00","domain":"probability theory","id":"claim_d617a83f03cfafbf51ad0c1673f989c02978b3bed5b6c84294079fc6e99cc561","kind":"concept","schema_version":1,"statement":"[Proposition 54 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] [\cite{Minh:2020regularizedDiv}]

