    \frac{\log\mathcal{C}_t([s-\delta,s+\delta])}{\log\delta}
    =
    d_{\mathrm{ct}},
    \qquad
    \mathcal{C}_t\text{-}\mathrm{a.e.}\ s.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:42:57.183645+00:00","domain":"probability theory","id":"claim_db9527b89bd4889017bbaf0cfc737d95b5e860218165eff1d715ca15d15e86d0","kind":"concept","schema_version":1,"statement":"[Lemma lem:metric-ball-locality of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] {kkmt2026cle4_part2}}]
	Let $U \subsetneq \BC$ be a simply connected domain. Let $z \in U$ be deterministic. Let $\tau$ be a stopping time for the filtration generated by 
	\begin{equation*}
		\left(\SCB_t(\SCL(z); D_{\Gamma_U}^U), \Gamma_U|_{\SCB_t(\SCL(z); D_{\Gamma_U}^U)}\right)_{t \ge 0}. 
	\end{equation*}
	Then the following is true: Let $V \subset U$ be a deterministic simply connected domain. Write $\{V_j\}_j$ for the connected components of $V^\star$ (recall~(equation eq:def-V-star of the paper) for the definition of $V^\star$).  Let $(\Gamma_U, D_{\Gamma_U}^U, \{D_{\Gamma_U|_{V_j}}^{V_j}\}_j)$ be coupled as in (def:weak_axioms of the paper), Axiom~(equation it:weak_axiom_locality of the paper) (locality). Then, on the event that $\SCB_\tau(\SCL(z); D_{\Gamma_U}^U) \cap V^\star = \emptyset$, conditionally on $\SCB_\tau(\SCL(z); D_{\Gamma_U}^U)$, on $V^\star$ and on the $\sigma$-algebra generated by~(equation eq:weak_axiom_locality of the paper), the $(\Gamma_U|_{V_j}, D_{\Gamma_U|_{V_j}}^{V_j})$'s are independent and their conditional laws are those of $(\Gamma_{V_j}, D_{\Gamma_{V_j}}^{V_j})$, respectively.
	The same is true with a deterministic connected arc of $\partial U$ in place of $\SCL(z)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:38:57.145131+00:00","domain":"probability theory","id":"claim_db96e98ab52fc105f3851c3b04c0395b0cdab20fdf397c2064942877a4576ae8","kind":"lemma","schema_version":1,"statement":"[Lem 20 of arXiv:2604.06122, 'REM universality for linear random energy'] Given $a\in (0,\varsigma)$ and a $h-$measurable sequence $(A_n)_{n\in \N}$ such that
\been{

\lim_{n\to \infty}\res A_n(h)=a,\qquad \gas
}
we have
\been{

\lim_{n\to \infty}\Lambda_n(h,A_n(h))=\hat \lambda(a),\qquad \gas
}
and 
\been{

\lim_{n\to \infty} \res M^*_n(h,A_n(h))=G^*(a),\qquad \gas.
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:00.611946+00:00","domain":"probability theory","id":"claim_db970ba5385b49d8bc2018221d6d949164564f214f165acf067a0130368d83e4","kind":"theorem","schema_version":1,"statement":"[Proposition 11 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] Let us be given two measures $\mu,\nu \in \mathcal{P}_1(\R)$ on the real line with the same barycentre, $[\mu] = [\nu]$. Then, 
	\begin{equation}

		\rho = \mu \vee \nu := (\FF_\mu \vee \FF_\nu) ''
	\end{equation}
	is a solution of the optimal convex dominant problem \eqref{eq:conv_dom} for  any convex cost function $f:\R\to\R \cup \{+\infty\}$ such that  $\inf \eqref{eq:conv_dom} < +\infty$.

	Moreover, if $f$ is strictly convex, then the solution $\rho = \mu \vee \nu$ is unique.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:53:54.887503+00:00","domain":"probability theory","id":"claim_dba0f373e8f134388373934ac38ddf70f836cfa01fa9c66792e6d27a26eae5d4","kind":"concept","schema_version":1,"statement":"[Lemma 31 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] For every fixed $k\ge 0$ and $\vv \zeta=( \zeta_0,\dots,\zeta_k)$,
\begin{equation}
\lim_{m\to\infty}
\tfrac{
\EE\left[
\left(
R_m(\vv\tau)
+\frac{R_k(\vv\zeta)P_m(\vv\tau)}
       {P_{k+1}(\vv\zeta)}
\right)^{-\alpha}
\prod_{j=1}^k
R_j^{\,2t_{j+1}-2t_j}(\vv\zeta)
\right]
}
{\EE\left[R_m^{-\alpha}(\vv\tau)\right]}
=
\EE\!\left[
\prod_{j=1}^k
R_j^{\,2t_{j+1}-2t_j}(\vv\zeta)
\right].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:58:38.148313+00:00","domain":"probability theory","id":"claim_dba38f3c192305bec049437e61bcc877a6de8a1c828e713befcc6d00c9c4dd0a","kind":"lemma","schema_version":1,"statement":"[Lemma claim:S over 64v of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] There exists a  constant $C>0$ such that for any $n\geq 1$, and $t \leq n/16$,
        \begin{equation}\begin{aligned}
        \mathbb{P}\Big(\Big|\Big\{u \in [n] &: \phi_n^{\scriptscriptstyle{({2}})}(u) > \Big( \frac{n}{64t}\Big)^2 \Big\}\Big|\le t\Big)\\ &\le
            \mathbb{P}\left(\Big|\left\{u \in [n] : \phi_n(u) >  \frac{n}{64t} \right\}\Big|\le t\right) \leq C \exp \Big( -  \frac{t}{8} \Big) .\end{aligned}
        \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.122548+00:00","domain":"probability theory","id":"claim_dba698d113fbf1cc099679157431e7be51ba3e24533586a3e5d84a1aadd276f9","kind":"lemma","schema_version":1,"statement":"[Lemma lem:uniqueness of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Let $\nu$ be any probability measure on $[0,\infty)$, $c>0$, and $z\in\mathbb{C}_+$. The equation
\begin{equation}
  \frac1m+z
  =\int_0^\infty\frac{r}{1+crm}\,\nu(\,\mathrm{d} r)

\end{equation}
has at most one solution $m\in\mathbb{C}_+$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.199380+00:00","domain":"probability theory","id":"claim_dbaaf8960705a5aef44fad2018a311c253048cf46300a0881d52a9258d0eee04","kind":"concept","schema_version":1,"statement":"[Theorem 22 ({\cite[Theorem 4.9) of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] {ZB+GD-21}}]
		Let $\mathcal{X}$ be a topological space such that there exists a sequence $\{f_m\}_{m\in\N}$ of continuous functions $f_m:\mathcal{X}\to\mathbb{R}$ that separates points of $\mathcal{X}$. Let us denote by $\mathcal{S}$, the $\sigma-$algebra generated by the sequence of maps $\{f_m\}_{m\in\N}$. Then
		\begin{itemize}
			\item[(a)] every compact subset of $\mathcal{X}$  is metrizable,
			\item[(b)] if $\{\nu_m\}_{m\in\N}$ is a tight sequence of probability measures on $(\mathcal{X}, \mathcal{S})$, then there exists a subsequence $\{m_k\}_{k\in\N}$, a probability space $(\Omega,\Fn,\Pr)$ with $\mathcal{X} - $valued Borel measurable random variables $\xi_k,\xi$ such that $\mu_{m_k}$ is the law of $\xi_k$ and $\xi_k$ converges to $\xi$ almost surely on $\Omega$. Moreover, the law of $\xi$ is a Radon measure.
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:17.755809+00:00","domain":"probability theory","id":"claim_dbb2e7f39d55cad3c04662dc519ca1bd8c6b234416aa72a8a744e5e62409e0a6","kind":"theorem","schema_version":1,"statement":"[Proposition 13 of arXiv:2511.04938, 'Uniform dimension theorems for parabolic SPDEs'] For every $T > 0$,
	\begin{equation}\begin{aligned}
		&\Var(H_1(t\,,x)\mid H_1(t_1\,,x_1),\dots,H_1(t_m\,,x_m))\\
		&\hskip1in \asymp 
			\min\left\{ \sqrt{t}\, , \min_{1\le j\le m}\left( |t-t_j|^{1/2} + |x-x_j| \right)\right\}, 
	\end{aligned}\end{equation}
	uniformly for all $m\in\N$ and $(t\,,x), (t_1\,,x_1), \dots, (t_m\,,x_m) \in (0\,,T] \times \T$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:25:06.155107+00:00","domain":"probability theory","id":"claim_dbb786ba98e3aac3e1b0303b34a05f0f0124a70ba0282881056962b8f2f83b25","kind":"concept","schema_version":1,"statement":"[Proposition 13 of arXiv:2608.22534, 'Entropy power inequalities in compact groups'] Let $G$ be a compact and metrizable topological abelian group
equipped with its Borel $\sigma$-algebra, and let $\mu$ denote the Haar 
probability measure on $G$. 
For any $G$-valued random variables $X, Y$ with finite entropies 
there is a non-empty, closed subset $S$ of $G$ of positive Haar 
measure such that, if $U_S$ is uniformly distributed on $S$, then,
for any constant $C\geq 4$,
\begin{equation} 
\dR(U_S, Y) \leq (C+2)\dR(X, Y) + H_2(1 - 2/C), 
\end{equation}
and
\begin{equation}
\log \frac{\mu(S-S)}{\mu(S)} \leq (2C+4)\dR(X, Y) + 2H_2(1 - 2/C).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.258187+00:00","domain":"probability theory","id":"claim_dbb787cb9e46dc59086e568b861405adcc0a5349762ceb89d819d983d0196409","kind":"concept","schema_version":1,"statement":"[Thm 75 ({\cite[Theorems 1.5(ii) and 1.7) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {BTM24}}]
Let $\alpha>2$ and $E\in \left(0,\frac{\alpha-2}{10(2\alpha-1)}\right)$.
Then it holds for any $K\in (0,\infty)$ and $0<T_1<T_2<\infty$ that
\begin{equation*}
  \sup_{x\in \R}|P_0(X_1\le x)-P^n_0(X^n_1\le x)|=O(n^{-\theta}),
\end{equation*}
and
\begin{equation*}
  \lim_{n\to\infty}n^{\frac{2}{3}E}\sup_{\substack{|x|\le K\\t\in [T_1,T_2]}}\left| p(t,0,x)-p_n\left( t,0,\frac{\floor{nx}}{n} \right) \right|=0,
\end{equation*}
$P$-almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.656784+00:00","domain":"probability theory","id":"claim_dbb88883e9ac172f8511e5457d983d272d3993b0b8b412347ab486b791948226","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2609.01885, 'The Order of the Non-universal Tree of a Hilbert Space with Respect to the Haar Basis'] Let $T$ be a tree on a set $A$. An \textbf{infinite hand} in $T$ is a sequence $(s_n)_{n=0}^\infty\subseteq T$ with the following properties:
\begin{enumerate}
\item $(|s_n|)_{n=0}^\infty\subseteq\mathbb N$ is strictly monotone increasing.
\item There exists an element $s\in T$ with $s\sqsubset s_n$ for every $n$; the element of largest length which satisfies this property is called the \textbf{palm} of the infinite hand.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.775605+00:00","domain":"probability theory","id":"claim_dbb892c63d1716d37df3ca32bad4e7bdd79efdfe1a2383f8fc4e744f62335b65","kind":"lemma","schema_version":1,"statement":"[Lemma lem:delta of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] Under any coupling between $\mathbf{X}$ and $\mathbf{Y}$, we have
\begin{align}
    \mleft|
        \operatorname{Cov}[X^i(0), X^j(t)]
    \mright|
    &\leqslant
    2 \sqrt{
        \mathbb{E} \mleft[ X^i(0) (X^i(0) - Y^i(0)) \mright] \cdot
        \mathbb{E} \mleft[ X^j(t) (X^j(t) - Y^j(t)) \mright]
    } \\

    &\qquad + \mathbb{E} \mleft[ Y^i(0) (X^j(t) - Y^j(t)) \mright]
        + \mathbb{E} \mleft[ (X^i(0) - Y^i(0)) Y^j(t) \mright] \\

    &\qquad + \mathbb{E}\mleft[Y^i(0)\mright] \mathbb{E}\mleft[ X^j(t) - Y^j(t) \mright]
    + \mathbb{E} \mleft[ X^j(t) \mright] \mathbb{E} \mleft[ X^i(0) - Y^i(0) \mright].
\end{align}
Moreover, both factors appearing under the square root in (equation decom4631 of the paper) are nonnegative.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:04:59.427389+00:00","domain":"probability theory","id":"claim_dbbafe4c184a48dd9963dba60defade867be3bc1b7c8b013fb40f24d2a321583","kind":"concept","schema_version":1,"statement":"[Lemma lem:two-point-decompose of arXiv:2605.19419, 'Tail exponents of the three-dimensional uniform spanning tree and Abelian sandpile'] Suppose $4r<R$ and $x\in\partial B_R$, $y\in\partial B_r$. Suppose that $\gamma$ is an ILERW started from $0$. $S_{1}$ and $S_{2}$ are two independent SRWs started from $x$ and $y$. Write $P_{x,y}$ for their joint law. Let $E$ denote the intersection of the following events:
\begin{itemize}
\item[1.]\ $S_{1}$ hits $0$ and, writing $\tau_{1}$ for the first hitting time of $0$, $S_{1}[0,\tau_{1}]\cap\gamma=\{0\}$.
\item[2.]\ $S_{2}$ hits $\operatorname{LE}(S_1[0,\tau_1])$ before it intersects $\gamma$.
\end{itemize}
Then,
\begin{equation}
P_{x,y}(E)\gtrsim (\log r)^{-1}R^{-1-\alpha}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:57:30.993195+00:00","domain":"probability theory","id":"claim_dbc0ec2cc0f8dfde758a66b68a27986cd406b8aea543762db6c3e4e38aa5a335","kind":"lemma","schema_version":1,"statement":"[Lemma 32 (Stein interpolation) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Let $A,B$ be centered $\R^d$-valued vectors with components in
$\mathbb D^{1,2}$, and put $C=\Cov(B)$.  Then, for $u,v\in\R^d$,
\begin{align}
 &\left|
 \E e^{i(u\cdot A+v\cdot B)}
 -\E e^{iu\cdot A}e^{-\frac12v^{\mathsf T}Cv}
 \right|\notag\\
 &\quad\le
 |u|\,|v|
 \left(\sum_{a,b}\norm{\Gamma(A_a,B_b)}_2^2\right)^{1/2}
 +\frac{|v|^2}{2}
 \left(\sum_{a,b}
 \norm{\Gamma(B_a,B_b)-C_{ab}}_2^2\right)^{1/2}.

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.244357+00:00","domain":"probability theory","id":"claim_dbc1da0dab44fb18cd4a5b6b5ced7f3f2309155149822431646a9d759302ba56","kind":"concept","schema_version":1,"statement":"[Theorem theorem12 of arXiv:2607.01463, 'Two Multi--Draw Coupon Collector models with different retention rules'] Consider the  $d$ coupon collector's problem (d--CCP), where in each run we keep \textbf{the least-collected} coupon so far. Let $T_{N,1}$ be the number of trials until all $N$ different types of coupons, which are uniformly distributed, are collected (at least once). Then,
\begin{equation}
\mathbb{E}[T_{N,1}]
=
\sum_{k=0}^{N-1}
\frac{1}{1-\binom{k}{d}/\binom{N}{d}},

\end{equation}
where $\binom{k}{d}=0,$ if $k<d$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.350783+00:00","domain":"probability theory","id":"claim_dbc749c84012c10ac36d23e44d879db72ad1c323719f22621d3730287ed2285e","kind":"concept","schema_version":1,"statement":"[Lemma 6 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] There exists a universal constant $\gamma > 0$ such that for $p > \fr{1}{2} - \gamma$,
there is some constant $\alpha_p > \fr{(2-p)^2}{2}$ such that
for any $\epsilon \geq \fr{1}{\poly(d)}$,
\begin{equation}
    \pi[\Adj(S) > \epsilon] \leq \Exp{- \fr{1}{\poly(d)} \cdot \alpha_p^d} \cdot (1 + o(1)),
\end{equation}
where the $o(1)$ term tends to $0$ in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:13:31.955724+00:00","domain":"probability theory","id":"claim_dbc814cb5913787e1637190663ee41e28ebdd34f89a85892b73baf367e6c50c0","kind":"concept","schema_version":1,"statement":"[Lemma lem:zeta of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] For our choice of shifts, $h \lesssim \gamma^{-1} \wedge \gamma/\beta$ and $c_0/A \lesssim 1$ for sufficiently small implied constants, and $\gamma \leqslant \sqrt{32\beta}$, we have
\begin{align*}
    \zeta_n \lesssim \frac{\beta h}{\gamma_{nh}} + h \eta_{nh}^\mathsf{p}\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:14:37.646785+00:00","domain":"probability theory","id":"claim_dbcbbbca9dc4dd629c49bfb63cd52bd97a82c901ed4253834be648295ea7a3b8","kind":"theorem","schema_version":1,"statement":"[Theorem 3 of arXiv:2608.19560, '\textbf{Computing transient probabilities in Markovian queues with balking conditional on '] The PGF $\pi_{k,\ell,s}^*(z,t \mid K)$ conditional on exactly $K$ customers
joined in $[0,T]$ is given by 

\begin{equation}
\pi_{k,\ell,s}^*(z,t \mid K)
=
\frac{p_{k,\ell,s}^*(z,t) q_{k,\ell,s}(\red{T-t},K)}
{\Pr[A^\join(T)=K]},
\quad 
(k,\ell,s) \in \Omega,\ 0 \leq t \leq T,

\end{equation}

where $p_{k,\ell,s}^*(\red{z},t)$ and $q_{k,\ell,s}(u,K)$ are given by Lemma
\ref{lem:p^*} and Lemma \ref{lem:q}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.562580+00:00","domain":"probability theory","id":"claim_dbd0a335f497bfe1f08ef21b67c8e1bbc5b0d3bd98fbbccec3ede27dacc1f9ea","kind":"lemma","schema_version":1,"statement":"[Lemma Generic Morse property of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:Morse}
For fixed \(N,p\), the set of coefficient tensors for which the restriction of \(H_N\) to \(\mathbb S_N\) is not Morse is contained in a proper real algebraic subset of \(\mathbb R^{N^p}\).  Consequently, if the joint coefficient law is absolutely continuous, the field is almost surely Morse.
The same conclusion holds when the coefficient law is absolutely
continuous with respect to Lebesgue measure on the space of symmetric
degree-\(p\) tensors.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.842840+00:00","domain":"probability theory","id":"claim_dbd4796f3e0635eb7d4b3f4739ca34d0f995f1b385335736c033d8d37d6705ba","kind":"concept","schema_version":1,"statement":"[Theorem 8 of arXiv:2608.13631, 'The classical discrete laws near the mode:\\ complete local expansions for the negative bi'] Under the hypotheses of Theorem~\ref{thm:hyp-main}, with $k=\mu+t$,
	\begin{equation}
		\log\Bigl[\sqrt{2\pi\,\frac{k\,(K-k)\,(n-k)\,(L+k)\,N}{K(N-K)\,n\,(N-n)}}\;P(k)\Bigr]
		\sim\sum_{m\ge1}\frac{\widehat A_m(t)}{N^{m}},
	\end{equation}
	with
	\begin{equation}
	\begin{gathered}
		\widehat A_m=\frac{(-1)^{m+1}}{m(m+1)}
		\Bigl[(W_m-1)\,B_{m+1}-\widehat\Xi_m\,\Bh_{m+1}(t)\Bigr],\\
		\widehat\Xi_m=(a^{-m}+d^{-m})
			+(-1)^{m+1}(b^{-m}+c^{-m}).
	\end{gathered}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:11:02.386382+00:00","domain":"probability theory","id":"claim_dbd66060b1974d50e6235c953243e0e86a4006dd0518e223f8ba23fef5d869d2","kind":"concept","schema_version":1,"statement":"[Corollary cor:global_subgraph_clt_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Recall the definition of $\sigma_n^2$ from (equation eq:sigmadef_global_intro of the paper).
For any $\varepsilon > 0$, 
\begin{equation}
    \mathbf{d}_\mathrm{Was} \mleft( \frac{\mathsf{N}_G(X) - \mathbb{E}[\mathsf{N}_G(X)]}{2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \sigma_n}, Z \mright) \lesssim n^{-\frac{1}{2}+\varepsilon}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.480653+00:00","domain":"probability theory","id":"claim_dbd76545cb5db914fda0d9b4fdc30d47974ba72bcb527ecfbc742ec37a4d5893","kind":"concept","schema_version":1,"statement":"[Thm 6 (Aru-Lupu-Sep\'ulveda \cite{ALS3}) of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $b>v$ and $a<v$, such that $b-a\geq 2\lambda$.
Also assume that $b-a\in 2\lambda \N$ (integer multiple of $2\lambda$).
Fix $z\in D$.
Then
\begin{displaymath}
\Big(\dfrac{1}{2\pi}\log\Big(\dfrac{\CR(z,D)}{\CR(z,D\setminus A_{a,b})}\Big), \ell_{a,b}(z), 
\ED(\partial D,\Gamma_{a,b}(z))\Big)
\end{displaymath}
has the same law as $(T_{a,b},W_{T_{a,b}},\tau_{a,b})$ under $W_{0} = v$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.587929+00:00","domain":"probability theory","id":"claim_dbda936cc1e3e5674398723a9f43c8a721a46f8ae60d6f227ef6da97ac12e301","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2609.01346, '2609.01346'] Let
\begin{equation}
 K_0\subset\{(x,r):x>0,\ r>0\}
\end{equation}
be a compact set of crossing data at $\theta=\pi/2$.  There is $u_0>0$ such
that every solution whose data at $u=0$ belong to $K_0$ is represented in the
$u$-chart on the full interval $[-u_0,u_0]$.  On a neighbourhood of the
corresponding incoming data, the map from the section $u=-u_0$ to the section
$u=u_0$, including the elapsed arclength, depends continuously on the
incoming data.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.828467+00:00","domain":"probability theory","id":"claim_dbde5203db5ad0e3e03238ed40aed24e1709b43e3cfc2356057c6161194055a2","kind":"definition","schema_version":1,"statement":"[Definition def:hoffman of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] On the enlarged alphabet $\overline E=\bigoplus_{m\ge1}E^{\odot m}$ of symmetric powers, in which a merged letter $[i_1\cdots i_r]$ denotes the symmetric product, let $\Phi$ be Hoffman's exponential: the graded Hopf-algebra isomorphism from the quasi-shuffle to the shuffle algebra acting on a word $w$ by
\begin{equation}
\Phi(w)=\sum_{w=B_1\mid\cdots\mid B_j}\frac{1}{|B_1|!\cdots|B_j|!}\,[B_1]\cdots[B_j],

\end{equation}
the sum ranging over compositions of $w$ into consecutive blocks. On the jump data a merged letter is evaluated by $[i_1\cdots i_r]\mapsto\sum_a z_a^{i_1}\cdots z_a^{i_r}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.573027+00:00","domain":"probability theory","id":"claim_dbe4c4cdee8f8ded0bd59646b2147330b570da6c8f1317646195f790ded70d9d","kind":"concept","schema_version":1,"statement":"[Prop 22 (Stochastic domination) of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $0\leq \beta'\leq \beta$. Let $G=(V,E)$ be a subgraph of $\mathbb Z^d$. Then, for every $\xi\in \{0,1\}^{E(\mathbb Z^d)\setminus E}$, and for every increasing event $\mathcal A\subset \{0,1\}^E$, the following inequalities hold:
\begin{equation}
	\phi_{G,\beta'}^{\xi}[\mathcal A]\leq \phi^1_{G,\beta}[\mathcal A],
\end{equation}
and
\begin{equation}
	\phi_{G,\beta'}^{0}[\mathcal A]\leq \phi_{\beta}[\mathcal A].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:10.027030+00:00","domain":"probability theory","id":"claim_dbe6961d8605d5a85000e78fef3f344d1346e471ac6adf23d9bb564b4382b307","kind":"theorem","schema_version":1,"statement":"[Theorem 33 of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] Fix $0 < \beta < 1$. Set $m(d)=\lfloor d^\beta\rfloor$ and let $k(d)$ be any sequence satisfying $k(d) \rightarrow \infty$, $\frac{m(d)k(d)}{d} \rightarrow 0$, and $\frac{k(d)}{m(d)} \rightarrow 0$.

Then there exist constants $0<c<C<\infty$ (depending only on $\beta$) such that for all sufficiently large $d$
and all $\varepsilon\in(0,1/4)$,
\begin{equation}
c\,d^{1-\beta}\bigl(\log(k(d))+\log(1/\varepsilon)\bigr)
\;\le\;
\tau_{\mathrm{mix}}^{(k(d))}(d,\varepsilon)
\;\le\;
C\,d^{1-\beta}\bigl(\log(k(d))+\log(1/\varepsilon)\bigr).
\end{equation}
Moreover, the full-chain mixing time satisfies the lower bound
\begin{equation}
\tau_{\mathrm{mix}}(d,\varepsilon)
\;\ge\;
c\,d^{1-\beta}\bigl(\log d+\log(1/\varepsilon)\bigr).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.258231+00:00","domain":"probability theory","id":"claim_dbe8e39028e4330255af511d5408e33f8aff8e87835daa8e896b90bf63fff1d0","kind":"concept","schema_version":1,"statement":"[Corollary 13 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} be valid with $N_{\infty} > 0$. Then for any positive solution $I$ to~\eqref{eq:a representative SIS epidemic model} the following two assertions hold:
\begin{enumerate}[(i)]
\item Assume that there are $a_{\infty}, b_{\infty}, c_{\infty}, d_{\infty}\in\R$ such that
\begin{align*}
\liminf_{s\uparrow \infty} h_{1}\big(s,N(s),\mathcal{L}(I_{s})\big) &\geq a_{\infty}, \quad \liminf_{s\uparrow \infty} h_{2}\big(s,N(s),\mathcal{L}(I_{s})\big) \geq b_{\infty},\\
\liminf_{s\uparrow \infty} h_{3}(s,N(s)) &\geq c_{\infty},\quad \limsup_{s\uparrow \infty} g_{1,1}(s)g_{1,2}(s)\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0})\leq d_{\infty}.
\end{align*}
If $a_{\infty} > d_{\infty}N_{\infty}^{\frac{3}{2}}$, then $I$ persists above the smallest zero $x_{0}$ of $f_{\infty}\colon ]0,N_{\infty}]\rightarrow\R$ defined by
\begin{equation}
f_{\infty}(x) := a_{\infty}+ b_{\infty}x + c_{\infty}x^{2} - d_{\infty}(N_{\infty}-x)^{\frac{3}{2}},
\end{equation}
and $x_{0} < N_{\infty}$ whenever $\gamma_{\infty} + \mu_{\infty} > 0$. Further, for $d_{\infty} = 0$ this zero is of the form $x_{0} = \frac{-b_{\infty}-\sqrt{b_{\infty}^{2}-4a_{\infty}c_{\infty}}}{2c_{\infty}}$, if $c_{\infty} \neq 0$, and $x_{0} = - \frac{a_{\infty}}{b_{\infty}}$, otherwise. 

\item Suppose that there are $\hat{a}_{\infty}, \hat{b}_{\infty},\hat{c}_{\infty},\hat{d}_{\infty}\in\R$ such that
\begin{align*}
\limsup_{s\uparrow \infty} h_{1}\big(s,N(s),\mathcal{L}(I_{s})\big) &\leq \hat{a}_{\infty}, \quad \limsup_{s\uparrow \infty} h_{2}\big(s,N(s),\mathcal{L}(I_{s})\big) \leq \hat{b}_{\infty},\\
\limsup_{s\uparrow \infty} h_{3}(s,N(s)) &\leq \hat{c}_{\infty},\quad \liminf_{s\uparrow \infty} g_{1,1}(s)g_{1,2}(s)\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0})\geq \hat{d}_{\infty}.
\end{align*}
If $\hat{a}_{\infty} \geq \hat{d}_{\infty}N_{\infty}^{\frac{3}{2}}$ and $\hat{a}_{\infty} + \hat{b}_{\infty}N_{\infty} + \hat{c}_{\infty}N_{\infty}^{2} < 0$, then $\liminf_{t\uparrow\infty} I_{t} \leq y_{0}$ a.s.~for the largest zero $y_{0}$ of $g_{\infty}\colon [0,N_{\infty}[\rightarrow\R$ given by
\begin{equation}
g_{\infty}(x) := \hat{a}_{\infty} + \hat{b}_{\infty}x + \hat{c}_{\infty}x^{2} - \hat{d}_{\infty}(N_{\infty}-x)^{\frac{3}{2}}.
\end{equation}
Further, for $\hat{d}_{\infty} = 0$ this zero is unique and of the form $y_{0} = \frac{-\hat{b}_{\infty} - \sqrt{\hat{b}_{\infty}^{2}-4\hat{a}_{\infty}\hat{c}_{\infty}}}{2\hat{c}_{\infty}}$, if $\hat{c}_{\infty} \neq 0$, and $y_{0} = - \frac{\hat{a}_{\infty}}{\hat{b}_{\infty}}$, otherwise.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

