&+N\sum_{\n_{2}=\mathrm{K}_{1}+1,\ldots,\mathrm{K}_{2}}\sum_{|\mathfrak{l}_{0}|\leq1}\mathrm{c}_{\n_{2}}\cdot N\grad^{\mathbf{X}}_{\mathfrak{l}_{0}}[\mathscr{S}^{N}\star(\mathfrak{q}_{\n_{2}}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot})]_{\x}\d\t.
\end{align}

\begin{itemize}
\item Above, {\small$\mathrm{K}_{1}\leq\mathrm{K}_{2}$} are uniformly bounded positive integers, and {\small$\mathrm{c}_{\n_{1}},\mathrm{c}_{\n_{2}}=\mathrm{O}(1)$} are deterministic.
\item The functions {\small$\mathfrak{q}_{\n}$} are admissible in the sense of Definition (definition:admissible of the paper).
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:55:27.257972+00:00","domain":"probability theory","id":"claim_de4fdd829860a83309fe373fa82abe65c5fb509cc35300f9ab2f8b7f1dbca853","kind":"theorem","schema_version":1,"statement":"[Proposition prop:3 of arXiv:2410.23250, 'Strict inequalities for arm exponents in planar percolation'] Fix $t\in [0,1/2]$.   Let $A,B,S,T\subset[n]$ pairwise disjoint. Let $F,G:\{0,1\}^n\times\{0,1\}^n\to \mathbb R$ such that
  \begin{itemize}
  \item $F(\omega,\omega_t)$ is  measurable w.r.t.\@ $\{(\omega(x),\omega_t(x))\:: \: x\in A\cup S\cup T\}$, 
  \item  $G(\omega,\omega_t)$ is measurable w.r.t.\@ $\{(\omega(x),\omega_t(x))\:: \: x\in B\cup S\cup T\}$,
  \item $F,G$ are both $S$-increasing and $T$-decreasing.
  \end{itemize}
  Then for every $t\in [0,1/2]$
  \begin{equation}
        \mathbb E[F(\omega,\omega_t)G(\omega,\omega_t)]\ge\mathbb E[F(\omega,\omega_t)]\mathbb E[G(\omega,\omega_t)]
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:41:28.184892+00:00","domain":"probability theory","id":"claim_de54a22625a8087184cbbe500070893a6e168ea9092d730ee59a1dc0cca19560","kind":"lemma","schema_version":1,"statement":"[Lemma lem:RelaxationTimeInduced of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] We can bound the relaxation time $t_{\textup{rel}}^{\textup{ind},+}$ of the additive reversibilisation $\mathbf{X}^{\textup{ind},+}$ of the induced chain $\mathbf{X}^{\textup{ind}}$ by
