		\item $\operatorname{div} F\in L_1$ for $d\geq 3$,
		\item $\Lambda^\epsilon \operatorname{div} F\in L_1$ for some $\epsilon>0$ for $d=2$,
	\end{itemize}
	then $F^{\mathsf{sol}}:= F - \nabla P*\operatorname{div} F$ is divergence-free and we define 
	\begin{gather}
		F^{\mathsf{irr}}:=\nabla P*\operatorname{div} F 
		\quad\text{and}\quad
		F^{\mathsf{sol}}:= F-\nabla P*\operatorname{div} F.
	\end{gather}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.064922+00:00","domain":"probability theory","id":"claim_e0a62c8f9c798e63a4931c3bf3823e3bca31f5d1fb46e9740ffe39cf175bbc82","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2606.00586, 'Stein's Method for Convergence Rates of Invariant Measures in the Nonlocal-to-Local Limit'] Suppose $b$ satisfies \eqref{eq:dispt}, then
