         where $C = \frac{f(0)}{f(1) + f(0)}.$
     \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.189274+00:00","domain":"probability theory","id":"claim_e0c0460e29e3c4a8548ef28c0695a1f9c5be58fdbfc7fb451167e0d154484209","kind":"concept","schema_version":1,"statement":"[Proposition 11 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] Let $p,q \geq 0$ and $\lambda,\gamma > 0$. Then, for $x,b \in [0,a]$, we have that
				\begin{align}
					&\mathbb{E}_x \Bigl(\ee^{-q T_{a,U}^{-,\lambda} - p\int^{T_{a,U}^{-,\lambda}}_0 \1_{\{U_s < b\}} \dd s} 1_{\left\{  T_{a,U}^{-,\lambda} < T_{b,U}^{+,\gamma} \right\}} \Bigr) =  \frac{\overline{z}_b^{(q+\lambda_p,\gamma-\lambda_p)}(x)  + \lambda \int^x_b \W^{(q+\gamma+\lambda)}(x-y)  \overline{z}_b^{(q+\lambda_p,\gamma-\lambda_p)}(y) \dd y }{\ee^{\varphi_{q+\gamma} a} \alpha_2^{(q+\gamma,q+\lambda_p)}(b) +  \lambda \int^a_b \Z^{(q+\gamma+\lambda)}(a-y,\varphi_{q+\gamma})\overline{z}_b^{(q+\lambda_p,\gamma-\lambda_p)}(y) \dd y}  \notag \\
					&\quad \times \Bigl( \lambda \int^b_0 \Bigl[ \ee^{\varphi_{q+\gamma} a} \alpha_1^{(q+\gamma,q+\lambda_p)}(b;u) +  \lambda \int^a_b \Z^{(q+\gamma+\lambda)}(a-y,\varphi_{q+\gamma})\overline{w}_b^{(q+\lambda_p,\gamma-\lambda_p)}(y;u) \dd y  \Bigr] \dd u \notag \\
					& \quad + \lambda \int^a_b \Z^{(q+\gamma+\lambda)}(a-u,\varphi_{q+\gamma}) \dd u \Bigr) -  \lambda \int^a_0 \Bigl(
					\overline{w}_b^{(q+\lambda_p,\gamma-\lambda_p)}(x;u) + \lambda \int^x_b \W^{(q+\gamma+\lambda)}(x-y)  \overline{w}_b^{(q+\lambda_p,\gamma-\lambda_p)}(y;u) \dd y \Bigr) \dd u , \notag




				\end{align}
				and 	
				\begin{align}
