{"assumptions":[],"created_at":"2026-10-28T01:41:54.364950+00:00","domain":"probability theory","id":"claim_e4aee0e65b15c836e3ad90a6376ede9d13c40a7076d0a09441057891c08297af","kind":"theorem","schema_version":1,"statement":"[Corollary cor:L of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let (asn:b of the paper) and (asn:sigma of the paper) hold. Let  $\chi\in\mathrm{Cut}_d$, $p\in[1,\infty)$, and let $X$ and $Y$ be two solutions to (equation eq:main of the paper). Then the map $f\mapsto\mathcal{J} f$ defined for $f\in\mathcal{C}^2({\mathbb{R}}^d; {\mathbb{R}}^d)$ by
    \begin{equ}
        (\mathcal{J} f )_t=\int_0^1\int_0^t\chi_{\rho}(X_r-Y_r)\nabla f\big(\theta X_r+(1-\theta)Y_r\big)\,dr\,d\theta
    \end{equ}
    extends as a continuous linear map from $\mathcal{C}^{\alpha+}({\mathbb{R}}^d; {\mathbb{R}}^d)$ to $\mathcal{C}^{1+(\alpha-1)H}([0,1]; L_p(\Omega; {\mathbb{R}}^{d\times d}))$, whose norm depends only on $\alpha,p,d,\lambda,H,\chi,\|\sigma\|_{\mathcal{C}^5},C^X_{D, p}, C^X_{S, 2p}, C^Y_{D,p}, C^Y_{S, 2p}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:40.047908+00:00","domain":"probability theory","id":"claim_e4b4b13ec23bfa0b26ee2ddad79300b40a43e5733cc22e6a83e4bd6b5a4686c4","kind":"concept","schema_version":1,"statement":"[Lem 2 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Let $u(x)=|x|^{\alpha-1}$ and $\alpha\in(1,2)$. For any $\eps >0$ and $\delta>1$, one can construct a smooth function $\pde$ such that:
\begin{itemize}
    \item[(i)] $\pde$ is supported on $\left[\eps\delta^{-1}, \eps\right]$ and satisfies $\int_{\eps\delta^{-1}}^{\eps} \pde(y) dy=1$, and is bounded by
    \begin{align*}
0\le \pde(x) \le 2(x \log \delta)^{-1}\quad \textrm{for~}x\in\left[\eps\delta^{-1}, \eps\right] .
\end{align*}
    \item[(ii)] The mollified function $u_{\delta,\eps} = u \ast \pde$ is of class $C^2$ and satisfies the following inequalities for all $x\in\real$:
    \begin{align}
        |x|^{\alpha-1} &\le \eps^{\alpha-1} + u_{\delta,\eps}(x),  \\
        u_{\delta,\eps}(x) &\le |x|^{\alpha-1} + \eps^{\alpha-1},  \\
        |u'_{\delta,\eps}(x)| &\le 2^{2-\alpha}(\alpha-1)|x|^{\alpha-2}\1_{[-2\eps,2\eps]^c}(x) + \frac{2^{3-\alpha}\delta(1-\delta^{-1})^{\alpha-1}}{\eps^{2-\alpha}\log \delta}\1_{[-2\eps,2\eps]}(x). 
    \end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.192715+00:00","domain":"probability theory","id":"claim_e4b987260e6282fd09b69f089ad0e2edfeedd501f076fd1b6d5f069aa2659014","kind":"concept","schema_version":1,"statement":"[Theorem 3 (Reduced \local\ for UGW trees) of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose Condition \ref{cond:UGW} holds. Let $\tree \sim \mathrm{UGW}(\rho_{\myroot})$, and let $X$ be as in \eqref{eq:GW}, and also let $(\bar{\tree},\Xbar)$ be as in Construction \ref{constr:UGWlocal}. 
Then for each $k \in \N_0$, we have
\begin{equation*}
\big((1_{\{v \in \tree\}},X_v[k])_{v \in \V_1}, \, |N_1(\tree))|\big) \stackrel{d}{=} \big((1_{\{v \in \bar{\tree}\}},\Xbar_v[k])_{v \in \V_1}, \, \Nhat(k)\big).
\end{equation*}
In particular, the $(\{0,1\} \times \PolishX^\infty)^{\V_1}$-valued random variables $(1_{\{v \in \tree\}},X_v)_{v \in \V_1}$ and $(1_{\{v \in \bar{\tree}\}},\Xbar_v)_{v \in \V_1}$ have the same law. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

