   \end{equation}
In view of the Gagliardo-Nirenberg inequality \eqref{Gagliardo-Nirenberg-inequality}, employing a standard density argument, we deduce the following inequality and Lemma
   \begin{equation}
      \lvert \bb_0(\bu,\bv,\bw) \rvert  \leq  C \lvert \bu \rvert_{\StokesH}^{1 -\frac d4} \lvert \nabla \bu \rvert_{\mathbb{L}^2}^{\frac d4} \lvert \bv \rvert_{\StokesH}^{1 - \frac d4} \lvert \nabla \bv \rvert_{\mathbb{L}^2}^{\frac d4} \lvert \nabla \bw \rvert_{\mathbb{L}^2}, \;\;\;\forall \bu,\,\bv,\,\bw \in \StokesV,
   \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:24.616677+00:00","domain":"probability theory","id":"claim_e7df4900f1056aa841a67d527c92abfae15d0c4c93f4e0a331dbf8ba5a8cb824","kind":"concept","schema_version":1,"statement":"[Lemma 17 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Let $a_n(t)$ be as in \eqref{E:1.24a} and set $\wt C_\star:=2c_\star\slb$ for~$c_\star$ as in Proposition~\ref{prop-3}. Then for all continuously differentiable $f\colon\R\to[0,\infty)$  with compact support, all natural $n\ge1$ and all real $t>0$ and $u>0$, the quantity $o(1)=o_{n,t,u}(1)$ defined implicitly by
