{"assumptions":[],"created_at":"2026-10-27T06:25:55.462655+00:00","domain":"probability theory","id":"claim_ea1e929a61acb2ed7de7ce248e50894d3e84008360dd54f64744419b016dad54","kind":"definition","schema_version":1,"statement":"[Defn 21 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A pair $(u^h,\nu^h)$ is called a kinetic solution of \eqref{eq:skeleton-obstacle-problem} with initial data $u^0$ and obstacle $\psi$ if the following conditions hold.
\begin{enumerate}[label=\textbf{\arabic*}.]
  \item For every $p\geq1$, $u^h\in L^\infty(0,T;L^p(\mathbb T^N))$ and
\begin{align*}
\underset{0\leq t\leq T}{{\rm{ess\,sup}}}\ \Vert u^h(t)\Vert ^p_{L^p(\mathbb{T}^N)} \leq C(p,\Vert h\Vert_{L^2(0,T;U)},T,D_0),
\end{align*}
\item  We have 
\begin{equation*}
u^h(x,t)\geq\psi(x,t),\qquad\text{for } \dd x\otimes\dd t\text{-a.e. } (x,t),
\end{equation*}
and $\nu^h$ is a nonnegative finite Radon measure on $\mathbb{T}^N\times[0,T)$.
\item  The function $u^h$ satisfies the weak initial trace condition
\begin{equation*}
\lim_{\tau\downarrow0}\frac{1}{\tau}\int_0^\tau\Vert u^h(t)-u^0\Vert _{L^1(\mathbb{T}^N)}\dd t=0.
\end{equation*}
\item There exists a (deterministic) kinetic measure $q^h$ such that, with $f:= \one_{\{u^h>\xi\}}$ and $\mu^h:=\delta_{u^h}$, for all $\varphi\in C^1_c(\mathbb{T}^N\times [0,T)\times \mathbb{R})$,
\begin{align}\notag
&\int^T_0\langle f(t), \partial_t \varphi(t)\rangle \dd t+\langle f^0, \varphi(0)\rangle +\int^T_0\langle f(t), a(\xi)\cdot \nabla \varphi (t)\rangle \dd t\\
&= -\sum_{k\geq 1}\int^T_0\int_{\mathbb{T}^N} \int_{\mathbb{R}}g_k(x,\xi)\varphi (x,t,\xi)h_k(t)\dd \mu^h_{x,t}(\xi)\dd x\dd t \\
&\quad + q^h(\partial_{\xi} \varphi)-\int_0^T\int_{\mathbb{T}^N}\varphi(x,t,\psi(x,t))\dd\nu^h(x,t),\nonumber
\end{align}
 where  $\mu^h_{x,t}(\dd\xi)=\delta_{u^h(x,t)}(\dd\xi)$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.780421+00:00","domain":"probability theory","id":"claim_ea20b3afc61c3997543acd3226a5770944e614b0c25af7e52c969829ea53c65a","kind":"concept","schema_version":1,"statement":"[Thm smasympexUN of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] There is a universal constant $C>0$, and a compactly supported 
distribution $\mu_k$ for every $k\in\mathbb{Z}_+$, such that the following 
hold. Fix any $h\in C^\infty(\mathbb{R})$, and let
$f(\theta):= h(K\cos\theta)$. Then
$$
	\left| \mathbf{E}[\mathop{\textnormal{tr}} h(X^N)]- \sum_{k=0}^{m-1} \frac{\mu_k(h)}{N^k} 
	\right| \leq 
	\frac{(C\tilde q_0)^m}{u^mN^m}
	\|f^{(m'+1)}\|_{[0,2\pi]} 
	+\frac{(C\tilde q_0)^{2m}}{m!\, u^{2m} N^m} 
	\|f^{(2m'+1)}\|_{[0,2\pi]} 
$$
for every $m, N\in \mathbb{N}$ and $u\in (0,1)$, where
$m':=\lceil (1+u)m\rceil$ and $\tilde q_0 := q_0(1+\log q_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.963392+00:00","domain":"probability theory","id":"claim_ea240042278f4b74096cea1e306dc2726a498c4e71f5f298e86098400fd25617","kind":"theorem","schema_version":1,"statement":"[Theorem thm:mass_ex_lvl_set of arXiv:2411.07113, '\begin{LARGE}On differentiability and mass distributions of topologically typical multivar'] Let $C$ be a $d$-dimensional Archimedean copula and $\gamma \in \mathcal{P}_{\mathcal{W}_d}$ its corresponding Williamson measure. Moreover, let $s_1,s_2 \in \mathbb{I}$, with $s_1 \leq s_2$. Then the following assertion holds:
    \begin{equation}
    \mu_C(L_{[s_1,s_2]}) = \gamma\left(\left[\frac{1}{\varphi(s_1)},\frac{1}{\varphi(s_2)}\right]\right).
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.569462+00:00","domain":"probability theory","id":"claim_ea2616f50cf3a5e3a4b89e50424300eb561c69db447cdec6610d4f0c8cd1040f","kind":"theorem","schema_version":1,"statement":"[Corollary cor.uniform-renewal of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let $\theta\in(0,1/4)$ and $\varepsilon>0$. There exist a $\mathbb{Q}$-full-probability event $\Omega_{\theta,\varepsilon}$ and a deterministic constant $C=C(\theta,\varepsilon,d,\Lambda,r_0)<\infty$ such that, for every $\omega\in\Omega_{\theta,\varepsilon}$, there exists a finite random scale $\lambda_0(\omega)>0$ with the property that for every $0<\lambda\le\lambda_0(\omega)$ and every $t\ge\lambda^{-2-\varepsilon}$,
		\begin{equation}
			E_0^{\lambda,\omega}|X^\lambda(t)-\ell(\lambda)t|\le C\sqrt t (\lambda^2 t)^\theta\, ,
		\end{equation}
		and
		\begin{equation}
			\widehat E_0^{\lambda,\omega}|A^\lambda(t)-\eta(\lambda)t|\le C\lambda^{-1}\sqrt t (\lambda^2 t)^\theta\, .
		\end{equation}
		Moreover, $\lambda_0$ has polynomial tails of every order: for each $p>0$ there is $C_p=C_p(p,\theta,\varepsilon,d,\Lambda,r_0)<\infty$ such that
		\begin{equation}
			\mathbb{Q}\bigl(\lambda_0\le 2^{-k}\bigr)\le C_p 2^{-pk}\qquad\text{for every integer }k\ge 0\, .
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:08.990387+00:00","domain":"probability theory","id":"claim_ea2d586236be4268f64cb9822311cc1b3a93a2cf5c531b5f64019f1e16e20380","kind":"lemma","schema_version":1,"statement":"[Lem lem_riemannPersistenceLowerBound of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] The persistence probability of a fractional L\'evy field $(X_H(\eta))_{\eta\in K}$ on the relatively compact set $K$ of a connected $d$-dimensional Riemannian manifold $\mathcal{M}$, where $O$ is in the interior of $K$, satisfies
    \begin{align*}
        \prob{\sup_{\eta\in K} X_H(\eta) < \varepsilon} \geq c ~ \varepsilon^{\frac{d}{H}} ~ \left(\sqrt{-\log \varepsilon}\right)^{-\frac{d}{H}}
    \end{align*}
    for some constant $c>0$ and all $\varepsilon>0$ small enough.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.425110+00:00","domain":"probability theory","id":"claim_ea2ecae92e1854dd9b3bd869435723771eefbd3a40621254806f8578aaa59ee5","kind":"lemma","schema_version":1,"statement":"[Lemma 162 of arXiv:2601.16377, '2601.16377'] Consider a uniformly random tiling of $A\times B\times C$ hexagon. Using the notations \eqref{eq_N_hexagon} and \eqref{eq_L_hexagon}, the $N$ horizontal lozenges on the vertical section at distance $\mathfrak{t}$ from the left border with coordinates $1\leq \ell_1<\ell_2<\dots<\ell_N\leq L$ have probability distribution
\begin{equation}

 \amsmathbb P_N(\ell_1,\ldots,\ell_N)=\frac{1}{\mathscr{Z}_N} \cdot \prod_{1 \leq i<j \leq N} (\ell_j-\ell_i)^2 \cdot \prod_{i=1}^N w(\ell_i),
\end{equation}
with the weight
\begin{equation}

w(\ell)=
 \left\{\begin{array}{lll}
  (\ell)_{C-\mathfrak{t}}\cdot (A+\mathfrak{t}+1-\ell)_{B-\mathfrak{t}}&& \textnormal{if}\,\,0 < \mathfrak{t}\leq \min(B,C),\\
  (\ell)_{C-\mathfrak{t}}\cdot (A+B+1-\ell)_{\mathfrak{t}-B} && \textnormal{if}\,\,B\leq \mathfrak{t}\leq C,\\
  (\ell)_{\mathfrak{t}-C}\cdot (A+C+1-\ell)_{B-\mathfrak{t}}&& \textnormal{if}\,\,C\leq \mathfrak{t}\leq B,\\
  (\ell)_{t-C}\cdot (A+B+C+1-\mathfrak{t}-\ell)_{\mathfrak{t}-B} && \textnormal{if}\,\, \max(B,C)\leq \mathfrak{t} < B+C,\end{array}\right.
\end{equation}
where $(a)_n$ is the Pochhammer symbol,
\[
(a)_n=a(a+1)\cdots (a+n-1)=\frac{\Gamma(a+n)}{\Gamma(a)},
\]
and $\mathscr{Z}_N$ is a normalizing
constant.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.937735+00:00","domain":"probability theory","id":"claim_ea2f0a6d7a067bdb7d620eaca11baec967c812904a6840e46068d6050daad3fb","kind":"lemma","schema_version":1,"statement":"[Lemma 20 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $X $ have density $f$ with respect to $\pi_{T}$ and $T=\E X.$ Then, $S(X) \sim f(\cdot + 1) \dd \pi_{T}$ and $\E S(X) = \frac{\E X^{2}}{T} - 1.$ Moreover,
