	\begin{split}
			&\mathbb{P}\Big( A_1\xleftrightarrow{\overline{\mathfrak{L}}^{D}[N,M]} ... \xleftrightarrow{\overline{\mathfrak{L}}^{D}[N,M]}   A_k \xleftrightarrow{\overline{\mathfrak{L}}^{D}[N,M]} \mathfrak{L}^{D}[N,M] \cup \mathscr{B}_j \mid \widehat{\mathsf{G}}^{D}[\omega_l; N,M] \Big)\\
		\le &	 (l+1)\mathbb{P}\big( A_1\xleftrightarrow{(D)} ... \xleftrightarrow{(D)} A_k \xleftrightarrow{(D)} \mathscr{B}_j \big).
	\end{split}
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:03.894143+00:00","domain":"probability theory","id":"claim_eb496f690e3f9c59352ad3849089a8ec41ec0ed5979052ea26c71bafa3b4f71a","kind":"lemma","schema_version":1,"statement":"[Lem 14 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Let \(Y_t\) be the Ornstein-Uhlenbeck process defined in~\eqref{OU_a0}, and let \(c>0\) be a fixed constant. Then for any \(0<T<\infty\) fixed it holds that
    \begin{multline*}
        \E_{\PP_y}\left[ 
        \exp\left\{
        c\int_0 ^T \Vert Y_s\Vert_2^2
        \,ds
        \right\}
        \right]
        = 
        \left(
        \frac{\sqrt{a_0^2-c}}{a_0\sinh(2\sqrt{a_0^2-
        c}T)+\sqrt{a_0^2-c}\cosh(2\sqrt{a_0^2-c}T)}
        \right)^{d/2}
        \\\exp\left\{
