{"assumptions":[],"created_at":"2026-10-26T20:58:53.188371+00:00","domain":"probability theory","id":"claim_ec32499cfa9c08f405404a5bc8782797e1168a197257731c394bd90deeef7e8c","kind":"concept","schema_version":1,"statement":"[Lemma 2 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] Let $0 \leq b \leq a$, $q \geq 0$ and $0 < \lambda < \infty$. Then the following identities hold:
			\begin{enumerate}
				\item[\upshape{(i)}] For $ x \in [b,a]$ and $ y \in [b,\infty)$,
				\begin{equation}
					\E_x\Bigl( \int^\infty_0 e^{-q t} \1_{\{Y_t \in \dd y, \; t < T_{a,Y}^{+,\lambda} \wedge \tau_{b,Y}^- \}} \dd t \Bigr) = \Bigl( \frac{\W^{(q)}(x-b)}{\Z^{(q)}(a-b, \varphi_{q+\lambda})} \Z^{(q)}(a-y, \varphi_{q+\lambda}) - \W^{(q)}(x-y)\Bigr) \dd y, 
				\end{equation}
				and, consequently, for $ y \in (a,\infty)$,	
				\begin{equation}
					\E_x\bigl( \ee^{-q T_{a,Y}^{+,\lambda}} \1_{\{Y_{T_{a,Y}^{+,\lambda}} \in \dd y, \; T_{a,Y}^{+,\lambda} < \tau_{b,Y}^-\}} \bigr) = \lambda \frac{\W^{(q)}(x-b)}{\Z^{(q)}(a-b,\varphi_{q+\lambda})} \ee^{\varphi_{q+\lambda}(a-y)} \dd y.  
				\end{equation}

				\item [\upshape{(ii)}] For $ x,y \in [b,\infty)$,	
				\begin{equation}
					\E_x \Bigl( \int^\infty_0 \ee^{-q t} \1_{\{Y_t \in \dd y, \; t < T_{a,Y}^{-,\lambda} \wedge \tau_{b,Y}^- \}} \dd t \Bigr) = \Bigl(\frac{\Z^{(q+\lambda)}(a-y, \varphi_{q})}{\Z^{(q+\lambda)}(a-b, \varphi_{q})} \W^{(q+\lambda)}(x-b) - \W^{(q+\lambda)}(x-y) \Bigr) \dd y, 
				\end{equation}
				and consequently, for $y \in (b,a)$,
				\begin{equation}
					\E_x \Bigl( \ee^{-q T_{a,Y}^{-,\lambda}} \1_{\{Y_{T_{a,Y}^{-,\lambda}} \in \dd y,\; T_{a,Y}^{-,\lambda} < \tau_{b,Y}^- \}} \Bigr) = \lambda \Bigl(\frac{\Z^{(q+\lambda)}(a-y, \varphi_{q})}{\Z^{(q+\lambda)}(a-b, \varphi_{q})} \W^{(q+\lambda)}(x-b) - \W^{(q+\lambda)}(x-y) \Bigr) \dd y. 
				\end{equation}
			\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:59:24.050890+00:00","domain":"probability theory","id":"claim_ec3617b789f335e9d72b66549d5ba5ddd6f9860daf60dfacc1d6ddea432d3a58","kind":"theorem","schema_version":1,"statement":"[Proposition prop:coordinate-crossing of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] For $N\ge3$, the first three Ritz levels are
\begin{equation}
 \Lambda_1(N)=2N,
 \qquad
 \Lambda_2(N)=3N-\sqrt{N^2+8N-8}.
\end{equation}
Set
\begin{equation}
 R_N:=\sqrt{N^2+11N-20},
 \qquad
 \phi_N:=\frac13\arccos\!\left(
 \frac{3\sqrt3\,N(7N-16)}{2R_N^3}\right).
\end{equation}
Then
\begin{equation}
 \Lambda_3(N)
 =4N+\frac{4R_N}{\sqrt3}
 \cos\!\left(\phi_N+\frac{2\pi}{3}\right).
\end{equation}
Equivalently, $\Lambda_3(N)$ is the smallest zero of
\begin{equation}
 \lambda^3-12N\lambda^2
 +(44N^2-44N+80)\lambda
 -48N^3+120N^2-192N=0.
\end{equation}
Moreover,
\begin{equation}
 \Lambda_2(N)<2N\qquad(N\ge3),
\end{equation}
and the first crossings of the continuum coefficient along this ladder are
\begin{align}
 \Lambda_1(N)&<A_N &&(N\ge12),\\
 \Lambda_2(10)&>A_{10},\qquad
 \Lambda_2(N)<A_N &&(N\ge11),\\
 \Lambda_3(10)&<A_{10}.
\end{align}
Consequently,
\begin{equation}
 C(N)\le\Lambda_2(N)<\min\{A_N,2N\}
 \qquad(N\ge11),
\end{equation}
and $C(10)<A_{10}$ follows from the third level.  Finally,
\begin{equation}
 \Lambda_3(N)
 =2N-4-\frac6N+\frac{51}{N^2}+O(N^{-3})
 \qquad(N\to\infty).
\end{equation}","status":"unverified"}

