     \begin{align}
          \int_D \dfrac{1}{d_{\partial D}^2}\left\vert\dfrac{\varphi}{\mathbf{M}}\right\vert^2 \mathbf{M}dr \le C_H \Vert \varphi\Vert^2_{H^1_\mathbf{M}}.
       \end{align}
        \item The following inclusions hold: $L^2_\mathbf{M} \subset L^2(D)$ and $H^1_\mathbf{M}\subset H^1_0(D).$

     \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.143501+00:00","domain":"probability theory","id":"claim_edc3712e427717239231ab5e80d446145f55535eee23202c7b8ca5c3402b78cb","kind":"concept","schema_version":1,"statement":"[Thm informal of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] Let $z \in \mathbb{R}^d$, $x \in \mathbb{R}^n \setminus \{0\}$, $A, B_i \in \mathbb{R}^{n \times n}$,
    \begin{equation}
           \begin{aligned}
                dz^\epsilon(t) &= -\epsilon z^\epsilon(t)\,dt + \sqrt{\epsilon}\,dW_t \\
                dx^\epsilon(t) &= \Big(A + \sum_{i=1}^d B_i z_i^\epsilon(t)\Bigr)x^\epsilon(t)\,dt \eqqcolon A(z^\epsilon(t))x^\epsilon(t)\,dt \,,
            \end{aligned}
    \end{equation}
    and $\lambda^\epsilon \coloneqq \lim_{t \to \infty} t^{-1}\ln \|x^\epsilon(t)\|$. Let $Z$ be distributed 
    according to the law of the invariant measure of $z^\epsilon(t)$ (which is independent of $\epsilon$). Then, provided
    that (equation eq:intro-eq of the paper) satisfies a weak non-degeneracy condition on $\mathbb{R}^d \times (\mathbb{R}^n \setminus \{0\})$, we have
    $$\lim_{\epsilon \to 0} \lambda^\epsilon = \mathbb{E}[\lambda(A(Z))] \,.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:53:00.823353+00:00","domain":"probability theory","id":"claim_edcacec64425d380334146c73c294577c0c56c0b69ecd0c2be5e640162094702","kind":"definition","schema_version":1,"statement":"[Definition Def: operations binary trees1 of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Let $\rho\in{\mathcal T}_b$. We define the family of binary trees ${\mathcal R}^-(\rho)\subset{\mathcal T}_b$ obtained from $\rho$ by the following algorithm. For any effective cherry of $\rho$:
		\begin{enumerate}
			\item we contract the effective cherry to its parent vertex;
			\item if the effective cherry contains two leaves, after contraction it becomes a new leaf which inherits the rightmost decoration of the pair;
			\item if, instead, the effective cherry contains only one leaf grafted from the left on the root, after contraction the new vertex is not a leaf and does not require any decoration. 
