{"assumptions":[],"created_at":"2026-10-27T05:44:28.093969+00:00","domain":"probability theory","id":"claim_eef9f2b32bad49c040607611155a7df1ea4863b34c530340cdfbe05b654e5889","kind":"concept","schema_version":1,"statement":"[Lemm 31 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Consider the {\bf deterministic} flow $\left( ({\eta}_t^{\mathbf{y}})_{t\in [0,T]}\right)_{\mathbf{y}\in E^{*,K}}$ that satisfies conditions {\fbox{\bf C1}}--{\fbox{\bf C2}}, and in addition, $\sup_{0\leq t\leq T}\|{\eta}_t^{\mathbf{y}}-{\eta}_t^{\mathbf{y}'}\|_{2,-(3+\delta)}\leq C_T|\mathbf{y}-\mathbf{y}'|$, for any $\mathbf{y},\mathbf{y}' \in E^{*,M}$. Equivalently, $\sup_{0\leq t\leq T}\|{\eta}_t^{\mathbf{y}^{*}}-{\eta}_t^{\mathbf{y}^{*'}}\|_{2,-(3+\delta)}\leq C_T|\mathbf{y}-\mathbf{y}'|$, for any $\mathbf{y},\mathbf{y}' \in E^{K}.$  Let $\Upsilon$ be a test function with non-negative value in $\mathcal{C}_0^{\infty}(E^K)$ and $(z_t)_{t\in [0,T]}$ be a continuous path with values in $\mathcal{H}^2_{\mathrm{Sym}}(\mathbb{S})\cap \mathcal{U}^2(\mathbb{S}) $. Then, the process $(\langle \tilde{\eta}_t^{\Upsilon,(u,\vartheta)},\mathrm{e}^{\epsilon \Delta} z_t\rangle)_{t\in [0,T]}$ is non-decreasing in time and one has
    \begin{align}
        \int_{E^M}\Bigg( \int_0^T \Upsilon(\mathbf{y}_t(u,-\vartheta))\mathrm{d}\left\langle \eta_t^{y^{*}},\mathrm{e}^{\epsilon \Delta}z_t\right\rangle\Bigg)\mathrm{d}y = \int_0^T \mathrm{d}\left\langle \tilde\eta_t^{\Upsilon,(v,\vartheta)},\mathrm{e}^{\epsilon \Delta}{z}_t\right\rangle, \quad t\in [0,T].
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.259037+00:00","domain":"probability theory","id":"claim_eefea7caaab767de4d4abe008840a80260a03af8fec6627d98904433ec8c8022","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] If the following two conditions hold for some $m\in\N$ and $\zeta,\eta\in [\frac{1}{2},\infty[^{d\times m}$, then~\eqref{co:4} is satisfied:
\begin{enumerate}[(i)]
\item There is a measurable and locally square-integrable map $g\colon\R_{+}\rightarrow\R^{d\times m}$ such that $|f_{i}(\cdot,x,y)| \leq |\sum_{j=1}^{m} g_{i,j} x^{\zeta_{i,j}}y^{\eta_{i,j}}|$ for all $i\in\{1,\dots,d\}$ and $x,y\geq 0$.

\item Each $\nu\in\mathcal{P}_{0}(\R)$ satisfies
\begin{align*}
\max_{x\in [0,N]} \frac{1}{2}\sum_{i=1}^{d}\sum_{\substack{j_{1},j_{2}=1,\\ \zeta_{i,j_{1}} + \zeta_{i,j_{2}} < 2}}^{m}g_{i,j_{1}}g_{i,j_{2}}x^{\zeta_{i,j_{1}} + \zeta_{i,j_{2}} - 1}(N-x)^{\eta_{i,j_{1}} + \eta_{i,j_{2}}} &\leq b_{0}(\cdot,N,\nu),\\
\max_{x\in [0,N]}\frac{1}{2}\sum_{i=1}^{d}\sum_{\substack{j_{1},j_{2}=1,\\ \eta_{i,j_{1}} + \eta_{i,j_{2}} < 2}}^{m} g_{i,j_{1}}g_{i,j_{2}} (N-x)^{\zeta_{i,j_{1}} + \zeta_{i,j_{2}}}x^{\eta_{i,j_{1}} + \eta_{i,j_{2}} - 1} &\leq \dot{N} - \sum_{i=0}^{k}b_{i}(\cdot,N,\nu)N^{i}.
\end{align*}
\end{enumerate}","status":"unverified"}

