{"assumptions":[],"created_at":"2026-10-27T14:13:22.515686+00:00","domain":"probability theory","id":"claim_f16e4fe542dd64b82b60ffd13122dabac72322a57efbc5edb39fff6b3779ad67","kind":"concept","schema_version":1,"statement":"[Thm CM results kappa>0 of arXiv:2505.16093, 'Multiple chordal SLE($\kappa$) and quantum Calogero-Moser system'] The multiple chordal SLE($\kappa$) is described by the partition function $\mathcal{Z}(\boldsymbol{x})$, we have
\begin{equation}
\mathcal{L}_j \mathcal{Z}(\boldsymbol{x})= h \mathcal{Z}(\boldsymbol{x})   
\end{equation}
where $\mathcal{L}_j$ is the null vector differential operator:
\begin{equation}
\mathcal{L}_j=  \frac{\kappa}{2}\left(\frac{\partial}{\partial x_j}\right)^2 +\sum_{k \neq j}\left( \left(\frac{2}{x_k-x_j}\right) \frac{\partial}{\partial x_k}-\frac{6-\kappa}{\kappa}\frac{1}{\left(x_k-x_j\right)^2}\right)  
\end{equation}

\begin{itemize}


\item[(i)] We transform the partition function $\mathcal{Z}(\boldsymbol{x})$ into an eigenfunction of quantum Calogero-Moser system by multiplying Coulomb gas correlation $\Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{x})$ 

\begin{equation}
\tilde{\mathcal{Z}}(\boldsymbol{x})=\Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{x})\mathcal{Z}(\boldsymbol{x})   
\end{equation}

where $$\Phi_{r}(\boldsymbol{x})=\prod_{1 \leq j<k \leq n}\left(x_j-x_k\right)^{-2r}$$

 Then $\tilde{\mathcal{Z}}(\boldsymbol{x})$ satisfies 
 $$\left(\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}\right)  \tilde{\mathcal{Z}}(\boldsymbol{x}) = h\tilde{\mathcal{Z}}(\boldsymbol{x})$$  where the differential operator $\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}$ is given by

\begin{equation}
\begin{aligned}
\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}= & \frac{\kappa}{2} \partial_j^2- F_j \partial_j+\frac{1}{2\kappa} F_j^2-\frac{1}{2} F_j^{\prime} -\sum_{k \neq j}\left(f_{j k}\left(\partial_k-\frac{1}{\kappa} F_k\right)-\frac{6-\kappa}{2\kappa} f_{j k}^{\prime}\right) \\
&=\frac{\kappa}{2} \partial_j^2- \sum_{k} f_{jk}(\partial_j+\partial_k)\\
&-\frac{1}{\kappa}\left[\sum_k \sum_{l \neq k} f_{j k} f_{j l}-2\sum_{k\neq j} f_{j k}^2\right]- F_{j}'
\end{aligned}   
\end{equation}

 The sum of the null vector differential operators $\mathcal{L}=\sum \mathcal{L}_j$ is given by
\begin{equation}
\Phi_{-\frac{1}{\kappa}} \cdot \mathcal{L} \cdot \Phi_{\frac{1}{\kappa}}=\kappa H_n\left(\frac{8}{\kappa}\right)
\end{equation}

where $H_{n}(\beta)$ with $\beta=\frac{8}{\kappa}$ is  the quantum Calogero-Moser Hamiltonian
$$H_n(\beta)=\sum_{j=1}^n \frac{1}{2} \frac{\partial^2}{\partial x_j^2}-\frac{\beta(\beta-2)}{16} \sum_{1 \leq j<k \leq n} \frac{1}{\sin ^2\left(\frac{x_j-x_k}{2}\right)}
$$
\item[(ii)]
The commutation relation between growing two SLEs can be expressed as
$$[\mathcal{L}_j,\mathcal{L}_k]= \frac{1}{\sin^2(\frac{x_j-x_k}{2})}(\mathcal{L}_k-\mathcal{L}_j)$$
\end{itemize}
then
$$[\mathcal{L}_j,\mathcal{L}_k]\mathcal{Z}(\boldsymbol{x})= \frac{1}{\sin^2(\frac{x_j-x_k}{2})}(\mathcal{L}_k-\mathcal{L}_j)\mathcal{Z}(\boldsymbol{x})=0$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:21:45.321292+00:00","domain":"probability theory","id":"claim_f17b935053b6f9062e343719abe7d699f259693077fd30d32af0ad8de51d3bd9","kind":"theorem","schema_version":1,"statement":"[Theorem 5 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Let $\mathcal{X}(t)$, $t \geq0$, be a stochastic process in $\RR^d$ with $\mathcal{X}(0) =0$, with stationary and independent increments. Assume that for some linear operator $E$ one has $\mathcal{X}(ct)\stackrel{\text{d}}{=} c^E\mathcal{X}(t)$, for all $t>0$, and that the law of $\mathcal{X}(1)$ is full. Let $X_n$, $n\in\NN$, be a sequence of r.v.'s in $\mathbb{R}^d$, in the domain of attraction of some full operator stable law as in \eqref{defopstable}, with $b_n=0$, $n\in \NN$, and with $Y \stackrel{\text{d}}{=}\mathcal{X}(1)$. Then there exists a regularly varying function $B$ with operator $-E$ such that
		\begin{align}
			B(n) \sum_{i=1}^n X_i \to \mathcal{X}(1),\quad \text{as $n\to+\infty,$}  
		\end{align}
		in distribution.
		Furthermore, as $c \to +\infty$,
		\begin{align}
			B([c]) \sum_{i=1}^{[ct]} X_i \to  \mathcal{X}(t)
		\end{align}
		and the convergence holds both in the sense of all finite-dimensional distributions and weakly on $D([0, +\infty), \mathbb{R}^d)$ with the $J$ topology.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.237497+00:00","domain":"probability theory","id":"claim_f1826b598c2d74ba3591b8a2c80af756d41f1072c8f4a501750e3af5efef288b","kind":"theorem","schema_version":1,"statement":"[Corollary 40 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(k\) be a perfect field and let
  \begin{equation*}
    S \defeq \bracketlr{\setA^1_k/\setG_{m,k}}^n.
  \end{equation*}
  This admits a \(\delta\)-lifting
  \begin{equation*}
    S_{W(k)} \defeq \bracketlr{\setA^1_{W(k)}/\setG_{m,W(k)}}^n
  \end{equation*}
  over \(W(k)\) with Frobenius lift given on the standard coordinates by
  \begin{equation*}
    t_i  \mapsto  t_i^p, \qquad u_i  \mapsto  u_i^p.
  \end{equation*}
  Then, for every integer \(r \geq 1\), there exists a morphism
  \begin{equation*}
    s'_r \colon W_rS_{\setF_p} \to S
  \end{equation*}
  and a commutative diagram
  \begin{equation*}
    \begin{tikzcd}
    W_rS_{\setF_p} \arrow[d, "s'_r"'] \arrow[rd, "\sigma_{S,r}"] &         \\
    S \arrow[r, "\pi_S"']                                  & S^{\dR}
    \end{tikzcd}
  \end{equation*}
  of \(\setF_p\)-stacks, where \(\pi_S \colon S \to S^{\dR}\) is the natural morphism given in \Cref{DefdeRhamStack} and \(\sigma_{S,r} \colon W_rS_{\setF_p} \to S^{\dR}\) is the morphism obtained by \cite{petrov2025Decomposition}*{Corollary~4.4} (\Cref{ConstPetrov}).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.256564+00:00","domain":"probability theory","id":"claim_f18329e36c5ace910660e843fdad88e5ef630e1c032c6bf505bed8f2f86b614c","kind":"lemma","schema_version":1,"statement":"[Lem 51 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For any $f,\psi,\varphi\in\BL^{\kappa},x,y,x_n,y_n\in M$ and a non-empty subset $A\subseteq M$,
