\end{multline*}
For $n\geq 2$ even,
\begin{multline*}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
=
\\
\sum_{j=0}^{+\infty}
\Big(
\Big(
\sum_{0\leq k< \lfloor n/2\rfloor}
