{"assumptions":[],"created_at":"2026-10-26T20:53:11.422701+00:00","domain":"probability theory","id":"claim_f3f76694e1e4041b219cec51dc96b5ce1a9b526f944ddf20b5650936d2655ae1","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2606.09121, 'Truncated Signature Information for Mixed Fractional Brownian Paths'] Let
