{"assumptions":[],"created_at":"2026-10-27T14:09:34.498611+00:00","domain":"probability theory","id":"claim_f412aca5c1992934dd22af9108f14e94cf7e45fc5c39baa4f94437a29d2bb7b8","kind":"concept","schema_version":1,"statement":"[Thm Coulomb gas integral screening of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] \begin{itemize}
\item[(i)] If we choose 
$\sigma_j = a = \sqrt{\frac{2}{\kappa}}$, and $\lambda_j = \frac{a^2}{2} - ab = \frac{6 - \kappa}{2\kappa}$ for $1 \leq j \leq n$, and $\lambda_j = \frac{\sigma_j^2}{2} - \sigma_j b$ for $n+1 \leq j \leq n+2$, then we obtain the following null vector equation:

\begin{equation} 
\begin{aligned}
&\left[\frac{\kappa}{4} \partial_j^2 + \sum_{k \neq j}^{n} \left( \frac{\partial_k}{z_k - z_j} - \frac{(6 - \kappa) / 2\kappa}{(z_k - z_j)^2} \right) + \frac{\partial_{n+1}}{z_{n+1} - z_j} \right. \\
& \left. + \frac{\partial_{n+2}}{z_{n+2} - z_j} - \frac{\lambda_{n+1}}{(z_{n+1} - z_j)^2} - \frac{\lambda_{n+2}}{(z_{n+2} - z_j)^2} \right] \Phi \\
= &\sum_{k=n+3}^{n+2+m} \partial_k \left( -\frac{\Phi(z_1, \ldots, z_{n+m+2})}{z_k - z_j} \right)
\end{aligned}
\end{equation}

for all $j \in \{1, 2, \ldots, n\}$. Thus, we attain the desired form ((desired form of the paper)) for all $j \in \{1, 2, \ldots, n\}$.

Currently, the number of screening charges $m$ and the values of $\sigma_k = 2a$ or $\sigma_k = 2(a + b)$ for $k \in \{n+3, n+4, \ldots, n+m+2\}$ remain unspecified. The charges $\sigma_{n+1} = \overline{\sigma_{n+2}}$ are chosen such that $\boldsymbol{\sigma} = \sum_j \sigma_j \cdot z_j$ satisfies the neutrality condition ($NC_b$).

\item[(ii)] If $n = 2k$, $m = k - 1$, and we choose $\sigma_j = a$ for all $j \in \{1, 2, \ldots, n-1\}$, $\sigma_n = 2b - a$, and the sign of $\sigma_k = -2a$ for all $k \in \{n+1, n+2, \ldots, n+m\}$, then we have the following null vector equation for $j \in \{1, 2, \ldots, n-1\}$:

\begin{equation} 
\begin{aligned}
&\left[\frac{\kappa}{4} \partial_n^2 + \sum_{k=1}^{n-1} \left( \frac{\partial_k}{z_k - z_n} - \frac{(6 - \kappa) / 2\kappa}{(z_k - z_n)^2} \right) \right] \Phi \\
= &\sum_{k=n+1}^{n+m-1} \partial_k \left( -\frac{\Phi(z_1, \ldots, z_{n+m})}{z_k - z_n} \right) \\
&+ \frac{1}{2} \sum_{k=n+1}^{n+m-1} \partial_k \left[ \frac{8 - \kappa}{z_k - z_n} \left( \prod_{s=1}^{n-1} \frac{z_k - z_s}{z_n - z_s} \prod_{\substack{t=n+1 \\ t \neq k}}^{n+m} \left( \frac{z_n - z_t}{z_k - z_t} \right)^2 \right) \Phi \right].
\end{aligned}
\end{equation}

Since the right-hand side of ((null vector equation at 2b-a of the paper)) consists of derivatives with respect to $z_k$ for $k \in \{n+1, n+2, \ldots, n+m\}$, we obtain the desired form ((desired form of the paper)) for $j = n$ as well. Therefore, the null vector equations are satisfied for all $1 \leq j \leq n$.

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:01:56.355880+00:00","domain":"probability theory","id":"claim_f415c73742c065b08772c1963c69b7f4b423a3cd715daca3073ff4145d18ac6d","kind":"definition","schema_version":1,"statement":"[Definition def:Walpha of arXiv:2609.00794, 'On operators whose adjoints or second adjoints attain their norms'] Given $\alpha \in S_{\ell_1}$, the space $W_{\alpha}$ is defined as the hyperplane of $c$ given by $W_\alpha=\ker(\Phi(\alpha)) \subseteq c$, that is,
\begin{equation*}
W_{\alpha} = \{x \in c\colon \Phi(\alpha)(x) = 0\} = \left\{ x \in c\colon \alpha_1 \lim_n x_n + \sum_{k=1}^{\infty} \alpha_{k+1} x_k = 0 \right\},
\end{equation*}
where $\Phi\colon \ell_1 \rightarrow c^*$ is the canonical isometry given by 
	\begin{equation}
	\Phi(g)(x) = g_1 \lim_n x_n + \sum_{k=1}^{\infty} g_{k+1} x_k
	\end{equation}
	for every $g=(g_n) \in \ell_1$ and $x=(x_n) \in c$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.432158+00:00","domain":"probability theory","id":"claim_f4171d862bad75a6c107b878e884f5cedb5aca949ed48fb06fa1802e7c036aca","kind":"lemma","schema_version":1,"statement":"[Lemma eq:Jrr of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:kernel_connection_estimate}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$.

    Let $\delta>0$ and $c > 0$ be such that $\#S(r)\leq c r^{d-\delta}$ for all $r \in \mathbf{N}$. 

    Then there exists $C = C(G,J) > 0$ such that for all $r \in \mathbf{N}$,

    \begin{equation}

        J(B(r), B(r)^{c})
        \leq 
        C
        r^{
        \max
        \left(
            d(2-\alpha),
            d - 1
        \right)  
        + 
        1
        -
        \delta
        }
        \log(r)^{
            \mathbf{1}
            \left(
                \alpha=1+1/d
            \right)
        }.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:38:57.120244+00:00","domain":"probability theory","id":"claim_f4184187672fbbb17d58521f5932fe29c3a6531b3ac1e13e057f2219542a8369","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.04848, '\bf Addendum to:\\ Bounds for survival probabilities in \\ supercritical Galton-Watson pro'] For every $r\ge2$ and every $\ze\in(0,1)$, the pgfs $\varphiNB$ and $\varphiFL$ satisfy
\begin{linenomath}\begin{equation}
	\varphiFL(x;\pNB,\rNB) \le \varphiNB\Bigl(x;r,\frac{\ze(1-\ze^r)}{1-\ze^{r+1}}\Bigr) \;\text{ for every }x\in[0,1]\,.
\end{equation}\end{linenomath}
Equality holds if and only if $x = \PinfNB$ or $x=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.591903+00:00","domain":"probability theory","id":"claim_f41def8eda409753f0477f5c230889e91830301fe18bfc2a8d89b97fe26c11ff","kind":"concept","schema_version":1,"statement":"[Thma 2 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\pi_0$ be a fixed cuspidal representation for $\PGL_n(F)$ that is unramified at every finite place and tempered at all archimedean places.

		Let $\q=\prod_v \p_v^{r_v}$ be an integral ideal coprime to the different ideal of $F$ such that $N(\q)\to \infty$ and let $(C_v)_{v\mid \infty}$ be a collection of fixed real numbers satisfying $C_v\geq 1$. Then there exists a spectral weight function $\H=\H_\q$ implicitly depending on $\pi_0$ and $(C_v)_v$ defined on the generic automorphic representations for $\PGL_n(F)$, factorizing as
		\begin{equation*}
			\H(\pi)=\prod_{v<\infty}H_v(\pi_v)\prod_{v\mid\infty}h_v(\pi_v),\quad \pi=\otimes'_v\pi_v,
		\end{equation*}
		satisfying the following properties:
		\begin{itemize}
			\item if $v<\infty$ and $c(\pi_v)>r_v$ then $H_v(\pi_v)=0$;
			\item if $v<\infty$ and $c(\pi_v)\le r_v$ then $H_v(\pi_v)\geq 1$ with equality when $r_v=0$; 
			\item if $v\mid\infty$ and $C(\pi_v)\leq C_v$ then $h_v(\pi_v) \gg_{C_v} 1$;
			\item if $v\mid\q$ then $\int_{\gen}H_v(\pi_v)\, d\mu_{\loc}\pi_v\asymp \mathrm{vol}^{-1}\left(K_0\left(\p_v^{r_v}\right)\right)$;
		\end{itemize}
		such that we have








		\begin{multline*}
			\int_{\mathrm{gen}} \frac{|L(1/2,\pi_0\otimes \tilde{\pi})|^2}{\ell(\pi)}\H(\pi)\,d\mu_{\mathrm{aut}}(\pi)\\
			=\Delta^{\mu}\vol(K_0(\q))^{-1}\left(L(1,\pi_0,\mathrm{Ad})\frac{n\zeta^\ast(1)\zeta(\frac{n}{2})^2}{\zeta(n)}\log N(\q)+B_\q\right.\\
			\left.+N(\q)^{-\frac{n-2}2}\frac{\zeta_\q(\frac{n}{2})}{\zeta_\q(1)}\left(C\log N(\q)+D_\q\right)+O_{F,\pi_0,\epsilon}\left(N(\q)^{-\frac{n-1}{2}+\vartheta+\epsilon}\right)\right),
		\end{multline*}
		where $0\le\vartheta<\frac{7}{64}$ is a bound towards the generalized Ramanujan conjecture and $\mu$ is a constant depending only on $n$. Here $B_\q$ and $D_\q$ are explicit $\q$-dependent constants, given by \eqref{eq:def-Bq} and \eqref{eq:def-Dq}, respectively, and are $O_{F,\pi_0}(1)$; and $C$ is a $\q$-independent constant. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:47:12.025679+00:00","domain":"probability theory","id":"claim_f42118052d323c6216e50995544c7b3db420c7cc3da829f816d1f18be92cffc1","kind":"concept","schema_version":1,"statement":"[Theo thm:main of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] Let $ \alpha \in (0,1/2)$. Under the $ C^0$-norm, the local order of the Wiener measure $W$ satisfies 
    \begin{equation*}
