{"assumptions":[],"created_at":"2026-10-26T19:25:12.195777+00:00","domain":"probability theory","id":"claim_f78ea6a34cd3ac32505649dc5fcac8574d4817504af97dab3e54a23a36cd0790","kind":"concept","schema_version":1,"statement":"[Lem 21 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For all $K \geq (\oC_{\mu}+\varepsilon) \log N$, $t>0$, and $\p \in [k]_0$, there exists $\delta=\delta(\mu,\varepsilon)>0$ and two sequence sets $\cS_{\p}^{\for}$ and $\cS_{\p}^{\back}$ such that the following holds.
        \begin{itemize}
            \item[\emph{(a)}] The sequence sets $\cS_{\p}^{\for}$ and $\cS_{\p}^{\back}$ are typical, i.e.
            \[
            \P(S_K \in \cS_{\p}^{\for}) \geq 1- \exp(-N^{\delta}), \quad \P(S_K \in \cS_{\p}^{\back}) \geq 1- \exp(-N^{\delta}).
            \]
            \item[\emph{(b)}] The truncated exponential moment of number of shared edges is small: both of the inequalities
            \begin{equation} 

            \begin{aligned}
                \E(e^{t|E_{\for}^\p(G,G')|}\cdot 1_{S_K,S_K' \in \cS_{\p}^{\for}}) &\leq 1+ O(N^{-\delta}),\\ \E(e^{t|E_{\back}^\p(G,G')|}\cdot 1_{S_K,S_K' \in \cS_{\p}^{\back}}) &\leq 1+ O(N^{-\delta}),
            \end{aligned}
            \end{equation}
            hold for sufficiently large $N$.
            \item[\emph{(c)}] If the sequence $S_K \in \cS^{\dagger}$, where 
            \begin{equation}
                \cS^{\dagger}=\bigcap_{\p \in [k]_0} \lt( \cS_{\p}^{\for} \cap \cS_{\p}^{\back}\rt),
            \end{equation}
            then $S_K$ is $\vartheta$-regular.
        \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.972463+00:00","domain":"probability theory","id":"claim_f78ef8fb215d5ee5318c0dfb06224a2284ea8c661deecfca7eddfb53ad2cf02d","kind":"concept","schema_version":1,"statement":"[Lemma 13 of arXiv:2606.10313, '\textbf{Invariance principles for additive functionals of voter models}'] There exists $C_6<+\infty$ independent of $a, b, B^{\vec{s}}$ such that
\begin{align*}
\int_a^bds_1\int_a^{s_1}ds_2\int_a^{s_2}ds_3\int_a^{s_3}\left|\hat{\mathbb{E}}\left(1_{B^{\vec{s}}}\mathcal{J}^{\vec{s}}\right)\right|ds_4
\leq C_6(b-a)^2
\end{align*}
for any $0<a<b$ and $B^{\vec{s}}=\mathcal{E}_{lk, \hat{l}\hat{k}}^{\vec{s}}$ or $\mathcal{E}_{lkj}^{\vec{s}}$ for any different $l, k, j\in \{1, 2, 3, 4\}$ and $\{\hat{l}, \hat{k}\}=\{1, 2, 3, 4\}\setminus\{l, k\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:16:46.709252+00:00","domain":"probability theory","id":"claim_f79088fb294cfe8e11723eb9b25fae5b0cabf0d420a1b6e27cb14420d7137069","kind":"concept","schema_version":1,"statement":"[Theorem thrm:path of arXiv:2411.18749, 'A star is born: Explosive Crump--Mode--Jagers branching processes'] Recall $\mu_n^w$ from~(equation eq:mu of the paper). If, for some $c>1$ and all $w\geq 0$, we have 
	\begin{equation} 
	\sum_{n=1}^\infty \E{\prod_{i=0}^\infty \frac{f(i,W)}{f(i,W)+c(\mu_n^w)^{-1}\log n}}=\infty, 
	\end{equation} 
