         \quad \forall w\in H^{\gamma } (\mathbb{S}^n),
    \end{equation*}
    where $\mathcal{M}_{\mathbb{S}^n } = \{v \in H^\gamma (\mathbb{S}^n) : \mathcal{P}v \in \mathcal{M}_{\mathbb{R}^n} \} $ and $\mathcal{P}$ is the isometric isomorphism given by the stereographic projection. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.222780+00:00","domain":"probability theory","id":"claim_f9af146c2aeee89b8fefaeaf3cacc4d47705c2731930e858010b9e0c8a8f6f24","kind":"lemma","schema_version":1,"statement":"[Lemma pos_marginal_cannot_be_locmin of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Let $\nu\in \P(\X)$ and $\k\geq 2$. Fix  an 
