{"assumptions":[],"created_at":"2026-10-27T21:44:17.353212+00:00","domain":"probability theory","id":"claim_fdf94aab1bdbe36e92b114f388a273a809c00231962ac4c5f6a2b0cdfe5b450a","kind":"concept","schema_version":1,"statement":"[Lemma L2 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] {Karimireddy2020}}]

Let $\{X_1,\dots,X_\tau\}$ be a collection of $\mathbb{R}^d$-valued random variables that are potentially dependent. Suppose that $\mathbb{E}[X_i]=\mu_i$ and $\mathbb{E}[\|X_i-\mu_i\|^2]\leq\sigma^2$, $i=1,\dots,\tau$. Then
\begin{equation*}
\mathbb{E}\left[\left\|\sum_{i=1}^{\tau}X_i\right\|^2\right]\leq\left\|\sum_{i=1}^{\tau}\mu_i\right\|^2
+\tau^2\sigma^2.
\end{equation*}
Suppose that $\{\mathcal{G}_i\}_{i=0}^{\tau}$ is a filtration, i.e.,
\begin{equation*}
\mathcal{G}_0\subseteq\mathcal{G}_1\subseteq\cdots\subseteq\mathcal{G}_\tau
\end{equation*}
and that $X_i$ is $\mathcal{G}_i$-measurable for each $i=1,\dots,\tau$. Define
\begin{equation*}
\mu_i=\mathbb{E}\left[X_i\mid\mathcal{G}_{i-1}\right],
\end{equation*}
and suppose that
\begin{equation*}
\mathbb{E}\left[\|X_i-\mu_i\|^2\mid\mathcal{G}_{i-1}\right]\leq\sigma^2,\qquad i=1,\dots,\tau.
\end{equation*}
Then $\{X_i-\mu_i\}_{i=1}^{\tau}$ forms a martingale-difference sequence with respect to $\{\mathcal{G}_i\}_{i=0}^{\tau}$, and
\begin{equation*}
			\mathbb{E}\left[
			\left\|\sum_{i=1}^{\tau}X_i\right\|^2
			\right]
			\leq
			2\mathbb{E}\left[
			\left\|\sum_{i=1}^{\tau}\mu_i\right\|^2
			\right]
			+2\tau\sigma^2.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.436812+00:00","domain":"probability theory","id":"claim_fe043280d542329116106ea496f3b14aa64d495cdbbbf84b2281e3856dcffe90","kind":"lemma","schema_version":1,"statement":"[Lemma lem:independence-across-disjoint-balls of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] For each $M>0$, $p,q \in (0,1)$, and $s>0$, there exists $n_* = n_*(M,p,q,s) \in \BN$ such that the following is true. Let $x_1,\ldots,x_n \in \partial \BD$ with $n \geq n_*$. Let $r>0$. Suppose that $|x_j - x_k| \geq 2(s+1) r$ for all distinct $j,k \in [1,n]_{\BZ}$. Let also $\Psi$ be a GFF on $\BD$ with boundary conditions given by a measurable function bounded by $M$. Let $E_1,\ldots,E_n$ be a family of events such that each $E_j$ is measurable with respect to the $\sigma$-algebra generated by $\Psi|_{B_r(x_j) \cap \BD}$. Suppose that $\BP[E_j] \geq p$ for all $j \in [1,n]_{\BZ}$. Then
	\begin{equation*}
		\BP\!\left\lbrack\bigcup_{j = 1}^n E_j\right\rbrack \ge q. 
\end{equation*}","status":"unverified"}

